{"requestId":"f2c76711f8614d4fa8f04d3a444ace83","modelId":"hy3","modelName":"Hy3","isHelperMessage":false,"traceId":"8544cadc9e597878e7534fde7b2249f7","toolStatus":{"chatcmpl-tool-b77d583cbba2d40f":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/ui.c","offset":739,"limit":130},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/ui.c","content":"   739:/* ---------------- 背光亮度：LEDC PWM 驱动 LCD_BLK 引脚 ---------------- */
   740:/* BLK 原来是普通 GPIO 常亮，这里改成 PWM 输出，占空比即亮度 */
   741:#define BLK_PWM_FREQ_HZ   1000
   742:#define BLK_PWM_RES       LEDC_TIMER_10_BIT                 /* 分辨率 10bit -> 0..1023 */
   743:#define BLK_MAX_DUTY      ((1u << LEDC_TIMER_10_BIT) - 1u)
   744:#define BLK_MIN_PERCENT   10        /* 最低亮度，避免调到 0 后屏幕全黑 */
   745:#define BLK_DEFAULT_PERCENT 100
   746:
   747:static uint8_t   g_brightness = BLK_DEFAULT_PERCENT;
   748:static lv_obj_t *g_br_label   = NULL;   /* 百分比数字标签 */
   749:
   750:/* 设置背光亮度（percent: BLK_MIN_PERCENT ~ 100） */
   751:static void backlight_set(uint8_t percent)
   752:{
   753:    if (percent < BLK_MIN_PERCENT) percent = BLK_MIN_PERCENT;
   754:    if (percent > 100) percent = 100;
   755:    g_brightness = percent;
   756:    uint32_t duty = (uint32_t)BLK_MAX_DUTY * percent / 100;
   757:    /* 注意：不能用 ledc_set_duty_and_update()！
   758:     * 它属于 fade 系列的线程安全 API，内部会先检查 fade 服务是否已安装，
   759:     * 未安装时会直接返回 ESP_FAIL 并打印 "Fade service not installed"，
   760:     * 占空比根本不会写入（readback 一直是初始值）。
   761:     * ledc_set_duty + ledc_update_duty 走的是非 fade 通路，不需要 fade 服务。 */
   762:    esp_err_t e1 = ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0, duty);
   763:    esp_err_t e2 = ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0);
   764:    /* 注：不要在这里用 ledc_get_duty() 做校验。它直接读硬件 duty 寄存器，
   765:     * 而新占空比要等下一个 PWM 周期才生效，紧跟着读必然读到「上一次」的值，
   766:     * 看起来像没写进去，其实是正常现象。用示波器看波形最准。 */
   767:    if (e1 != ESP_OK || e2 != ESP_OK) {
   768:        ESP_LOGE("BLK", "duty %lu failed (set=%d upd=%d)", (unsigned long)duty, (int)e1, (int)e2);
   769:    }
   770:}
   771:
   772:/* 初始化 LEDC，把 LCD_BLK 接到 PWM 通道上 */
   773:static void backlight_init(void)
   774:{
   775:    ledc_timer_config_t tcfg = {
   776:        .speed_mode      = LEDC_LOW_SPEED_MODE,
   777:        .duty_resolution = BLK_PWM_RES,
   778:        .timer_num       = LEDC_TIMER_0,
   779:        .freq_hz         = BLK_PWM_FREQ_HZ,
   780:        .clk_cfg         = LEDC_AUTO_CLK,
   781:    };
   782:    ESP_ERROR_CHECK(ledc_timer_config(&tcfg));
   783:
   784:    /* 注意：intr_type 在新版 IDF 已废弃，不要赋值，否则会有编译告警 */
   785:    ledc_channel_config_t ccfg = {
   786:        .gpio_num   = LCD_BLK_GPIO,
   787:        .speed_mode = LEDC_LOW_SPEED_MODE,
   788:        .channel    = LEDC_CHANNEL_0,
   789:        .timer_sel  = LEDC_TIMER_0,
   790:        .duty       = BLK_MAX_DUTY,      /* 默认最亮 */
   791:        .hpoint     = 0,
   792:    };
   793:    ESP_ERROR_CHECK(ledc_channel_config(&ccfg));
   794:    ESP_LOGI("BLK", "LEDC ready: GPIO%d, %luHz, %dbit",
   795:             (int)LCD_BLK_GPIO,
   796:             (unsigned long)ledc_get_freq(LEDC_LOW_SPEED_MODE, LEDC_TIMER_0),
   797:             (int)LEDC_TIMER_10_BIT);
   798:}
   799:
   800:/* 亮度滑块回调 */
   801:static void brightness_cb(lv_event_t *e)
   802:{
   803:    lv_obj_t *sl = lv_event_get_target(e);
   804:    int v = lv_slider_get_value(sl);
   805:    backlight_set((uint8_t)v);
   806:    if (g_br_label) {
   807:        lv_label_set_text_fmt(g_br_label, "%d%%", v);
   808:    }
   809:}
   810:
   811:/* 设置界面：状态栏 + 返回栏（复用 make_app_screen）+ 亮度滑动条 */
   812:static void build_settings_screen(lv_obj_t *scr)
   813:{
   814:    lv_obj_t *cap = lv_label_create(scr);
   815:    lv_label_set_text(cap, "亮度");
   816:    lv_obj_set_style_text_font(cap, &lv_font_cn_16, 0);
   817:    lv_obj_set_style_text_color(cap, lv_color_white(), 0);
   818:    lv_obj_set_pos(cap, 16, 76);
   819:
   820:    g_br_label = lv_label_create(scr);
   821:    lv_label_set_text_fmt(g_br_label, "%d%%", g_brightness);
   822:    lv_obj_set_style_text_font(g_br_label, &lv_font_montserrat_20, 0);
   823:    lv_obj_set_style_text_color(g_br_label, lv_color_hex(0x9AA0B5), 0);
   824:    lv_obj_set_width(g_br_label, 60);
   825:    lv_obj_set_style_text_align(g_br_label, LV_TEXT_ALIGN_RIGHT, 0);
   826:    lv_obj_set_pos(g_br_label, 244, 76);
   827:
   828:    lv_obj_t *sl = lv_slider_create(scr);
   829:    lv_obj_set_size(sl, 288, 20);
   830:    lv_obj_set_pos(sl, 16, 116);
   831:    lv_slider_set_range(sl, BLK_MIN_PERCENT, 100);
   832:    lv_slider_set_value(sl, g_brightness, LV_ANIM_OFF);
   833:    lv_obj_set_scrollbar_mode(sl, LV_SCROLLBAR_MODE_OFF);
   834:    lv_obj_add_event_cb(sl, brightness_cb, LV_EVENT_VALUE_CHANGED, NULL);
   835:
   836:    /* 两端提示文字 */
   837:    lv_obj_t *mn = lv_label_create(scr);
   838:    lv_label_set_text(mn, "10%");
   839:    lv_obj_set_style_text_font(mn, &lv_font_montserrat_16, 0);
   840:    lv_obj_set_style_text_color(mn, lv_color_hex(0x9AA0B5), 0);
   841:    lv_obj_set_pos(mn, 16, 142);
   842:
   843:    lv_obj_t *mx = lv_label_create(scr);
   844:    lv_label_set_text(mx, "100%");
   845:    lv_obj_set_style_text_font(mx, &lv_font_montserrat_16, 0);
   846:    lv_obj_set_style_text_color(mx, lv_color_hex(0x9AA0B5), 0);
   847:    lv_obj_set_pos(mx, 268, 142);
   848:}
   849:
   850:/* 在 App 屏幕中央放一行占位文字 */
   851:static void add_placeholder(lv_obj_t *scr, const char *msg)
   852:{
   853:    lv_obj_t *l = lv_label_create(scr);
   854:    lv_label_set_text(l, msg);
   855:    lv_label_set_long_mode(l, LV_LABEL_LONG_WRAP);
   856:    lv_obj_set_width(l, LCD_W - 40);
   857:    lv_obj_set_style_text_font(l, &lv_font_cn_16, 0);
   858:    lv_obj_set_style_text_color(l, lv_color_hex(0x9AA0B5), 0);
   859:    lv_obj_align(l, LV_ALIGN_CENTER, 0, 0);
   860:}
   861:
   862:/* 主界面上的一个 App 按钮（真正的 lv_button，放在最顶层，固定且可点） */
   863:static lv_obj_t *make_app_button(lv_obj_t *parent, const lv_image_dsc_t *app_icon, const char *name,
   864:                                 lv_color_t color, int app_id)
   865:{
   866:    lv_obj_t *btn = lv_button_create(parent);
   867:    lv_obj_set_size(btn, 88, 88);
   868:    lv_obj_set_style_bg_opa(btn, LV_OPA_TRANSP, 0);     // 按钮本身透明，里面用色块当图标","totalLineCount":4031,"hasMore":true,"hint":""}}}}}

