    16:/* 天气调试日志开关：默认 0(关闭)。改 1 可打印 任务启动/唤醒 定位日志。
    17: * 注意: weather updated / geocode / forecast 失败 属功能日志，始终打印。 */
    18:#define WEATHER_DEBUG 0
    19:
    20:#define WX_DEFAULT_CITY "Shanghai"
    21:/* 手动指定城市：留空("")则自动定位（公网 IP，可能跨城市不准）；
    22: * 填城市名（如 "Shenzhen"）则固定使用该城市，走地理编码，结果最稳。 */
    23:#define WX_MANUAL_CITY "Shenzhen"
    24:/* 默认城市（上海）经纬度：地理编码失败时的回退值，保证天气仍能显示 */
    25:#define WX_DEF_LAT 31.2304
    26:#define WX_DEF_LON 121.4737
    27:/* Open-Meteo 免费、无需 API Key、支持 HTTPS；geocoding 把城市名转经纬度 */
    28:#define WX_GEO_URL "https://geocoding-api.open-meteo.com/v1/search?name=%s&count=1&language=en&format=json"
    29:#define WX_FC_URL  "https://api.open-meteo.com/v1/forecast?latitude=%.4f&longitude=%.4f&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m&timezone=auto"
    30:/* 自动定位：用设备公网 IP 获取城市与经纬度（城市级精度，免 API Key）。
    31: * ipinfo.io 返回 {"city":"...","loc":"lat,lon",...}；定位失败则回退默认城市。 */
    32:#define WX_LOC_URL "https://ipinfo.io/json"
    33:
    34:weather_data_t g_weather = {0};
    35:
    36:static SemaphoreHandle_t s_req_sem = NULL;
    37:static char s_req_city[40];
    38:static bool s_req_has_city = false;
    39:
    40:/* 自动定位得到的经纬度/城市（定位成功后缓存，避免每次刷新都打 IP 定位服务） */
    41:static double s_loc_lat = 0, s_loc_lon = 0;
    42:static char   s_loc_city[40];
    43:static bool   s_loc_valid = false;
    44:
    45:/* ---------------- 极简 JSON 取值（针对 Open-Meteo 固定结构） ---------------- */
    46:
    47:/* 找到 "key": 之后值的起始位置（要求 key 被双引号包裹，避免误命中值里的内容）。
    48: * 返回值可能是字符串（以 " 开头）或数值；由调用方按类型处理。
    49: * 用 from 指定搜索起点，便于 js_get_double 跳过同名字符串值后继续找下一个。 */
    50:static const char *js_find_val_from(const char *from, const char *key)
    51:{
    52:    size_t kl = strlen(key);
    53:    const char *p = from;
    54:    while ((p = strstr(p, key)) != NULL) {
    55:        if (p > from && p[-1] == '"' && p[kl] == '"') {
    56:            const char *c = p + kl + 1;
    57:            while (*c && *c != ':' && *c != '}' && *c != ',') c++;
    58:            if (*c == ':') {
    59:                const char *v = c + 1;
    60:                while (*v == ' ' || *v == '\t' || *v == '\n' || *v == '\r') v++;
    61:                return v;
    62:            }
    63:        }
    64:        p += kl;
    65:    }
    66:    return NULL;
    67:}
    68:
    69:static const char *js_find_val(const char *s, const char *key)
    70:{
    71:    return js_find_val_from(s, key);
    72:}
    73:
    74:static bool js_get_double(const char *s, const char *key, double *out)
    75:{
    76:    const char *from = s;
    77:    while (1) {
    78:        const char *v = js_find_val_from(from, key);
    79:        if (!v) {
    80:            return false;
    81:        }
    82:        /* Open-Meteo 在 current_units 里用同名键、但值是字符串单位（如 "°C"），
    83:         * 跳过字符串型值，继续找下一个同名键，直到命中数值那次。 */
    84:        if (*v == '"') {
    85:            from = v + 1;
    86:            continue;
    87:        }
    88:        char *end = NULL;
    89:        double val = strtod(v, &end);
    90:        if (end == v) {                       /* 没解析到数字，继续找下一个 */
    91:            from = v + 1;
    92:            continue;
    93:        }
    94:        *out = val;
    95:        return true;
    96:    }
    97:}
    98:
    99:static bool js_get_str(const char *s, const char *key, char *out, size_t n)
   100:{
   101:    const char *v = js_find_val(s, key);
   102:    if (!v || *v != '"') {
   103:        return false;
   104:    }
   105:    const char *q = v + 1;
   106:    size_t i = 0;
   107:    while (*q && *q != '"' && i + 1 < n) {
   108:        out[i++] = *q++;
   109:    }
   110:    out[i] = '\0';
   111:    return i > 0;
   112:}
