   129:        case 61: s = "小雨"; break;
   130:        case 63: s = "中雨"; break;
   131:        case 65: s = "大雨"; break;
   132:        case 66: case 67: s = "冻雨"; break;
   133:        case 71: s = "小雪"; break;
   134:        case 73: s = "中雪"; break;
   135:        case 75: s = "大雪"; break;
   136:        case 77: s = "米雪"; break;
   137:        case 80: s = "小阵雨"; break;
   138:        case 81: s = "中阵雨"; break;
   139:        case 82: s = "暴雨"; break;
   140:        case 85: s = "小阵雪"; break;
   141:        case 86: s = "强阵雪"; break;
   142:        case 95: s = "雷阵雨"; break;
   143:        case 96: case 99: s = "雷阵雨伴冰雹"; break;
   144:        default: s = "未知"; break;
   145:    }
   146:    strncpy(out, s, n - 1);
