   194:/* 把 URL 里的空格做最简单编码（%20），避免城市名带空格时请求失败 */
   195:static void url_encode_spaces(char *url, size_t cap)
   196:{
   197:    for (size_t i = 0; url[i]; ) {
   198:        if (url[i] == ' ') {
   199:            size_t rest = strlen(url + i);
   200:            if (rest + 2 < cap - i) {
   201:                memmove(url + i + 3, url + i + 1, rest); /* 右移 2 字节腾出 %20 */
   202:                url[i] = '%'; url[i + 1] = '2'; url[i + 2] = '0';
   203:                i += 3;
   204:            } else {
   205:                break;
   206:            }
   207:        } else {
   208:            i++;
   209:        }
   210:    }
   211:}
