   213:/* 自动定位：用设备公网 IP 获取城市与经纬度（城市级精度，免 API Key）。
   214: * ipinfo.io 返回 {"city":"...","loc":"lat,lon",...}；失败返回 false。 */
   215:static bool auto_locate(double *lat, double *lon, char *city, size_t n)
   216:{
   217:    char buf[256];
   218:    if (http_get(WX_LOC_URL, buf, sizeof(buf)) != ESP_OK) {
   219:        return false;
   220:    }
   221:    char loc[40];
   222:    if (!js_get_str(buf, "loc", loc, sizeof(loc))) {
   223:        return false;
   224:    }
   225:    if (sscanf(loc, "%lf,%lf", lat, lon) != 2) {
   226:        return false;
   227:    }
   228:    if (!js_get_str(buf, "city", city, n)) {
   229:        strncpy(city, "Unknown", n - 1);
   230:        city[n - 1] = '\0';
   231:    }
   232:    ESP_LOGI(TAG, "auto locate: %s (%.4f, %.4f)", city, *lat, *lon);
   233:    return true;
   234:}
