   236:static void weather_task(void *arg)
   237:{
   238:    (void)arg;
   239:    /* 用 static 缓冲，避免大响应体占用任务栈（TLS 握手本身栈消耗不小） */
   240:    static char geo[2048];
   241:    static char fc[2048];
   242:
   243:    for (;;) {
   244:        xSemaphoreTake(s_req_sem, portMAX_DELAY);
   245:#if WEATHER_DEBUG
   246:        ESP_LOGI(TAG, "weather task woke, wifi_state=%d", g_wifi_state);
   247:#endif
   248:
   249:        if (g_wifi_state != WIFI_STA_CONNECTED) {
   250:            ESP_LOGW(TAG, "WiFi not connected, skip weather fetch");
   251:            continue;
   252:        }
   253:
   254:        g_weather.fetching = true;
   255:
   256:        /* 1) 确定经纬度与城市名
   257:         *    - 指定了城市（UI 传入或下方 WX_MANUAL_CITY 配置）：走地理编码
   258:         *    - 都未指定：自动定位（公网 IP -> 城市/经纬度），成功则缓存；
   259:         *      失败再回退到默认城市“Shanghai”的地理编码 */
   260:        double lat = WX_DEF_LAT, lon = WX_DEF_LON;
   261:        char cname[40];
   262:
   263:        const char *city = s_req_has_city ? s_req_city
   264:                                          : (WX_MANUAL_CITY[0] ? WX_MANUAL_CITY : NULL);
   265:
   266:        if (city) {
   267:            strncpy(cname, city, sizeof(cname) - 1);
   268:            cname[sizeof(cname) - 1] = '\0';
   269:
   270:            char geo_url[256];
   271:            snprintf(geo_url, sizeof(geo_url), WX_GEO_URL, city);
   272:            url_encode_spaces(geo_url, sizeof(geo_url));
   273:
   274:            esp_err_t geo_err = http_get(geo_url, geo, sizeof(geo));
   275:            if (geo_err == ESP_OK &&
   276:                js_get_double(geo, "latitude", &lat) &&
   277:                js_get_double(geo, "longitude", &lon) &&
   278:                js_get_str(geo, "name", cname, sizeof(cname))) {
   279:                ESP_LOGI(TAG, "geocode ok: %s (%.4f, %.4f)", cname, lat, lon);
   280:            } else {
   281:                if (geo_err == ESP_OK) {
   282:                    ESP_LOGW(TAG, "geocode parse failed, body: %.*s",
   283:                             (int)strnlen(geo, 160), geo);
   284:                }
   285:                ESP_LOGW(TAG, "geocode failed for '%s', fallback to default coords", city);
   286:            }
   287:        } else {
   288:            if (s_loc_valid) {
   289:                lat = s_loc_lat; lon = s_loc_lon;
   290:                strncpy(cname, s_loc_city, sizeof(cname) - 1);
   291:                cname[sizeof(cname) - 1] = '\0';
   292:                ESP_LOGI(TAG, "use cached location: %s (%.4f, %.4f)", cname, lat, lon);
   293:            } else if (auto_locate(&lat, &lon, cname, sizeof(cname))) {
   294:                s_loc_lat = lat; s_loc_lon = lon;
   295:                strncpy(s_loc_city, cname, sizeof(s_loc_city) - 1);
   296:                s_loc_city[sizeof(s_loc_city) - 1] = '\0';
   297:                s_loc_valid = true;
   298:            } else {
   299:                /* 自动定位失败，回退到默认城市地理编码 */
   300:                strncpy(cname, WX_DEFAULT_CITY, sizeof(cname) - 1);
   301:                cname[sizeof(cname) - 1] = '\0';
   302:
   303:                char geo_url[256];
   304:                snprintf(geo_url, sizeof(geo_url), WX_GEO_URL, WX_DEFAULT_CITY);
   305:                url_encode_spaces(geo_url, sizeof(geo_url));
   306:
   307:                esp_err_t geo_err = http_get(geo_url, geo, sizeof(geo));
   308:                if (geo_err == ESP_OK &&
   309:                    js_get_double(geo, "latitude", &lat) &&
   310:                    js_get_double(geo, "longitude", &lon) &&
   311:                    js_get_str(geo, "name", cname, sizeof(cname))) {
   312:                    ESP_LOGI(TAG, "geocode ok (fallback): %s (%.4f, %.4f)", cname, lat, lon);
   313:                } else {
   314:                    if (geo_err == ESP_OK) {
   315:                        ESP_LOGW(TAG, "geocode parse failed, body: %.*s",
   316:                                 (int)strnlen(geo, 160), geo);
   317:                    }
   318:                    ESP_LOGW(TAG, "auto locate & geocode failed, use default coords");
   319:                }
   320:            }
   321:        }
   322:
   323:        /* 2) 当前天气：经纬度 -> 实况 */
   324:        char fc_url[256];
   325:        snprintf(fc_url, sizeof(fc_url), WX_FC_URL, lat, lon);
   326:
   327:        double temp = 0, hum = 0, wind = 0, d_code = 0;
   328:        esp_err_t fc_err = http_get(fc_url, fc, sizeof(fc));
   329:        if (fc_err == ESP_OK &&
   330:            js_get_double(fc, "temperature_2m", &temp) &&
   331:            js_get_double(fc, "relative_humidity_2m", &hum) &&
   332:            js_get_double(fc, "weather_code", &d_code) &&
   333:            js_get_double(fc, "wind_speed_10m", &wind)) {
   334:
   335:            g_weather.temp     = (float)temp;
   336:            g_weather.humidity = (int)hum;
   337:            g_weather.code     = (int)d_code;
   338:            g_weather.wind     = (float)wind;
   339:            strncpy(g_weather.city, cname, sizeof(g_weather.city) - 1);
   340:            g_weather.city[sizeof(g_weather.city) - 1] = '\0';
   341:            wmo_desc(g_weather.code, g_weather.desc, sizeof(g_weather.desc));
   342:            g_weather.updated_ms = esp_timer_get_time() / 1000;
   343:            g_weather.valid   = true;
   344:            g_weather.error   = false;
   345:            g_weather.version++;
   346:            ESP_LOGI(TAG, "weather updated: %s %.1fC %s (RH %d%%, wind %.1f km/h)",
   347:                     cname, temp, g_weather.desc, g_weather.humidity, wind);
   348:        } else {
   349:            if (fc_err == ESP_OK) {
   350:                ESP_LOGW(TAG, "forecast parse failed, body: %.*s",
   351:                         (int)strnlen(fc, 160), fc);
   352:            }
   353:            g_weather.error = true;
   354:            ESP_LOGW(TAG, "forecast fetch/parse failed");
   355:        }
   356:
   357:        g_weather.fetching = false;
   358:    }
   359:}
