   361:void weather_init(void)
   362:{
   363:    s_req_sem = xSemaphoreCreateBinary();
   364:    /* 栈放 PSRAM：HTTPS 抓取需 ~32KB 栈，若放内部 RAM 会和 LVGL 的两块 38400B
   365:     * draw_buf 互相挤占，导致任一方分配失败(屏幕卡死 / 任务没建却打了 started)。
   366:     * PSRAM 充裕(>800KB)，把任务栈放那里，屏幕与天气两者兼顾。 */
   367:    BaseType_t ok = xTaskCreateWithCaps(weather_task, "weather", 32768, NULL, 3, NULL,
   368:                                        MALLOC_CAP_SPIRAM);
   369:    if (ok != pdPASS) {
   370:        /* 极端情况 PSRAM 也失败：降档用内部 RAM 小栈兜底 */
   371:        ESP_LOGE(TAG, "PSRAM-stack task create failed (%d), retry internal @24KB", (int)ok);
   372:        ok = xTaskCreate(weather_task, "weather", 24576, NULL, 3, NULL);
   373:    }
   374:#if WEATHER_DEBUG
   375:    ESP_LOGI(TAG, "weather task started (create=%d)", (int)ok);
   376:#endif
   377:}
