   379:void weather_request(const char *city)
   380:{
   381:    if (city && city[0]) {
   382:        strncpy(s_req_city, city, sizeof(s_req_city) - 1);
   383:        s_req_city[sizeof(s_req_city) - 1] = '\0';
   384:        s_req_has_city = true;
   385:    } else {
   386:        s_req_has_city = false;
   387:    }
   388:    if (s_req_sem) {
   389:        xSemaphoreGive(s_req_sem);
   390:    }
   391:}
