    if (!scr) return;
    ui_switch(scr, false);      /* 进 App：新屏从右边压进来 */
    g_active_app = id;
    /* 系统信息定时器仅在“关于本机”屏可见时运行，进出时启停避免常驻空刷 */
    if (g_sysinfo_timer) {
        if (id == APP_SYSINFO) lv_timer_resume(g_sysinfo_timer);
        else                   lv_timer_pause(g_sysinfo_timer);
    }
}

/* 供 pvz.c 等外部界面调用: 跳回主界面（往回退，方向相反） */
