    pc_mon_set_active(false);   /* 离开 App 界面，停止监控数据拉取 */
    g_active_app = APP_NONE;
    if (g_sysinfo_timer) lv_timer_pause(g_sysinfo_timer);
    ui_switch(g_home, true);    /* 回主页：主页从左边推回来 */
}","explanation":"在进出 App 时记录当前 App 并启停系统信息定时器。"}}]}

