   196:     * LV_FS_POSIX_LETTER / LV_FS_POSIX_PATH）。之后 lv_image_set_src(img, "S:/dir/a.jpg")
   197:     * 就能直接解码显示 SD 卡里的图。
   198:     * 注意：lv_init() 内部已经调用过 lv_fs_posix_init()（见 lv_init.c），
   199:     * 这里不能再注册一次，否则同一个盘符会被注册两遍。 */
   200:
   201:    /* 给 LVGL 追加内存池：优先 PSRAM，失败则退回内部 DRAM，并逐级降容量重试。
   202:     * 必须在 lv_init() 之后调用。 */
   203:    size_t added = lvgl_add_mem_pool(MALLOC_CAP_SPIRAM, "PSRAM");
   204:    if (added == 0) {
   205:        ESP_LOGW(TAG, "PSRAM pool unavailable, falling back to internal DRAM");
   206:        added = lvgl_add_mem_pool(MALLOC_CAP_INTERNAL, "INTERNAL");
   207:    }
   208:
   209:    /* 自验证：打印挂池后 LVGL 的实际总内存，确认是否真的生效 */
   210:    lv_mem_monitor_t mon;
   211:    lv_mem_monitor(&mon);
   212:    ESP_LOGI(TAG, "LVGL total memory = %u bytes (extra pool added = %u)",
   213:             (unsigned)mon.total_size, (unsigned)added);
   214:
   215:    /* 图片解码结果（整帧 ARGB8888）改用系统 PSRAM，别挤 LVGL 池 */
   216:    lv_draw_buf_handlers_t * img_hd = lv_draw_buf_get_image_handlers();
   217:    if (img_hd) {
   218:        img_hd->buf_malloc_cb = img_buf_malloc;
   219:        img_hd->buf_free_cb   = img_buf_free;
   220:        ESP_LOGI(TAG, "图片解码帧改走系统 PSRAM（LVGL 池只留文件+扫描线）");
   221:    }
   222:
   223:    /* 分配两个内部 RAM draw buf (PARTIAL 模式)。
   224:     * 优先 MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA, 满足 GDMA 对源缓冲的可访问性要求。 */
   225:    s_draw_buf1 = heap_caps_malloc(DISP_BUF_SIZE, MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA);
   226:    s_draw_buf2 = heap_caps_malloc(DISP_BUF_SIZE, MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA);
   227:    if (!s_draw_buf1 || !s_draw_buf2) {
   228:        ESP_LOGE(TAG, "internal RAM draw buf alloc failed (need %u bytes each)",
   229:                 (unsigned)DISP_BUF_SIZE);
   230:        return;
   231:    }
   232:    ESP_LOGI(TAG, "draw_buf1 @ %p, draw_buf2 @ %p, each %u bytes (internal RAM)",
   233:             s_draw_buf1, s_draw_buf2, (unsigned)DISP_BUF_SIZE);
   234:
   235:    /* 注册显示驱动: PARTIAL 模式 + 双 draw buf。
   236:     * LVGL 只渲染脏区到 draw buf, flush_cb 把这块 DMA 到屏幕对应坐标。 */
   237:    s_disp = lv_display_create(LCD_W, LCD_H);
   238:    lv_display_set_buffers(s_disp, s_draw_buf1, s_draw_buf2,
   239:                           DISP_BUF_SIZE, LV_DISPLAY_RENDER_MODE_PARTIAL);
   240:    lv_display_set_flush_cb(s_disp, disp_flush_cb);
   241:    lv_display_set_rotation(s_disp, LV_DISP_ROTATION_0);
   242:
   243:    /* 注册 DMA 完成中断回调, 由它异步通知 LVGL 渲染下一块。
   244:     * PARTIAL 模式下每块脏区 DMA 完成都触发此回调。 */
   245:    lcd_set_color_trans_done_cb(on_color_trans_done_cb, NULL);
