/* ================= 计算器 ================= */
static lv_obj_t *g_calc_disp = NULL;
static char      c_buf[24] = "0";
static int       c_op = 0;      /* 0 无, 11 +, 12 -, 13 *, 14 / */
static double    c_acc = 0;
static bool      c_fresh = true;

static void calc_show(void)
{
    double cur = atof(c_buf);
    double v = (c_op && c_fresh) ? c_acc : cur;
    char buf[32];
    if (v == (long)v) snprintf(buf, sizeof(buf), "%.0f", v);
    else              snprintf(buf, sizeof(buf), "%.4f", v);
    lv_label_set_text(g_calc_disp, buf);
}
static void calc_reset(void)
{
    strcpy(c_buf, "0"); c_acc = 0; c_op = 0; c_fresh = true; calc_show();
}
static double calc_apply(double a, int op, double b)
{
    switch (op) {
        case 11: return a + b;
        case 12: return a - b;
        case 13: return a * b;
        case 14: return (b == 0) ? 0 : a / b;
    }
    return b;
}
static void calc_input(int key)
{
    if (key >= 0 && key <= 9) {
        if (c_fresh) { c_buf[0] = (char)('0' + key); c_buf[1] = 0; c_fresh = false; }
        else if (strlen(c_buf) < 23) { size_t n = strlen(c_buf); c_buf[n] = (char)('0' + key); c_buf[n+1] = 0; }
        calc_show();
    } else if (key == 10) {                       /* 小数点 */
        if (c_fresh) { strcpy(c_buf, "0."); c_fresh = false; }
        else if (strchr(c_buf, '.') == NULL) strcat(c_buf, ".");
        calc_show();
    } else if (key >= 11 && key <= 14) {          /* 运算符 */
        double cur = atof(c_buf);
        if (c_op) c_acc = calc_apply(c_acc, c_op, cur);
        else      c_acc = cur;
        c_op = key; c_fresh = true; calc_show();
    } else if (key == 15) {                        /* 等号 */
        if (c_op) { double cur = atof(c_buf); c_acc = calc_apply(c_acc, c_op, cur); c_op = 0; }
        snprintf(c_buf, sizeof(c_buf), "%.6g", c_acc);
        c_fresh = true; calc_show();
    } else if (key == 99) {                        /* C 清除 */
        calc_reset();
    }
}
static void calc_key_cb(lv_event_t *e)
{
    calc_input((int)(intptr_t)lv_event_get_user_data(e));
}
