static void tm_fmt(int64_t us, char *buf)
{
    if (us < 0) us = 0;
    int ms = (int)((us / 10000) % 100);
    int s  = (int)((us / 1000000) % 60);
    int m  = (int)(us / 60000000);
    snprintf(buf, 32, "%02d:%02d.%02d", m, s, ms);
