  3523:/* Weather 屏：数据有变化才刷新界面 */
  3524:static void ui_weather_screen_refresh(void)
  3525:{
  3526:    lv_obj_t *active = lv_screen_active();
  3527:    if (!g_weather_screen || active != g_weather_screen || !g_wx_temp) return;
  3528:
  3529:    bool changed = (g_weather.version != s_wx_shown_ver) ||
  3530:                   (g_weather.fetching != s_wx_fetching) ||
  3531:                   s_wx_need_redraw ||
  3532:                   (g_wifi_state != s_wx_wifi_state);
  3533:    if (!changed) return;
  3534:
  3535:    s_wx_need_redraw = false;
  3536:    s_wx_shown_ver = g_weather.version;
  3537:    s_wx_fetching  = g_weather.fetching;
  3538:    s_wx_wifi_state = g_wifi_state;
  3539:
  3540:    if (g_wifi_state != WIFI_STA_CONNECTED) {
  3541:        lv_label_set_text(g_wx_city, "--");
  3542:        lv_label_set_text(g_wx_temp, "--.- °C");
  3543:        lv_label_set_text(g_wx_desc, "WiFi 未连接");
  3544:        lv_label_set_text(g_wx_extra, "请先连接 WiFi 后点刷新");
  3545:        lv_label_set_text(g_wx_updated, "");
  3546:        return;
  3547:    }
  3548:    char buf[48];
  3549:    if (g_weather.fetching) {
  3550:        lv_label_set_text(g_wx_updated, "更新中...");
  3551:    } else if (g_weather.valid) {
  3552:        lv_label_set_text(g_wx_city, g_weather.city);
  3553:        snprintf(buf, sizeof(buf), "%.1f °C", g_weather.temp);
  3554:        lv_label_set_text(g_wx_temp, buf);
  3555:        lv_label_set_text(g_wx_desc, g_weather.desc);
  3556:        snprintf(buf, sizeof(buf), "湿度 %d%%   风速 %.1f km/h",
  3557:                 g_weather.humidity, g_weather.wind);
  3558:        lv_label_set_text(g_wx_extra, buf);
  3559:        int ago_s = (int)((esp_timer_get_time() / 1000 - g_weather.updated_ms) / 1000);
  3560:        if (ago_s < 0) ago_s = 0;
  3561:        snprintf(buf, sizeof(buf), "%d 秒前更新", ago_s);
  3562:        lv_label_set_text(g_wx_updated, buf);
  3563:    } else if (g_weather.error) {
  3564:        lv_label_set_text(g_wx_desc, "获取失败");
  3565:        lv_label_set_text(g_wx_updated, "请检查网络");
  3566:    }
  3567:}
