  3569:/* 电脑监控屏：数据有变化才刷新界面（每秒一次） */
  3570:static void ui_pcmon_screen_refresh(void)
  3571:{
  3572:    lv_obj_t *active = lv_screen_active();
  3573:    if (!g_pcmon_screen || active != g_pcmon_screen) return;
  3574:
  3575:    if (g_pcmon.version == s_pcmon_shown_ver && !g_pcmon.error) return;
  3576:    s_pcmon_shown_ver = g_pcmon.version;
  3577:
  3578:    char buf[64];
  3579:    for (int i = 0; i < PC_MON_MAX_SENSORS; i++) {
  3580:        if (i < g_pcmon.count) {
  3581:            const pc_sensor_t *s = &g_pcmon.sensors[i];
  3582:            if (s->unit[0])
  3583:                snprintf(buf, sizeof(buf), "%s: %s %s", s->label, s->value, s->unit);
  3584:            else
  3585:                snprintf(buf, sizeof(buf), "%s: %s", s->label, s->value);
  3586:            lv_label_set_text(g_pcmon_labels[i], buf);
  3587:        } else {
  3588:            lv_label_set_text(g_pcmon_labels[i], "");
  3589:        }
  3590:    }
  3591:
  3592:    if (g_pcmon.error) {
  3593:        lv_label_set_text(g_pcmon_status, "连接失败，请检查 PC 服务端");
  3594:    } else if (g_pcmon.valid) {
  3595:        int ago_s = (int)((esp_timer_get_time() / 1000 - g_pcmon.updated_ms) / 1000);
  3596:        if (ago_s < 0) ago_s = 0;
  3597:        snprintf(buf, sizeof(buf), "已连接 · %d 秒前更新", ago_s);
  3598:        lv_label_set_text(g_pcmon_status, buf);
  3599:    } else {
  3600:        lv_label_set_text(g_pcmon_status, "等待连接...");
  3601:    }
  3602:}
