  3734:/* ================= 计算器 ================= */
  3735:static lv_obj_t *g_calc_disp = NULL;
  3736:static char      c_buf[24] = "0";
  3737:static int       c_op = 0;      /* 0 无, 11 +, 12 -, 13 *, 14 / */
  3738:static double    c_acc = 0;
  3739:static bool      c_fresh = true;
  3740:
  3741:static void calc_show(void)
  3742:{
  3743:    double cur = atof(c_buf);
  3744:    double v = (c_op && c_fresh) ? c_acc : cur;
  3745:    char buf[32];
  3746:    if (v == (long)v) snprintf(buf, sizeof(buf), "%.0f", v);
  3747:    else              snprintf(buf, sizeof(buf), "%.4f", v);
  3748:    lv_label_set_text(g_calc_disp, buf);
  3749:}
  3750:static void calc_reset(void)
  3751:{
  3752:    strcpy(c_buf, "0"); c_acc = 0; c_op = 0; c_fresh = true; calc_show();
  3753:}
  3754:static double calc_apply(double a, int op, double b)
  3755:{
  3756:    switch (op) {
  3757:        case 11: return a + b;
  3758:        case 12: return a - b;
  3759:        case 13: return a * b;
  3760:        case 14: return (b == 0) ? 0 : a / b;
  3761:    }
  3762:    return b;
  3763:}
  3764:static void calc_input(int key)
  3765:{
  3766:    if (key >= 0 && key <= 9) {
  3767:        if (c_fresh) { c_buf[0] = (char)('0' + key); c_buf[1] = 0; c_fresh = false; }
  3768:        else if (strlen(c_buf) < 23) { size_t n = strlen(c_buf); c_buf[n] = (char)('0' + key); c_buf[n + 1] = 0; }
  3769:        calc_show();
  3770:    } else if (key == 10) {                       /* 小数点 */
  3771:        if (c_fresh) { strcpy(c_buf, "0."); c_fresh = false; }
  3772:        else if (strchr(c_buf, '.') == NULL) strcat(c_buf, ".");
  3773:        calc_show();
  3774:    } else if (key >= 11 && key <= 14) {          /* 运算符 */
  3775:        double cur = atof(c_buf);
  3776:        if (c_op) c_acc = calc_apply(c_acc, c_op, cur);
  3777:        else      c_acc = cur;
  3778:        c_op = key; c_fresh = true; calc_show();
  3779:    } else if (key == 15) {                        /* 等号 */
  3780:        if (c_op) { double cur = atof(c_buf); c_acc = calc_apply(c_acc, c_op, cur); c_op = 0; }
  3781:        snprintf(c_buf, sizeof(c_buf), "%.6g", c_acc);
  3782:        c_fresh = true; calc_show();
  3783:    } else if (key == 99) {                        /* C 清除 */
  3784:        calc_reset();
  3785:    }
  3786:}
  3787:static void calc_key_cb(lv_event_t *e)
  3788:{
  3789:    calc_input((int)(intptr_t)lv_event_get_user_data(e));
  3790:}
