  3873:static void tm_fmt(int64_t us, char *buf)
  3874:{
  3875:    if (us < 0) us = 0;
  3876:    int ms = (int)((us / 10000) % 100);
  3877:    int s  = (int)((us / 1000000) % 60);
  3878:    int m  = (int)(us / 60000000);
  3879:    snprintf(buf, 32, "%02d:%02d.%02d", m, s, ms);
  3880:}
  3881:static int64_t tm_current(void)
  3882:{
  3883:    if (tm_state != TM_RUN) return tm_acc_us;
  3884:    int64_t d = esp_timer_get_time() - tm_start_us;
  3885:    return (tm_mode == 0) ? (tm_acc_us + d) : (tm_acc_us - d);
  3886:}
  3887:static void tm_refresh(void)
  3888:{
  3889:    char buf[32]; tm_fmt(tm_current(), buf);
  3890:    lv_label_set_text(g_tm_disp, buf);
  3891:}
  3892:static void tm_set_mode(int m)
  3893:{
  3894:    tm_mode = m; tm_state = TM_STOP; tm_lap = 0;
  3895:    tm_acc_us = (m == 1) ? (int64_t)tm_set_sec * 1000000 : 0;
  3896:    lv_label_set_text(lv_obj_get_child(g_tm_mode_btn[0], 0), m == 0 ? ">秒表" : "秒表");
  3897:    lv_label_set_text(lv_obj_get_child(g_tm_mode_btn[1], 0), m == 1 ? ">倒计时" : "倒计时");
  3898:    lv_label_set_text(g_tm_btnC_lbl, m == 0 ? "计次" : "+1:00");
  3899:    lv_label_set_text(g_tm_btnA_lbl, "开始");
  3900:    lv_label_set_text(g_tm_info, m == 1 ? "设定 05:00" : "");
  3901:    tm_refresh();
  3902:}
