   756:/* ---------------- 背光亮度：LEDC PWM 驱动 LCD_BLK 引脚 ---------------- */
   757:/* BLK 原来是普通 GPIO 常亮，这里改成 PWM 输出，占空比即亮度 */
   758:#define BLK_PWM_FREQ_HZ   1000
   759:#define BLK_PWM_RES       LEDC_TIMER_10_BIT                 /* 分辨率 10bit -> 0..1023 */
   760:#define BLK_MAX_DUTY      ((1u << LEDC_TIMER_10_BIT) - 1u)
   761:#define BLK_MIN_PERCENT   10        /* 最低亮度，避免调到 0 后屏幕全黑 */
   762:#define BLK_DEFAULT_PERCENT 100
