   764:static uint8_t   g_brightness = BLK_DEFAULT_PERCENT;
   765:static lv_obj_t *g_br_label   = NULL;   /* 百分比数字标签 */
   766:
   767:/* 设置背光亮度（percent: BLK_MIN_PERCENT ~ 100） */
   768:static void backlight_set(uint8_t percent)
   769:{
   770:    if (percent < BLK_MIN_PERCENT) percent = BLK_MIN_PERCENT;
   771:    if (percent > 100) percent = 100;
   772:    g_brightness = percent;
   773:    uint32_t duty = (uint32_t)BLK_MAX_DUTY * percent / 100;
   774:    /* 注意：不能用 ledc_set_duty_and_update()！
   775:     * 它属于 fade 系列的线程安全 API，内部会先检查 fade 服务是否已安装，
   776:     * 未安装时会直接返回 ESP_FAIL 并打印 "Fade service not installed"，
   777:     * 占空比根本不会写入（readback 一直是初始值）。","totalLineCount":4483,"hasMore":true,"hint":""}}}}}

