/* ================= 计算器 ================= */
static lv_obj_t *g_calc_disp = NULL;
static char      c_buf[24] = "0";
static int       c_op = 0;      /* 0 无, 11 +, 12 -, 13 *, 14 / */
static double    c_acc = 0;
