    lv_obj_set_style_text_font(g_tm_btnC_lbl, &lv_font_cn_16, 0); lv_obj_center(g_tm_btnC_lbl);
    lv_obj_add_event_cb(bC, tm_btnC_cb, LV_EVENT_CLICKED, NULL);","new_str":"    lv_obj_t *bC = lv_button_create(row); lv_obj_set_size(bC, (LCD_W - 20 - 16) / 3, 36);
