    15:static const char *TAG = "SD";
    16:
    17:/* SDMMC 的每一次命令传输都要临时申请一小块 DMA 内存（内部 SRAM）。
    18: * 若此时内部 RAM 被吃光，就会报 sdmmc_send_cmd_send_scr: not enough mem (0x101)，
    19: * 连 8 字节都申请不到。打印各区域余量，便于定位到底是哪块内存不够。 */
    20:static void sd_log_heap(const char *when)
    21:{
    22:    ESP_LOGI(TAG, "[%s] 内存: 内部 free=%u/largest=%u  DMA free=%u/largest=%u  PSRAM free=%u",
    23:             when,
    24:             (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL),
    25:             (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL),
    26:             (unsigned)heap_caps_get_free_size(MALLOC_CAP_DMA),
    27:             (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_DMA),
    28:             (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    29:}
    30:
    31:sd_card_info_t g_sdcard = {0};
    32:
    33:static sdmmc_card_t *s_card = NULL;
    34:
    35:/* 按指定总线宽度初始化 SDMMC 主机并挂载 FATFS。
    36: * 1 线模式把 D1~D3 显式设成 NC，避免误用默认引脚。 */
    37:static esp_err_t mount_with_width(int width, int freq_khz)
    38:{
    39:    esp_vfs_fat_sdmmc_mount_config_t mount_cfg = {
    40:        .format_if_mount_failed = false,   /* 绝不格式化用户的数据 */
    41:        .max_files              = 5,
    42:        .allocation_unit_size   = 16 * 1024,
    43:        .disk_status_check_enable = false,
    44:        .use_one_fat            = false,
    45:    };
    46:
    47:    sdmmc_host_t host = SDMMC_HOST_DEFAULT();
    48:    host.max_freq_khz = freq_khz;
    49:
    50:    sdmmc_slot_config_t slot = SDMMC_SLOT_CONFIG_DEFAULT();
    51:    slot.width = width;
    52:    slot.clk   = (gpio_num_t)SDMMC_PIN_CLK;
    53:    slot.cmd   = (gpio_num_t)SDMMC_PIN_CMD;
    54:    slot.d0    = (gpio_num_t)SDMMC_PIN_D0;
    55:    if (width >= 4) {
    56:        slot.d1 = (gpio_num_t)SDMMC_PIN_D1;
    57:        slot.d2 = (gpio_num_t)SDMMC_PIN_D2;
    58:        slot.d3 = (gpio_num_t)SDMMC_PIN_D3;
    59:    } else {
    60:        slot.d1 = GPIO_NUM_NC;
    61:        slot.d2 = GPIO_NUM_NC;
    62:        slot.d3 = GPIO_NUM_NC;
    63:    }
