  1908:/* ===================== 音乐播放（伪实现） =====================
  1909: * 需求：能从 SD 卡读到音频文件、能「播放」、有进度。
  1910: * 伪实现：扫描 /sdcard 下的音频文件，点列表即选曲；用定时器按真实时间推进进度条，
  1911: *         到尾自动下一首。不解码、不占用任何音频引脚、不真正出声。
  1912: * TODO（引脚确定后）：在 music_play() 里初始化 MP3 解码器，并把 music_timer_cb 里
  1913: *       的「定时器伪推进」改成「读一帧 PCM → 经 I2S 送到 DAC/功放」，即可真正出声。
  1914: * ============================================================== */
  1915:#define MUSIC_MAX_FILES   64
  1916:#define MUSIC_DIR         "/sdcard"
  1917:
  1918:static char       g_music_files[MUSIC_MAX_FILES][384];
  1919:static int        g_music_count = 0;
  1920:static int        g_music_cur   = -1;
  1921:static int        g_music_pos   = 0;     /* 已播放毫秒（伪） */
  1922:static int        g_music_dur   = 0;     /* 曲目总时长（秒，估算） */
  1923:static bool       g_music_playing = false;
  1924:static uint32_t   g_music_tick = 0;      /* 上次推进时的 lv_tick（ms） */
  1925:static lv_timer_t *s_music_timer = NULL;
  1926:
  1927:static lv_obj_t  *g_music_title  = NULL;
  1928:static lv_obj_t  *g_music_slider = NULL;
  1929:static lv_obj_t  *g_music_time   = NULL;
  1930:static lv_obj_t  *g_music_time_r = NULL;   /* 进度条右侧：总时长 */
  1931:static lv_obj_t  *g_music_play_btn = NULL;
  1932:static lv_obj_t  *g_music_play_lbl = NULL;
  1933:
  1934:static const char *music_base(const char *p)
  1935:{
  1936:    const char *s = strrchr(p, '/');
  1937:    return s ? s + 1 : p;
  1938:}
  1939:
  1940:static bool music_is_audio(const char *name)
  1941:{
  1942:    size_t n = strlen(name);
  1943:    if (n < 4) return false;
  1944:    const char *e = name + n - 4;
  1945:    return strcasecmp(e, ".mp3") == 0 || strcasecmp(e, ".wav") == 0 ||
  1946:           strcasecmp(e, ".flac") == 0 || strcasecmp(e, ".ogg") == 0;
  1947:}
  1948:
  1949:/* 扫描 SD 卡根目录的音频文件 */
  1950:static void music_scan(void)
  1951:{
  1952:    g_music_count = 0;
  1953:    DIR *d = opendir(MUSIC_DIR);
  1954:    if (!d) return;
  1955:    struct dirent *ent;
  1956:    while ((ent = readdir(d)) != NULL && g_music_count < MUSIC_MAX_FILES) {
  1957:        if (!music_is_audio(ent->d_name)) continue;
  1958:        snprintf(g_music_files[g_music_count], sizeof(g_music_files[0]),
  1959:                 "%s/%s", MUSIC_DIR, ent->d_name);
  1960:        g_music_count++;
  1961:    }
  1962:    closedir(d);
  1963:}
  1964:
  1965:/* 估算时长（秒）：尝试解析 MP3 第一帧得到比特率/采样率；失败按 ~128kbps 回退 */
  1966:static int music_estimate_duration(const char *path)
  1967:{
  1968:    struct stat st;
  1969:    if (stat(path, &st) != 0 || st.st_size <= 0) return 0;
  1970:    long size = st.st_size;
  1971:    FILE *f = fopen(path, "rb");
  1972:    if (!f) return (int)(size / 16000);
  1973:
  1974:    int dur = 0;
  1975:    unsigned char h[4];
  1976:    /* 跳过 ID3v2 标签头（前 3 字节 "ID3"，后跟 7 字节长度） */
  1977:    if (fread(h, 1, 3, f) == 3 && h[0] == 'I' && h[1] == 'D' && h[2] == 'D') {
  1978:        unsigned char b[7];
  1979:        if (fread(b, 1, 7, f) == 7) {
  1980:            long len = ((long)b[2] << 21) | ((long)b[3] << 14) |
  1981:                       ((long)b[4] << 7)  |  b[5];
  1982:            fseek(f, 10 + len, SEEK_SET);
  1983:        }
  1984:    } else {
  1985:        fseek(f, 0, SEEK_SET);
  1986:    }
  1987:    /* 在前 64KB 内定位第一个 MP3 帧同步字 0xFF 0xEx/Fx */
  1988:    long scanned = 0;
  1989:    while (scanned < 65536 && fread(h, 1, 4, f) == 4) {
  1990:        if (h[0] == 0xFF && (h[1] & 0xE0) == 0xE0) {
  1991:            int bi = (h[2] >> 4) & 0xF;   /* 比特率索引 */
  1992:            int si = (h[2] >> 2) & 0x3;   /* 采样率索引 */
  1993:            static const int br[16] = {0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0};
  1994:            static const int sr[4]  = {44100,48000,32000,0};
  1995:            int bitrate = br[bi], samplerate = sr[si];
  1996:            if (bitrate > 0 && samplerate > 0) {
  1997:                /* MPEG1 Layer III 帧大小（字节）与每帧样本数（1152） */
  1998:                long frame = (144L * bitrate * 1000) / samplerate;
  1999:                long off   = ftell(f) - 4;
  2000:                long frames = (size - off) / frame;
  2001:                if (frames > 0) dur = (int)(frames * 1152 / samplerate);
  2002:                break;
  2003:            }
  2004:        }
  2005:        fseek(f, -3, SEEK_CUR);
  2006:        scanned++;
  2007:    }
  2008:    fclose(f);
  2009:    if (dur <= 0) dur = (int)(size / 16000);   /* 回退：~128kbps */
  2010:    return dur;
  2011:}
  2012:
  2013:static void music_update_time(void)
  2014:{
  2015:    int s = g_music_pos / 1000;
  2016:    char b1[16], b2[16];
  2017:    snprintf(b1, sizeof(b1), "%d:%02d", s / 60, s % 60);
  2018:    snprintf(b2, sizeof(b2), "%d:%02d", g_music_dur / 60, g_music_dur % 60);
  2019:    lv_label_set_text(g_music_time, b1);     /* 左侧：当前 */
  2020:    lv_label_set_text(g_music_time_r, b2);   /* 右侧：总时长 */
  2021:}
  2022:
  2023:static void music_update_title(void)
  2024:{
  2025:    if (g_music_cur >= 0)
  2026:        lv_label_set_text(g_music_title, music_base(g_music_files[g_music_cur]));
  2027:}
  2028:
  2029:static void music_play(int idx)
  2030:{
  2031:    if (idx < 0 || idx >= g_music_count) return;
  2032:    g_music_cur = idx;
  2033:    g_music_dur = music_estimate_duration(g_music_files[idx]);
  2034:    if (g_music_dur <= 0) g_music_dur = 1;","totalLineCount":4442,"hasMore":true,"hint":""}},"isError":false}]}

