命令处理：
```c
static void apply_cmd(audio_cmd_t *c)
{
  switch(c->type) {
    case CMD_PLAY:
        wav_close();
        if (wav_open(c->path) != ESP_OK) { set error; break; }
        reconfig_clock(rate);
        loaded=true; playing=true; pos=0; dur=dur_ms;
        sd_mode(true);
        break;
    case CMD_PAUSE: playing=false; sd_mode(false); break;
    case CMD_RESUME: if (loaded) { playing=true; sd_mode(true);} break;
    case CMD_STOP: playing=false; loaded=false; sd_mode(false); wav_close(); break;
    case CMD_SEEK: seek to value; break;
    case CMD_VOLUME: s_volume = value; break;
  }
  g_audio.version++;
}
```

