WAV 解析：
```c
static esp_err_t wav_open(const char *path)
{
    memset(&s_wav, 0, sizeof(s_wav));
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;
    uint8_t h[12];
    if (fread(h,1,12,f)!=12 || memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) { fclose(f); return ESP_ERR_INVALID_RESPONSE; }
    // iterate chunks
    uint8_t ch[8];
    bool have_fmt=false;
    while (fread(ch,1,8,f)==8) {
        uint32_t sz = le32(ch+4);
        long pos = ftell(f);
        if (!memcmp(ch,"fmt ",4)) {
            uint8_t fmt[16];
            uint32_t n = sz < 16 ? sz : 16;
            if (fread(fmt,1,n,f)!=n) break;
            uint16_t format = le16(fmt+0);
            s_wav.channels = le16(fmt+2);
            s_wav.rate = le32(fmt+4);
            s_wav.bits = le16(fmt+14);
            if (format != 1 || s_wav.bits != 16 || (channels!=1&&channels!=2) || rate==0) { ... }
            have_fmt=true;
        } else if (!memcmp(ch,"data",4)) {
            s_wav.data_off = pos;
            s_wav.data_bytes = sz;
            fseek(f, pos + sz + (sz&1), SEEK_SET);
            // 其实找到 data 就可以停（但 data 可能在 fmt 之后，通常如此）
        }
        fseek(f, pos + sz + (sz&1), SEEK_SET);
    }
    ...
}
```
注意，找到 data 后不需要继续遍历，直接 break 更稳（因为 data 后面可能有 LIST 等）。但 fmt 必须在 data 前（标准如此）。我在找到 data 时 break。

dur_ms = data_bytes * 1000 / bytes_per_sec，bytes_per_sec = rate * channels * 2。

seek: offset = data_off + (ms * bytes_per_sec / 1000)，对齐到 frame（channels*2 的倍数）。

