保守做法：用 `xTaskCreateWithCaps` 建任务（栈放 PSRAM），命令用**静态结构体 + 任务通知 + portMUX 临界区**，零动态内存。这是最省内存且可靠的。

设计：
```c
static portMUX_TYPE s_cmd_lock = portMUX_INITIALIZER_UNLOCKED;
static volatile aud_cmd_e s_cmd = AUD_CMD_NONE;
static char   s_cmd_path[384];
static int    s_cmd_value;
static TaskHandle_t s_task;

static void post_cmd(aud_cmd_e c, const char *path, int value) {
    portENTER_CRITICAL(&s_cmd_lock);
    if (path) strncpy(s_cmd_path, path, sizeof(s_cmd_path)-1), ...;
    s_cmd_value = value;
    s_cmd = c;   // 最后写，作为"有效"标志
    portEXIT_CRITICAL(&s_cmd_lock);
    if (s_task) xTaskNotifyGive(s_task);
}

static bool take_cmd(aud_cmd_t *out) {
    portENTER_CRITICAL(&s_cmd_lock);
    if (s_cmd == AUD_CMD_NONE) { portEXIT_CRITICAL(...); return false; }
    out->cmd = s_cmd; ... strcpy(out->path, s_cmd_path);
    s_cmd = AUD_CMD_NONE;
    portEXIT_CRITICAL(...);
    return true;
}
```
但 aud_cmd_t 里含 path[384] 会占任务栈 384B（PSRAM 栈，没问题）。

