WAV 解析函数：
```c
static uint32_t rd32(const uint8_t *p){ return p[0] | (p[1]<<8) | (p[2]<<16) | ((uint32_t)p[3]<<24); }
static uint16_t rd16(const uint8_t *p){ return p[0] | (p[1]<<8); }

static esp_err_t wav_open(const char *path)
{
    memset(&s_wav, 0, sizeof(s_wav));
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;
    uint8_t h[12];
    if (fread(h,1,12,f)!=12 || memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) { fclose(f); return ESP_ERR_INVALID_RESPONSE; }
    uint8_t ck[8];
    bool have_fmt=false;
    while (fread(ck,1,8,f)==8) {
        uint32_t sz = rd32(ck+4);
        long pos = ftell(f);
        if (!memcmp(ck,"fmt ",4) && sz>=16) {
            uint8_t fmt[16];
            if (fread(fmt,1,16,f)==16) {
                uint16_t format = rd16(fmt);      // 1 = PCM
                s_wav.ch = rd16(fmt+2);
                s_wav.rate = rd32(fmt+4);
                s_wav.bits = rd16(fmt+14);
                have_fmt = (format==1);
            }
        } else if (!memcmp(ck,"data",4)) {
            s_wav.data_off = (uint32_t)pos;
            s_wav.data_len = sz;
            fseek(f, pos + sz, SEEK_SET);
            break;   // data 就是最后一块，直接停
        }
        fseek(f, pos + sz + (sz&1), SEEK_SET);  // chunk 按偶对齐
    }
    ...
}
```
注意：找到 data 后直接 break，但需要先 fseek 回去到 data 起始用于播放。我改成：记录 data_off/data_len 后 break，播放时 fseek(f, data_off, SEEK_SET)。

验证：format==1(PCM)、bits==16、ch==1 或 2、rate 合理(8000~96000)。其他明确报错。

时长：`dur_ms = data_len * 1000 / (rate * ch * bits/8)`。

进度：`pos_ms = played * 1000 / byte_per_ms`，即 `played * 1000 / (rate*ch*2)`。

seek(pct 0..1000)：`played = data_len * pct / 1000`，对齐到帧边界（`frame = ch*2`），`fseek(f, data_off + played, SEEK_SET)`。

播放循环：
