            if (xQueueReceive(q, &cmd, 0) == pdTRUE) { handle; continue; }
            // 读一帧
            size_t n = fread(s_raw, 1, want, f);
            if (n == 0) { eof; g_audio.playing=false; eof=true; ...; fclose; f=NULL; continue; }
            convert to s_pcm;
            apply volume;
            i2s_channel_write(...);
            update pos_ms; version++;
        } else {
            // 阻塞等命令
            if (xQueueReceive(q, &cmd, portMAX_DELAY) == pdTRUE) handle;
        }
    }
}
