#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"

static const char *TAG = "AUDIO";

/* 全局状态：后台任务写、UI 只读，靠 version 轮询同步（与 pc_mon.c 同构） */
volatile audio_state_t g_audio;

/* ---------------- 命令通道 ---------------- */
typedef enum {
    CMD_PLAY, CMD_PAUSE, CMD_RESUME, CMD_STOP, CMD_SEEK, CMD_VOLUME
} cmd_id_t;

typedef struct {
    cmd_id_t id;
    int      value;
    char     path[384];        /* 与 ui.c 的 g_music_files[] 路径缓冲等长 */
} audio_cmd_t;

static QueueHandle_t  s_q = NULL;
static TaskHandle_t   s_task = NULL;

/* ---------------- I2S ---------------- */
static i2s_chan_handle_t s_tx = NULL;
static bool               s_tx_enabled = false;

/* MAX98357A 的 SD_MODE：低=关断(静音省电)，高=工作。开机保持关断，避免上电噗声 */
static void amp_enable(bool on)
{
    if ((int)AUDIO_I2S_SD_MODE_GPIO < 0) return;      /* 硬件已上拉，跳过 */
    gpio_set_level(AUDIO_I2S_SD_MODE_GPIO, on ? 1 : 0);
}

static esp_err_t i2s_set_rate(uint32_t rate)
{
    if (!s_tx) {
        i2s_chan_config_t ch = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
        /* 默认 6×240 帧 ≈ 5.7KB 内部 DMA 内存，本项目内部 DRAM 紧张，减到 4×240 */
        ch.dma_desc_num  = 4;
        ch.dma_frame_num = 240;
        esp_err_t err = i2s_new_channel(&ch, &s_tx, NULL);
        if (err != ESP_OK) return err;

        i2s_std_config_t std = {
            .clk_cfg  = I2S_STD_CLK_DEFAULT_CONFIG(rate),
            /* 统一输出 16bit / 双声道。MAX98357A 无 MCLK，内部从 BCLK 恢复时钟 */
            .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT,
                                                             I2S_SLOT_MODE_STEREO),
            .gpio_cfg = {
                .mclk = I2S_GPIO_UNUSED,
                .bclk = AUDIO_I2S_BCLK_GPIO,
                .ws   = AUDIO_I2S_LRCK_GPIO,
                .dout = AUDIO_I2S_DOUT_GPIO,
                .din  = I2S_GPIO_UNUSED,
                .invert_flags = { .mclk_inv = false, .bclk_inv = false, .ws_inv = false },
            },
        };
        err = i2s_channel_init_std_mode(s_tx, &std);
        if (err != ESP_OK) return err;
    } else {
        if (s_tx_enabled) {
            i2s_channel_disable(s_tx);
            s_tx_enabled = false;
        }
        i2s_std_clk_config_t clk = I2S_STD_CLK_DEFAULT_CONFIG(rate);
        esp_err_t err = i2s_channel_reconfig_std_clock(s_tx, &clk);
        if (err != ESP_OK) return err;
    }
    esp_err_t err = i2s_channel_enable(s_tx);
    if (err == ESP_OK) s_tx_enabled = true;
    return err;
}

/* ---------------- WAV 解析 ---------------- */
typedef struct {
    uint32_t rate;
    uint16_t channels;
    uint16_t bits;
    uint32_t data_off;       /* data 区在文件中的起始偏移 */
    uint32_t data_size;      /* data 区字节数 */
    uint32_t frame_bytes;    /* 一个完整帧（含所有声道）的字节数 */
    uint32_t bytes_per_sec;
    uint32_t dur_ms;
} wav_info_t;

static FILE      *s_file = NULL;
static wav_info_t s_wav;
static uint32_t   s_played = 0;      /* 已从 data 区读出的字节数 */
static uint8_t    s_volume = 80;

/* 文件缓冲放 PSRAM：内部 DRAM 要留给 LVGL / WiFi / SDMMC DMA。
 * i2s_channel_write 会把用户缓冲拷进内部 DMA 描述符，故源缓冲可在 PSRAM。 */
#define SRC_BYTES   1024
#define OUT_SAMPLES 2048            /* 8bit mono 最坏 4 倍膨胀：1024B → 4096B */
static uint8_t  *s_src = NULL;
static int16_t  *s_out = NULL;

static uint16_t rd16(const uint8_t *p) { return (uint16_t)(p[0] | ((uint16_t)p[1] << 8)); }
static uint32_t rd32(const uint8_t *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static void file_close(void)
{
    if (s_file) { fclose(s_file); s_file = NULL; }
    memset(&s_wav, 0, sizeof(s_wav));
    s_played = 0;
}

/* 只支持未压缩 PCM WAV。返回非 OK 时由调用方给出提示 */
static esp_err_t wav_open(const char *path)
{
    file_close();
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;

    uint8_t h[12];
    if (fread(h, 1, 12, f) != 12 || memcmp(h, "RIFF", 4) || memcmp(h + 8, "WAVE", 4)) {
        fclose(f);
        return ESP_ERR_INVALID_RESPONSE;
    }

    uint16_t format = 0;
    uint8_t  ck[8];
    while (fread(ck, 1, 8, f) == 8) {
        uint32_t sz = rd32(ck + 4);
        long pos = ftell(f);
        if (!memcmp(ck, "fmt ", 4)) {
            uint8_t fmt[16];
            size_t  n = sz < sizeof(fmt) ? sz : sizeof(fmt);
            if (fread(fmt, 1, n, f) == n && n >= 16) {
                format       = rd16(fmt);
                s_wav.channels  = rd16(fmt + 2);
                s_wav.rate      = rd32(fmt + 4);
                s_wav.bits      = rd16(fmt + 14);
            }
        } else if (!memcmp(ck, "data", 4)) {
            s_wav.data_off  = (uint32_t)pos;
            s_wav.data_size = sz;
            break;
        }
        fseek(f, pos + sz + (sz & 1), SEEK_SET);   /* RIFF chunk 按偶数字节对齐 */
    }

    if (format != 1 || !s_wav.data_size || !s_wav.rate ||
        (s_wav.channels != 1 && s_wav.channels != 2) ||
        (s_wav.bits != 8 && s_wav.bits != 16 && s_wav.bits != 24 && s_wav.bits != 32)) {
        fclose(f);
        memset(&s_wav, 0, sizeof(s_wav));
        return ESP_ERR_NOT_SUPPORTED;
    }

    s_wav.frame_bytes   = (uint32_t)s_wav.channels * (s_wav.bits / 8);
    s_wav.bytes_per_sec  = s_wav.rate * s_wav.frame_bytes;
    s_wav.dur_ms         = (uint32_t)(((uint64_t)s_wav.data_size * 1000) / s_wav.bytes_per_sec);
    s_file = f;
    s_played = 0;
    fseek(f, s_wav.data_off, SEEK_SET);
    return ESP_OK;
}

/* 源 PCM → 16bit 双声道，并施加软件音量。返回输出字节数 */
static size_t pcm_convert(size_t n)
{
    const int ch  = s_wav.channels;
    const int bps = s_wav.bits / 8;
    size_t frames = n / s_wav.frame_bytes;

    for (size_t i = 0; i < frames; i++) {
        int32_t l = 0, r = 0;
        for (int c = 0; c < ch; c++) {
            const uint8_t *p = s_src + (i * ch + c) * bps;
            int32_t v;
            switch (s_wav.bits) {
            case 8:  v = ((int32_t)p[0] - 128) << 8; break;   /* 8bit WAV 是无符号 */
            case 16: v = (int16_t)rd16(p); break;
            case 24: v = (int16_t)(p[1] | ((uint16_t)p[2] << 8)); break;  /* 取高 16 位 */
            default: v = (int32_t)rd32(p) >> 16; break;                     /* 32bit 取高 16 位 */
            }
            if (c == 0) l = v; else r = v;
        }
        if (ch == 1) r = l;                 /* 单声道复制到左右，避免只接了一边没声 */
        s_out[2 * i]     = (int16_t)(l * s_volume / 100);
        s_out[2 * i + 1]  = (int16_t)(r * s_volume / 100);
    }
    return frames * 4;                     /* 16bit × 2ch */
}

static void publish(void)
{
    g_audio.version++;
}

static void set_hint(const char *s)
{
    /* volatile char[] 逐字节写，写完后才 publish，UI 拿到新 version 时内容已就绪 */
    size_t i = 0;
    if (s) for (; i + 1 < sizeof(g_audio.hint) && s[i]; i++) g_audio.hint[i] = s[i];
    g_audio.hint[i] = '\0';
}

/* ---------------- 命令处理 ---------------- */
static void handle_cmd(const audio_cmd_t *c)
{
    switch (c->id) {
    case CMD_PLAY: {
        esp_err_t err = wav_open(c->path);
        if (err != ESP_OK) {
            file_close();
            amp_enable(false);
            g_audio.loaded  = false;
            g_audio.playing = false;
            g_audio.eof     = false;
            g_audio.pos_ms  = 0;
            g_audio.dur_ms  = 0;
            set_hint(err == ESP_ERR_NOT_SUPPORTED ? "仅支持 PCM WAV" : "文件打开失败");
            publish();
            break;
        }
        err = i2s_set_rate(s_wav.rate);
        if (err != ESP_OK) {
            ESP_LOGE(TAG, "i2s_set_rate(%u) failed: %s", (unsigned)s_wav.rate, esp_err_to_name(err));
            file_close();
            g_audio.loaded = false; g_audio.playing = false;
            set_hint("I2S 初始化失败");
            publish();
            break;
        }
        g_audio.sample_rate = s_wav.rate;
        g_audio.channels    = (uint8_t)s_wav.channels;
        g_audio.bits        = (uint8_t)s_wav.bits;
        g_audio.dur_ms      = s_wav.dur_ms;
        g_audio.pos_ms      = 0;
        g_audio.loaded     = true;
        g_audio.playing    = true;
        g_audio.eof        = false;
        set_hint(NULL);
        amp_enable(true);
        ESP_LOGI(TAG, "play %s: %uHz %uch %ubit %ums", c->path,
                 (unsigned)s_wav.rate, (unsigned)s_wav.channels,
                 (unsigned)s_wav.bits, (unsigned)s_wav.dur_ms);
        publish();
        break;
    }
    case CMD_PAUSE:
        if (g_audio.loaded) {
            g_audio.playing = false;
            amp_enable(false);               /* 关断功放，暂停时无静态底噪 */
            publish();
        }
        break;
    case CMD_RESUME:
        if (g_audio.loaded && s_file) {
            g_audio.playing = true;
            amp_enable(true);
            publish();
        }
        break;
    case CMD_STOP:
        file_close();
        amp_enable(false);
        if (s_tx_enabled) { i2s_channel_disable(s_tx); s_tx_enabled = false; }
        g_audio.loaded = false; g_audio.playing = false; g_audio.eof = false;
        g_audio.pos_ms = 0; g_audio.dur_ms = 0;
        set_hint(NULL);
        publish();
        break;
    case CMD_SEEK: {
        if (!g_audio.loaded || !s_file || !s_wav.data_size) break;
        int pct = c->value;
        if (pct < 0) pct = 0;
        if (pct > 1000) pct = 1000;
        uint32_t off = (uint32_t)(((uint64_t)s_wav.data_size * pct) / 1000);
        off -= off % s_wav.frame_bytes;      /* 对齐到帧边界 */
        fseek(s_file, s_wav.data_off + off, SEEK_SET);
        s_played = off;
        g_audio.pos_ms = (uint32_t)(((uint64_t)off * 1000) / s_wav.bytes_per_sec);
        g_audio.eof = false;
        publish();
        break;
    }
    case CMD_VOLUME: {
        int v = c->value;
        if (v < 0) v = 0;
        if (v > 100) v = 100;
        s_volume = (uint8_t)v;
        g_audio.volume = s_volume;
        publish();
        break;
    }
    }
}

static void audio_task(void *arg)
{
    (void)arg;
    for (;;) {
        audio_cmd_t cmd;
        /* 播放中不能阻塞等命令，否则 I2S 断流会破音；空闲时才阻塞休眠省 CPU */
        BaseType_t got = xQueueReceive(s_q, &cmd, (s_file && g_audio.playing) ? 0 : portMAX_DELAY);
        if (got == pdTRUE) handle_cmd(&cmd);

        if (!s_file || !g_audio.playing) continue;

        uint32_t want = (SRC_BYTES / s_wav.frame_bytes) * s_wav.frame_bytes;
        if (want == 0) want = s_wav.frame_bytes;
        size_t n = fread(s_src, 1, want, s_file);
        if (n == 0) {
            /* 播完：置 eof 让 UI 决定下一首，同时关断功放 */
            amp_enable(false);
            g_audio.playing = false;
            g_audio.eof     = true;
            g_audio.pos_ms  = s_wav.dur_ms;
            publish();
            continue;
        }

        size_t bytes = pcm_convert(n);
        size_t written = 0;
        /* 阻塞写出：I2S 时钟决定真实播放速度，因此进度天然与真实时间同步 */
        esp_err_t err = i2s_channel_write(s_tx, s_out, bytes, &written, portMAX_DELAY);
        if (err != ESP_OK) {
            ESP_LOGE(TAG, "i2s write failed: %s", esp_err_to_name(err));
            amp_enable(false);
            g_audio.playing = false;
            set_hint("I2S 输出失败");
            publish();
            continue;
        }

        s_played += (uint32_t)n;
        g_audio.pos_ms = (uint32_t)(((uint64_t)s_played * 1000) / s_wav.bytes_per_sec);
        publish();                      /* 每块推进一次，UI 按 version 刷新进度条 */
    }
}

/* ---------------- 对外 API ---------------- */
static void post_cmd(cmd_id_t id, const char *path, int value)
{
    if (!s_q) return;
    audio_cmd_t c = { .id = id, .value = value };
    if (path) {
        snprintf(c.path, sizeof(c.path), "%s", path);
    } else {
        c.path[0] = '\0';
    }
    /* 队列满时丢最旧的一条再投，保证「停止/切歌」这类关键命令不被卡住 */
    if (xQueueSend(s_q, &c, 0) != pdTRUE) {
        audio_cmd_t dummy;
        xQueueReceive(s_q, &dummy, 0);
        xQueueSend(s_q, &c, 0);
    }
}

void audio_player_init(void)
{
    memset((void *)&g_audio, 0, sizeof(g_audio));
    g_audio.volume = s_volume;

    if ((int)AUDIO_I2S_SD_MODE_GPIO >= 0) {
        gpio_config_t io = {
            .pin_bit_mask = 1ULL << AUDIO_I2S_SD_MODE_GPIO,
            .mode         = GPIO_MODE_OUTPUT,
            .pull_up_en   = GPIO_PULLUP_DISABLE,
            .pull_down_en = GPIO_PULLDOWN_DISABLE,
            .intr_type    = GPIO_INTR_DISABLE,
        };
        gpio_config(&io);
        gpio_set_level(AUDIO_I2S_SD_MODE_GPIO, 0);
    }

    /* 缓冲在开机、内存最空时一次性分配，之后常驻 */
    s_src = (uint8_t *)heap_caps_malloc(SRC_BYTES, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    s_out = (int16_t *)heap_caps_malloc(OUT_SAMPLES * sizeof(int16_t),
                                        MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!s_src || !s_out) {
        ESP_LOGE(TAG, "audio buffers alloc failed (PSRAM), player disabled");
        return;
    }

    s_q = xQueueCreate(4, sizeof(audio_cmd_t));
    if (!s_q) { ESP_LOGE(TAG, "cmd queue create failed"); return; }

    BaseType_t ok = xTaskCreateWithCaps(audio_task, "audio", 8192, NULL, 5, NULL,
                                        MALLOC_CAP_SPIRAM);
    if (ok != pdPASS) {
        ok = xTaskCreate(audio_task, "audio", 8192, NULL, 5, &s_task);
    }
    if (ok != pdPASS) {
        ESP_LOGE(TAG, "audio task create failed");
        return;
    }
    ESP_LOGI(TAG, "init ok, I2S BCLK=%d LRCK=%d DOUT=%d SD_MODE=%d",
             (int)AUDIO_I2S_BCLK_GPIO, (int)AUDIO_I2S_LRCK_GPIO,
             (int)AUDIO_I2S_DOUT_GPIO, (int)AUDIO_I2S_SD_MODE_GPIO);
}

esp_err_t audio_player_play(const char *path)
{
    if (!s_q || !path || !path[0]) return ESP_ERR_INVALID_STATE;
    post_cmd(CMD_PLAY, path, 0);
    return ESP_OK;
}
