static esp_err_t wav_open(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;
    uint8_t h[12];
    if (fread(h,1,12,f)!=12 || memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) { fclose(f); return ESP_ERR_INVALID_RESPONSE; }
    wav_info_t w = {0};
    uint8_t ck[8];
    while (fread(ck,1,8,f)==8) {
        uint32_t sz = rd32(ck+4);
        long pos = ftell(f);
        if (!memcmp(ck,"fmt ",4)) {
            uint8_t fmt[16];
            size_t n = sz < sizeof(fmt) ? sz : sizeof(fmt);
            if (fread(fmt,1,n,f)==n && n>=16) {
                uint16_t format = rd16(fmt);
                w.channels = rd16(fmt+2);
                w.rate = rd32(fmt+4);
                w.bits = rd16(fmt+14);
                if (format!=1) ...
            }
        } else if (!memcmp(ck,"data",4)) {
            w.data_off = (uint32_t)pos;
            w.data_size = sz;
            break;
        }
        fseek(f, pos + sz + (sz & 1), SEEK_SET);
    }
    // validate
    if (format != 1 || w.rate==0 || (w.channels!=1&&w.channels!=2) || !(bits==8||16||24||32)) -> unsupported
    w.frame_bytes = w.channels * (w.bits/8);
    w.bytes_per_sec = w.rate * w.frame_bytes;
    dur_ms = w.data_size * 1000 / w.bytes_per_sec;
    ...
    s_file=f; s_wav=w; s_played_bytes=0;
    fseek(f, w.data_off, SEEK_SET);
}
