            if (bitrate > 0 && samplerate > 0) {
                /* MPEG1 Layer III 帧大小（字节）与每帧样本数（1152） */
                long frame = (144L * bitrate * 1000) / samplerate;
                long off   = ftell(f) - 4;
                long frames = (size - off) / frame;
                if (frames > 0) dur = (int)(frames * 1152 / samplerate);
