{
    (void)t;
    if (!g_music_playing || g_music_cur < 0) return;
    uint32_t now = lv_tick_get();
    uint32_t dt = now - g_music_tick;
    g_music_tick = now;
    g_music_pos += (int)dt;
    int dur_ms = g_music_dur * 1000;
