    15:#include "freertos/queue.h"
    16:
    17:static const char *TAG = "AUDIO";
    18:
    19:/* 全局状态：后台任务写、UI 只读，靠 version 轮询同步（与 pc_mon.c 同构） */
    20:volatile audio_state_t g_audio;
    21:
    22:/* ---------------- 命令通道 ---------------- */
    23:typedef enum {
    24:    CMD_PLAY, CMD_PAUSE, CMD_RESUME, CMD_STOP, CMD_SEEK, CMD_VOLUME
    25:} cmd_id_t;
    26:
    27:typedef struct {
    28:    cmd_id_t id;
    29:    int      value;
    30:    char     path[384];        /* 与 ui.c 的 g_music_files[] 路径缓冲等长 */
    31:} audio_cmd_t;
    32:
    33:static QueueHandle_t  s_q = NULL;
    34:static TaskHandle_t   s_task = NULL;
    35:
    36:/* ---------------- I2S ---------------- */
    37:static i2s_chan_handle_t s_tx = NULL;
    38:static bool               s_tx_enabled = false;
    39:
    40:/* MAX98357A 的 SD_MODE：低=关断(静音省电)，高=工作。开机保持关断，避免上电噗声 */
    41:static void amp_enable(bool on)
    42:{
    43:    gpio_num_t pin = AUDIO_I2S_SD_MODE_GPIO;
    44:    if (pin < 0) return;                 /* 宏设为 GPIO_NUM_NC：硬件已上拉，跳过 */
    45:    gpio_set_level(pin, on ? 1 : 0);
    46:}
    47:
    48:static esp_err_t i2s_set_rate(uint32_t rate)
    49:{
    50:    if (!s_tx) {
    51:        i2s_chan_config_t ch = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    52:        /* 默认 6×240 帧 ≈ 5.7KB 内部 DMA 内存，本项目内部 DRAM 紧张，减到 4×240 */
    53:        ch.dma_desc_num  = 4;
    54:        ch.dma_frame_num = 240;
    55:        esp_err_t err = i2s_new_channel(&ch, &s_tx, NULL);
    56:        if (err != ESP_OK) return err;
    57:
    58:        i2s_std_config_t std = {
    59:            .clk_cfg  = I2S_STD_CLK_DEFAULT_CONFIG(rate),
    60:            /* 统一输出 16bit / 双声道。MAX98357A 无 MCLK，内部从 BCLK 恢复时钟 */
    61:            .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT,
    62:                                                             I2S_SLOT_MODE_STEREO),
    63:            .gpio_cfg = {
    64:                .mclk = I2S_GPIO_UNUSED,
    65:                .bclk = AUDIO_I2S_BCLK_GPIO,
    66:                .ws   = AUDIO_I2S_LRCK_GPIO,
    67:                .dout = AUDIO_I2S_DOUT_GPIO,
    68:                .din  = I2S_GPIO_UNUSED,
    69:                .invert_flags = { .mclk_inv = false, .bclk_inv = false, .ws_inv = false },
    70:            },
    71:        };
    72:        err = i2s_channel_init_std_mode(s_tx, &std);
    73:        if (err != ESP_OK) return err;
    74:    } else {
    75:        if (s_tx_enabled) {
    76:            i2s_channel_disable(s_tx);
    77:            s_tx_enabled = false;
    78:        }
    79:        i2s_std_clk_config_t clk = I2S_STD_CLK_DEFAULT_CONFIG(rate);
    80:        esp_err_t err = i2s_channel_reconfig_std_clock(s_tx, &clk);
    81:        if (err != ESP_OK) return err;
    82:    }
    83:    esp_err_t err = i2s_channel_enable(s_tx);
    84:    if (err == ESP_OK) s_tx_enabled = true;
    85:    return err;
    86:}
    87:
    88:/* ---------------- WAV 解析 ---------------- */
    89:typedef struct {
    90:    uint32_t rate;
    91:    uint16_t channels;
    92:    uint16_t bits;
    93:    uint32_t data_off;       /* data 区在文件中的起始偏移 */
    94:    uint32_t data_size;      /* data 区字节数 */
    95:    uint32_t frame_bytes;    /* 一个完整帧（含所有声道）的字节数 */
    96:    uint32_t bytes_per_sec;
    97:    uint32_t dur_ms;
    98:} wav_info_t;
    99:
   100:static FILE      *s_file = NULL;
   101:static wav_info_t s_wav;
   102:static uint32_t   s_played = 0;      /* 已从 data 区读出的字节数 */
   103:static uint8_t    s_volume = 80;
   104:
   105:/* 文件缓冲放 PSRAM：内部 DRAM 要留给 LVGL / WiFi / SDMMC DMA。
   106: * i2s_channel_write 会把用户缓冲拷进内部 DMA 描述符，故源缓冲可在 PSRAM。 */
   107:#define SRC_BYTES   1024
   108:#define OUT_SAMPLES 2048            /* 8bit mono 最坏 4 倍膨胀：1024B → 4096B */
   109:static uint8_t  *s_src = NULL;
   110:static int16_t  *s_out = NULL;
   111:
   112:static uint16_t rd16(const uint8_t *p) { return (uint16_t)(p[0] | ((uint16_t)p[1] << 8)); }
   113:static uint32_t rd32(const uint8_t *p)
   114:{
   115:    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
   116:           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
   117:}
   118:
   119:static void file_close(void)
   120:{
   121:    if (s_file) { fclose(s_file); s_file = NULL; }
   122:    memset(&s_wav, 0, sizeof(s_wav));
   123:    s_played = 0;
   124:}
   125:
   126:/* 只支持未压缩 PCM WAV。返回非 OK 时由调用方给出提示 */
   127:static esp_err_t wav_open(const char *path)
   128:{
   129:    file_close();
   130:    FILE *f = fopen(path, "rb");
   131:    if (!f) return ESP_ERR_NOT_FOUND;
   132:
   133:    uint8_t h[12];
   134:    if (fread(h, 1, 12, f) != 12 || memcmp(h, "RIFF", 4) || memcmp(h + 8, "WAVE", 4)) {
   135:        fclose(f);
   136:        return ESP_ERR_INVALID_RESPONSE;
   137:    }
   138:
   139:    uint16_t format = 0;
   140:    uint8_t  ck[8];
   141:    while (fread(ck, 1, 8, f) == 8) {
   142:        uint32_t sz = rd32(ck + 4);
   143:        long pos = ftell(f);
   144:        if (!memcmp(ck, "fmt ", 4)) {
   145:            uint8_t fmt[16];
   146:            size_t  n = sz < sizeof(fmt) ? sz : sizeof(fmt);
   147:            if (fread(fmt, 1, n, f) == n && n >= 16) {
   148:                format       = rd16(fmt);
   149:                s_wav.channels  = rd16(fmt + 2);
   150:                s_wav.rate      = rd32(fmt + 4);
   151:                s_wav.bits      = rd16(fmt + 14);
   152:            }
   153:        } else if (!memcmp(ck, "data", 4)) {
   154:            s_wav.data_off  = (uint32_t)pos;
   155:            s_wav.data_size = sz;
   156:            break;
   157:        }
   158:        fseek(f, pos + sz + (sz & 1), SEEK_SET);   /* RIFF chunk 按偶数字节对齐 */
   159:    }
   160:
   161:    if (format != 1 || !s_wav.data_size || !s_wav.rate ||
   162:        (s_wav.channels != 1 && s_wav.channels != 2) ||
   163:        (s_wav.bits != 8 && s_wav.bits != 16 && s_wav.bits != 24 && s_wav.bits != 32)) {
   164:        fclose(f);
   165:        memset(&s_wav, 0, sizeof(s_wav));
   166:        return ESP_ERR_NOT_SUPPORTED;
   167:    }
   168:
   169:    s_wav.frame_bytes   = (uint32_t)s_wav.channels * (s_wav.bits / 8);
   170:    s_wav.bytes_per_sec  = s_wav.rate * s_wav.frame_bytes;
   171:    s_wav.dur_ms         = (uint32_t)(((uint64_t)s_wav.data_size * 1000) / s_wav.bytes_per_sec);
   172:    s_file = f;
   173:    s_played = 0;
   174:    fseek(f, s_wav.data_off, SEEK_SET);
   175:    return ESP_OK;
   176:}
