   178:/* 源 PCM → 16bit 双声道，并施加软件音量。返回输出字节数 */
   179:static size_t pcm_convert(size_t n)
   180:{
   181:    const int ch  = s_wav.channels;
   182:    const int bps = s_wav.bits / 8;
   183:    size_t frames = n / s_wav.frame_bytes;
   184:
   185:    for (size_t i = 0; i < frames; i++) {
   186:        int32_t l = 0, r = 0;
   187:        for (int c = 0; c < ch; c++) {
   188:            const uint8_t *p = s_src + (i * ch + c) * bps;
   189:            int32_t v;
   190:            switch (s_wav.bits) {
   191:            case 8:  v = ((int32_t)p[0] - 128) << 8; break;   /* 8bit WAV 是无符号 */
   192:            case 16: v = (int16_t)rd16(p); break;
   193:            case 24: v = (int16_t)(p[1] | ((uint16_t)p[2] << 8)); break;  /* 取高 16 位 */
   194:            default: v = (int32_t)rd32(p) >> 16; break;                     /* 32bit 取高 16 位 */
   195:            }
   196:            if (c == 0) l = v; else r = v;
   197:        }
   198:        if (ch == 1) r = l;                 /* 单声道复制到左右，避免只接了一边没声 */
   199:        s_out[2 * i]     = (int16_t)(l * s_volume / 100);
   200:        s_out[2 * i + 1]  = (int16_t)(r * s_volume / 100);
   201:    }
   202:    return frames * 4;                     /* 16bit × 2ch */
   203:}
