   310:static void audio_task(void *arg)
   311:{
   312:    (void)arg;
   313:    for (;;) {
   314:        audio_cmd_t cmd;
   315:        /* 播放中不能阻塞等命令，否则 I2S 断流会破音；空闲时才阻塞休眠省 CPU */
   316:        BaseType_t got = xQueueReceive(s_q, &cmd, (s_file && g_audio.playing) ? 0 : portMAX_DELAY);
   317:        if (got == pdTRUE) handle_cmd(&cmd);
   318:
   319:        if (!s_file || !g_audio.playing) continue;
   320:
   321:        uint32_t want = (SRC_BYTES / s_wav.frame_bytes) * s_wav.frame_bytes;
   322:        if (want == 0) want = s_wav.frame_bytes;
   323:        size_t n = fread(s_src, 1, want, s_file);
   324:        if (n == 0) {
   325:            /* 播完：置 eof 让 UI 决定下一首，同时关断功放 */
   326:            amp_enable(false);
   327:            g_audio.playing = false;
   328:            g_audio.eof     = true;
   329:            g_audio.pos_ms  = s_wav.dur_ms;
   330:            publish();
   331:            continue;
   332:        }
   333:
   334:        size_t bytes = pcm_convert(n);
   335:        size_t written = 0;
   336:        /* 阻塞写出：I2S 时钟决定真实播放速度，因此进度天然与真实时间同步。
   337:         * 超时必须是有限毫秒值 —— 驱动内部走 pdMS_TO_TICKS(timeout_ms)，
   338:         * 传 portMAX_DELAY 会整数溢出成 0，反而立刻返回 TIMEOUT。
   339:         * 一块 1024B 在 44.1kHz/16bit/双声道下约 12ms，1000ms 余量充足。 */
   340:        esp_err_t err = i2s_channel_write(s_tx, s_out, bytes, &written, 1000);
   341:        if (err != ESP_OK) {
   342:            ESP_LOGE(TAG, "i2s write failed: %s", esp_err_to_name(err));
   343:            amp_enable(false);
   344:            g_audio.playing = false;
   345:            set_hint("I2S 输出失败");
   346:            publish();
   347:            continue;
   348:        }
   349:
   350:        s_played += (uint32_t)n;
   351:        g_audio.pos_ms = (uint32_t)(((uint64_t)s_played * 1000) / s_wav.bytes_per_sec);
   352:        publish();                      /* 每块推进一次，UI 按 version 刷新进度条 */
   353:    }
   354:}
