   374:void audio_player_init(void)
   375:{
   376:    /* g_audio 是 volatile 且由后台任务写，这里任务尚未创建，BSS 已清零，
   377:     * 只显式初始化常量字段即可（不对 volatile 对象做 memset） */
   378:    g_audio.volume = s_volume;
   379:    g_audio.hint[0] = '\0';
   380:
   381:    gpio_num_t sd = AUDIO_I2S_SD_MODE_GPIO;
   382:    if (sd >= 0) {
   383:        gpio_config_t io = {
   384:            .pin_bit_mask = 1ULL << (unsigned)sd,
   385:            .mode         = GPIO_MODE_OUTPUT,
   386:            .pull_up_en   = GPIO_PULLUP_DISABLE,
   387:            .pull_down_en = GPIO_PULLDOWN_DISABLE,
   388:            .intr_type    = GPIO_INTR_DISABLE,
   389:        };
   390:        gpio_config(&io);
   391:        gpio_set_level(sd, 0);
   392:    }
   393:
   394:    /* 缓冲在开机、内存最空时一次性分配，之后常驻 */
   395:    s_src = (uint8_t *)heap_caps_malloc(SRC_BYTES, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
   396:    s_out = (int16_t *)heap_caps_malloc(OUT_SAMPLES * sizeof(int16_t),
   397:                                        MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
   398:    if (!s_src || !s_out) {
   399:        ESP_LOGE(TAG, "audio buffers alloc failed (PSRAM), player disabled");
   400:        return;
   401:    }
   402:
   403:    s_q = xQueueCreate(4, sizeof(audio_cmd_t));
   404:    if (!s_q) { ESP_LOGE(TAG, "cmd queue create failed"); return; }
   405:
   406:    BaseType_t ok = xTaskCreateWithCaps(audio_task, "audio", 8192, NULL, 5, NULL,
   407:                                        MALLOC_CAP_SPIRAM);
   408:    if (ok != pdPASS) {
   409:        ok = xTaskCreate(audio_task, "audio", 8192, NULL, 5, &s_task);
   410:    }
   411:    if (ok != pdPASS) {
   412:        ESP_LOGE(TAG, "audio task create failed");
   413:        return;
   414:    }
   415:    ESP_LOGI(TAG, "init ok, I2S BCLK=%d LRCK=%d DOUT=%d SD_MODE=%d",
   416:             (int)AUDIO_I2S_BCLK_GPIO, (int)AUDIO_I2S_LRCK_GPIO,
   417:             (int)AUDIO_I2S_DOUT_GPIO, (int)AUDIO_I2S_SD_MODE_GPIO);
   418:}
