   420:esp_err_t audio_player_play(const char *path)
   421:{
   422:    if (!s_q || !path || !path[0]) return ESP_ERR_INVALID_STATE;
   423:    post_cmd(CMD_PLAY, path, 0);
   424:    return ESP_OK;
   425:}
   426:void audio_player_pause(void)  { post_cmd(CMD_PAUSE, NULL, 0); }
   427:void audio_player_resume(void) { post_cmd(CMD_RESUME, NULL, 0); }
   428:void audio_player_stop(void)   { post_cmd(CMD_STOP, NULL, 0); }
