    72:        err = i2s_channel_init_std_mode(s_tx, &std);
    73:        if (err != ESP_OK) return err;
    74:    } else {
    75:        if (s_tx_enabled) {
    76:            i2s_channel_disable(s_tx);
    77:            s_tx_enabled = false;
    78:        }
    79:        i2s_std_clk_config_t clk = I2S_STD_CLK_DEFAULT_CONFIG(rate);
    80:        esp_err_t err = i2s_channel_reconfig_std_clock(s_tx, &clk);
    81:        if (err != ESP_OK) return err;
    82:    }
    83:    esp_err_t err = i2s_channel_enable(s_tx);
    84:    if (err == ESP_OK) s_tx_enabled = true;
    85:    return err;
    86:}
