   210:static void set_hint(const char *s)
   211:{
   212:    /* volatile char[] 逐字节写，写完后才 publish，UI 拿到新 version 时内容已就绪 */
   213:    size_t i = 0;
   214:    if (s) for (; i + 1 < sizeof(g_audio.hint) && s[i]; i++) g_audio.hint[i] = s[i];
   215:    g_audio.hint[i] = '\0';
   216:}
