   218:/* ---------------- 命令处理 ---------------- */
   219:static void handle_cmd(const audio_cmd_t *c)
   220:{
   221:    switch (c->id) {
   222:    case CMD_PLAY: {
   223:        esp_err_t err = wav_open(c->path);
   224:        if (err != ESP_OK) {
   225:            file_close();
   226:            amp_enable(false);
   227:            g_audio.loaded  = false;
   228:            g_audio.playing = false;
   229:            g_audio.eof     = false;
   230:            g_audio.pos_ms  = 0;
   231:            g_audio.dur_ms  = 0;
   232:            set_hint(err == ESP_ERR_NOT_SUPPORTED ? "仅支持 PCM WAV" : "文件打开失败");
   233:            publish();
   234:            break;
   235:        }
   236:        err = i2s_set_rate(s_wav.rate);
   237:        if (err != ESP_OK) {
   238:            ESP_LOGE(TAG, "i2s_set_rate(%u) failed: %s", (unsigned)s_wav.rate, esp_err_to_name(err));
   239:            file_close();
   240:            g_audio.loaded = false; g_audio.playing = false;
   241:            set_hint("I2S 初始化失败");
   242:            publish();
   243:            break;
   244:        }
   245:        g_audio.sample_rate = s_wav.rate;
   246:        g_audio.channels    = (uint8_t)s_wav.channels;
   247:        g_audio.bits        = (uint8_t)s_wav.bits;
   248:        g_audio.dur_ms      = s_wav.dur_ms;
   249:        g_audio.pos_ms      = 0;
   250:        g_audio.loaded     = true;
   251:        g_audio.playing    = true;
   252:        g_audio.eof        = false;
   253:        set_hint(NULL);
   254:        amp_enable(true);
   255:        ESP_LOGI(TAG, "play %s: %uHz %uch %ubit %ums", c->path,
   256:                 (unsigned)s_wav.rate, (unsigned)s_wav.channels,
   257:                 (unsigned)s_wav.bits, (unsigned)s_wav.dur_ms);
   258:        publish();
   259:        break;
   260:    }
   261:    case CMD_PAUSE:
   262:        if (g_audio.loaded) {
   263:            g_audio.playing = false;
   264:            amp_enable(false);               /* 关断功放，暂停时无静态底噪 */
   265:            publish();
   266:        }
   267:        break;
   268:    case CMD_RESUME:
   269:        if (g_audio.loaded && s_file) {
   270:            g_audio.playing = true;
   271:            amp_enable(true);
   272:            publish();
   273:        }
   274:        break;
   275:    case CMD_STOP:
   276:        file_close();
   277:        amp_enable(false);
   278:        if (s_tx_enabled) { i2s_channel_disable(s_tx); s_tx_enabled = false; }
   279:        g_audio.loaded = false; g_audio.playing = false; g_audio.eof = false;
   280:        g_audio.pos_ms = 0; g_audio.dur_ms = 0;
   281:        set_hint(NULL);
   282:        publish();
   283:        break;
   284:    case CMD_SEEK: {
   285:        if (!g_audio.loaded || !s_file || !s_wav.data_size) break;
   286:        int pct = c->value;
   287:        if (pct < 0) pct = 0;
   288:        if (pct > 1000) pct = 1000;
   289:        uint32_t off = (uint32_t)(((uint64_t)s_wav.data_size * pct) / 1000);
   290:        off -= off % s_wav.frame_bytes;      /* 对齐到帧边界 */
   291:        fseek(s_file, s_wav.data_off + off, SEEK_SET);
   292:        s_played = off;
   293:        g_audio.pos_ms = (uint32_t)(((uint64_t)off * 1000) / s_wav.bytes_per_sec);
   294:        g_audio.eof = false;
   295:        publish();
   296:        break;
   297:    }
   298:    case CMD_VOLUME: {
   299:        int v = c->value;
   300:        if (v < 0) v = 0;
   301:        if (v > 100) v = 100;
   302:        s_volume = (uint8_t)v;
   303:        g_audio.volume = s_volume;
   304:        publish();
   305:        break;
   306:    }
   307:    }
   308:}
