   356:/* ---------------- 对外 API ---------------- */
   357:static void post_cmd(cmd_id_t id, const char *path, int value)
   358:{
   359:    if (!s_q) return;
   360:    audio_cmd_t c = { .id = id, .value = value };
   361:    if (path) {
   362:        snprintf(c.path, sizeof(c.path), "%s", path);
   363:    } else {
   364:        c.path[0] = '\0';
   365:    }
   366:    /* 队列满时丢最旧的一条再投，保证「停止/切歌」这类关键命令不被卡住 */
   367:    if (xQueueSend(s_q, &c, 0) != pdTRUE) {
   368:        audio_cmd_t dummy;
   369:        xQueueReceive(s_q, &dummy, 0);
   370:        xQueueSend(s_q, &c, 0);
   371:    }
   372:}
