static esp_err_t mp3_open(const char *path)
{
    file_close();
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;
    fseek(f, 0, SEEK_END);
    long total = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (total < 64) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    /* ID3v2：10 字节头 + syncsafe 长度（+可选 footer） */
    uint8_t id3[10];
    uint32_t off = 0;
    if (fread(id3,1,10,f)==10 && !memcmp(id3,"ID3",3)) {
        uint32_t sz = ((uint32_t)(id3[6]&0x7f)<<21) | ((uint32_t)(id3[7]&0x7f)<<14) |
                      ((uint32_t)(id3[8]&0x7f)<<7)  |  (uint32_t)(id3[9]&0x7f);
        off = 10 + sz + ((id3[5] & 0x10) ? 10 : 0);
    }
    if (off >= (uint32_t)total - 4) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    fseek(f, off, SEEK_SET);
    s_mp3_len = (int)fread(s_mp3_in, 1, MP3_IN_CAP, f);
    if (s_mp3_len < 8) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    mp3dec_init(s_mp3dec);
    mp3dec_frame_info_t info;
    /* pcm=NULL 只解析帧头、拿采样率/声道/码率，不真正解码 */
    int spf = mp3dec_decode_frame(s_mp3dec, s_mp3_in, s_mp3_len, NULL, &info);
    if (spf <= 0 || info.hz < 8000 || info.hz > 48000 || info.bitrate_kbps <= 0) {
        fclose(f);
        return ESP_ERR_NOT_SUPPORTED;
    }
    ...
}
