主循环改造：
```c
static void audio_task(void *arg)
{
    (void)arg;
    for (;;) {
        audio_cmd_t cmd;
        BaseType_t got = xQueueReceive(s_q, &cmd, (s_file && g_audio.playing) ? 0 : portMAX_DELAY);
        if (got == pdTRUE) handle_cmd(&cmd);
        if (!s_file || !g_audio.playing) continue;

        size_t bytes = 0;
        bool   eof_now = false;

        if (s_codec == CODEC_WAV) {
            uint32_t want = (SRC_BYTES / s_trk.frame_bytes) * s_trk.frame_bytes;
            if (!want) want = s_trk.frame_bytes;
            size_t n = fread(s_src, 1, want, s_file);
            if (n == 0) eof_now = true;
            else {
                bytes = pcm_convert(n);
                s_played += n;
            }
        } else if (s_codec == CODEC_MP3) {
            if (s_mp3_len < MP3_IN_CAP) mp3_refill();
            if (s_mp3_len < 8) { eof_now = true; }
            else {
                mp3dec_frame_info_t info;
                int samples = mp3dec_decode_frame(s_mp3dec, s_mp3_in, s_mp3_len, s_mp3_pcm, &info);
                int consumed = info.frame_bytes;
                if (consumed < 0) consumed = 0;
                if (consumed > s_mp3_len) consumed = s_mp3_len;
                mp3_consume(consumed);
                if (samples > 0) {
                    /* 采样率/声道变化（少见，VBR/拼接文件），重配 I2S */
                    if (info.hz > 0 && info.hz != s_trk.rate) {
                        ESP_LOGI(...);
                        if (i2s_set_rate(info.hz) == ESP_OK) {
                            s_trk.rate = info.hz;
                            g_audio.sample_rate = info.hz;
                        }
                    }
                    if (info.channels != s_trk.channels) { s_trk.channels = ...; g_audio.channels = ...; }
                    bytes = mp3_to_out(samples, info.channels);
                    s_decoded += samples;
                } else if (consumed == 0 && feof(s_file)) {
                    eof_now = true;
                }
                /* samples==0 且 consumed>0：跳过了垃圾/标签，继续下一轮 */
            }
        } else {
            eof_now = true;
        }

        if (eof_now) {
            amp_enable(false);
            g_audio.playing = false;
            g_audio.eof = true;
            g_audio.pos_ms = s_trk.dur_ms;
            publish();
            continue;
        }
        if (bytes == 0) continue;   /* 本轮没产出 PCM（如跳过 ID3），继续 */

        size_t written = 0;
        esp_err_t err = i2s_channel_write(s_tx, s_out, bytes, &written, 1000);
        if (err != ESP_OK) { ... }

        if (s_codec == CODEC_WAV)
            g_audio.pos_ms = (uint32_t)(((uint64_t)s_played*1000)/s_trk.bytes_per_sec);
        else
            g_audio.pos_ms = (uint32_t)(((uint64_t)s_decoded*1000)/s_trk.rate);
        if (g_audio.pos_ms > s_trk.dur_ms) g_audio.pos_ms = s_trk.dur_ms;
        publish();
    }
}
```

注意 MP3 分支里 `s_mp3_len < 8 && !feof` 的情况：refill 后如果还是 <8（文件小），`eof_now` 会被设为 true 即使还没 EOF。但如果文件确实很小，也确实该结束。OK。不过应该加 `feof(s_file)` 判断更严谨：`if (s_mp3_len < 8) { if (feof(s_file)) eof_now = true; else continue; }`。但如果缓冲 <8 且没 EOF（不可能，refill 会填满除非文件结束），所以直接 eof 也行。为避免死循环，直接 eof_now=true。嗯，若 `fread` 返回 0 但 `feof` 未置位（错误），也会结束，安全。

