`mp3_open(path)`:
```c
static esp_err_t mp3_open(const char *path)
{
    file_close();
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;
    fseek(f, 0, SEEK_END);
    long total = ftell(f);
    if (total < 128) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    /* ID3v2 跳过 */
    uint8_t id3[10];
    uint32_t off = 0;
    fseek(f, 0, SEEK_SET);
    if (fread(id3,1,10,f)==10 && !memcmp(id3,"ID3",3)) {
        uint32_t sz = ((uint32_t)(id3[6]&0x7F)<<21)|...;
        off = 10 + sz + ((id3[5]&0x10)?10:0);   // footer
    }
    if (off >= (uint32_t)total) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    /* 读一块探测首帧 */
    fseek(f, off, SEEK_SET);
    size_t n = fread(s_mp3_in, 1, MP3_IN_BYTES, f);
    if (n < 4) ...
    mp3dec_init(s_mp3dec);
    mp3dec_frame_info_t info;
    /* 先调用一次带 pcm=NULL 探测头信息（不解码） */
    int samples = mp3dec_decode_frame(s_mp3dec, s_mp3_in, (int)n, NULL, &info);
    if (samples <= 0 || info.hz == 0) → 不是有效 MP3
    ...
}
```

注意：`pcm=NULL` 时函数会 `memset(dec,0,...)` 然后找帧，设置 info，然后 `if (!pcm) return hdr_frame_samples(hdr);`。所以 info.frame_bytes 是首帧偏移+长度。这可用于 CBR 估算。

然后 Xing 解析：Xing 头位于第一帧 MP3 数据里，偏移取决于 MPEG 版本和声道模式。简化：在首帧数据 `[frame_offset+4 ... frame_offset+4+...]` 里搜索 "Xing"/"Info"/"VBRI"，找到后读 frame count。

其实 VBR 时长精度不是关键，但用户会觉得进度条不准很烦。我实现一个简化但有效的：
- 搜索整个前 4KB 输入缓冲里的 "Xing" / "Info"（字节扫描）
- 找到后：flags 在 tag+4，若 flags & 1，frame count 在 tag+8（big-endian）
- `dur_ms = frames * samples_per_frame * 1000 / hz`
- VBRI：在帧头后固定 32 字节处，frame count 在 VBRI+14（big-endian）。也顺手做。
- 否则 CBR：`dur_ms = (total - off) * 8000 / bitrate_kbps`

ID3v1 尾部 128 字节要扣除（如果是文本标签），影响很小，可忽略或检测。

`mp3_decode_frame()` 流式核心：
```c
/* 返回：>0 输出字节数，0 = 需要更多输入（或 EOF），<0 错误 */
static int mp3_pump(size_t *out_bytes, uint32_t *new_rate)
```

主循环改成：
```c
if (s_codec == CODEC_WAV) {
    ... 原逻辑 ...
} else {
    /* MP3 */
    if (s_mp3_len < MP3_REFILL_AT && !feof(s_file)) mp3_refill();
    if (s_mp3_len < 4) → EOF 处理
    mp3dec_frame_info_t info;
    int samples = mp3dec_decode_frame(s_mp3dec, s_mp3_in, s_mp3_len, s_mp3_pcm, &info);
    int consumed = info.frame_bytes;
    if (consumed > s_mp3_len) consumed = s_mp3_len;
    if (consumed > 0) { mp3_consume(consumed); }
    if (samples <= 0) {
        /* 没解出帧：如果文件已读完且缓冲耗尽 → EOF；否则继续 refill */
        if (consumed == 0 && feof(s_file)) → EOF
        continue;  // 注意不能死循环，consumed 应该 >0
    }
    /* 采样率变化 → 重配 */
    if (info.hz && info.hz != s_trk.rate) { ... }
    /* 转换到 s_out：mono 复制 + 音量 */
    size_t bytes = mp3_to_out(samples, info.channels);
    /* 写 I2S */
    ...
    s_decoded_samples += samples;
    g_audio.pos_ms = s_decoded_samples*1000/s_trk.rate;
