`mp3_refill()`：
```c
static void mp3_refill(void)
{
    if (s_mp3_len >= MP3_IN_CAP || !s_file) return;
    size_t n = fread(s_mp3_in + s_mp3_len, 1, MP3_IN_CAP - s_mp3_len, s_file);
    s_mp3_len += (int)n;
}
```

`mp3_consume(n)`：
```c
static void mp3_consume(int n)
{
    if (n <= 0) return;
    if (n >= s_mp3_len) { s_mp3_len = 0; return; }
    s_mp3_len -= n;
    memmove(s_mp3_in, s_mp3_in + n, s_mp3_len);
}
```

