{
    if (samples > MINIMP3_MAX_SAMPLES_PER_FRAME / 2) samples = ...;
    /* s_mp3_pcm 是 int16，交错，samples = 每声道样本数 */
    for (int i = 0; i < samples; i++) {
        int32_t l = s_mp3_pcm[i * channels];
        int32_t r = (channels == 2) ? s_mp3_pcm[i * channels + 1] : l;
        s_out[2*i]   = (int16_t)(l * s_volume / 100);
        s_out[2*i+1] = (int16_t)(r * s_volume / 100);
