        if (bytes == 0) continue;   /* 本轮没产出 PCM（如跳过 ID3），继续 */

        size_t written = 0;
        esp_err_t err = i2s_channel_write(s_tx, s_out, bytes, &written, 1000);
        if (err != ESP_OK) { ... }

