} track_info_t;
```

`wav_open` 基本照搬，填 `s_trk`，`s_fmt = FMT_WAV`，`s_trk.samples_per_frame = 0`。

`mp3_open`:
```c
static esp_err_t mp3_open(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (!f) return ESP_ERR_NOT_FOUND;

    fseek(f, 0, SEEK_END);
    long fsz = ftell(f);
    if (fsz < 16) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }

    /* 读开头一块用于探测（含 ID3v2） */
    size_t probe_len = fread(s_mp3_in, 1, MP3_IN_BYTES - 8, f)  // 注意 fseek 回 0 先
    ...
}
```
需要先 `fseek(f, 0, SEEK_SET)` 再读。

ID3v2 解析：
```c
uint32_t off = 0;
if (probe_len >= 10 && !memcmp(s_mp3_in, "ID3", 3)) {
    uint32_t tag = ((uint32_t)(s_mp3_in[6] & 0x7f) << 21) |
                   ((uint32_t)(s_mp3_in[7] & 0x7f) << 14) |
                   ((uint32_t)(s_mp3_in[8] & 0x7f) << 7) |
                   (uint32_t)(s_mp3_in[9] & 0x7f);
    off = 10 + tag + ((s_mp3_in[5] & 0x10) ? 10 : 0);  // footer flag 0x10
}
```
ID3v2 header: "ID3" + ver(2) + flags(1) + size(4 syncsafe)。flags bit4 (0x10) = footer present → +10。

若 `off >= probe_len` → 文件太小/标签太大 → NOT_SUPPORTED（或者应该重新从 off 读一块）。大 ID3（含封面）可能 > 4KB！这时探测缓冲不够。处理：若 `off >= probe_len`，则 `fseek(f, off, SEEK_SET)` 重新读一块到 `s_mp3_in`。我实现这个兜底。

探测帧头：
```c
mp3dec_t probe;
mp3dec_init(&probe);
mp3dec_frame_info_t info;
int spf = mp3dec_decode_frame(&probe, s_mp3_in + off, (int)(probe_len - off), NULL, &info);
```
