`mp3_pump(size_t *out_bytes, uint32_t *pos_ms)`：
```c
static bool mp3_pump(size_t *out_bytes)
{
    mp3_refill();
    if (s_mp3_len <= 0) return false;

    mp3dec_frame_info_t info;
    int samples = mp3dec_decode_frame(s_mp3dec, s_mp3_in, s_mp3_len, s_mp3_pcm, &info);
    int consumed = info.frame_bytes;
    if (consumed < 0) consumed = 0;
    if (consumed > s_mp3_len) consumed = s_mp3_len;

    bool got = (samples > 0);
    if (got) {
        int ch = info.channels;
        if (ch != 1 && ch != 2) ch = 2;
        /* 转成 16bit 双声道 + 音量 */
        for (int i = 0; i < samples; i++) {
            int32_t l = s_mp3_pcm[i*ch];
            int32_t r = (ch == 2) ? s_mp3_pcm[i*ch+1] : l;
            s_out[2*i] = (int16_t)(l * s_volume / 100);
            s_out[2*i+1] = (int16_t)(r * s_volume / 100);
        }
        *out_bytes = (size_t)samples * 4;
        s_decoded_samples += (uint64_t)samples;
        if (s_trk.rate) g_audio.pos_ms = (uint32_t)(s_decoded_samples * 1000 / s_trk.rate);
    }

    /* 消费已处理的字节 */
    if (consumed > 0) {
        s_mp3_len -= consumed;
        if (s_mp3_len > 0) memmove(s_mp3_in, s_mp3_in + consumed, s_mp3_len);
    }
    if (!got && consumed == 0) return false;   // 无法推进 → EOF
    if (!got && s_mp3_eof && s_mp3_len < 16) return false;
    return true;   // 本轮没有 PCM 产出，调用方 continue
}
```
注意 `s_out` 容量：`samples` 最大 1152（每帧），×2 = 2304 int16 = `MINIMP3_MAX_SAMPLES_PER_FRAME`。所以 `OUT_SAMPLES = MINIMP3_MAX_SAMPLES_PER_FRAME` (2304)。OK。

`s_mp3_pcm` 容量：解码 stereo 时 `samples*2 = 2304` int16 = 正好 `MINIMP3_MAX_SAMPLES_PER_FRAME`。OK。

但 `return true` 且 `*out_bytes == 0` 时调用方要 continue 而不是写 I2S。我让函数返回三态更清晰：用枚举或 int：`1` = 有 PCM，`0` = 需要继续（无产出），`-1` = EOF。调用方：
