  1927:static lv_obj_t  *g_music_title  = NULL;
  1928:static lv_obj_t  *g_music_slider = NULL;","totalLineCount":4453,"hasMore":true,"hint":""}}},"chatcmpl-tool-afb7d2c3a5310a10":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/audio_player.c","offset":200,"limit":210},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/audio_player.c","content":"   200:/* WAV 源 PCM → 16bit 双声道 + 软件音量，写入 s_out，返回字节数 */
   201:static size_t pcm_convert(size_t n)
   202:{
   203:    const int ch  = s_trk.channels;
   204:    const int bps = s_trk.bits / 8;
   205:    size_t frames = n / s_trk.frame_bytes;
   206:
   207:    for (size_t i = 0; i < frames; i++) {
   208:        int32_t l = 0, r = 0;
   209:        for (int c = 0; c < ch; c++) {
   210:            const uint8_t *p = s_src + (i * ch + c) * bps;
   211:            int32_t v;
   212:            switch (s_trk.bits) {
   213:            case 8:  v = ((int32_t)p[0] - 128) << 8; break;   /* 8bit WAV 是无符号 */
   214:            case 16: v = (int16_t)rd16(p); break;
   215:            case 24: v = (int16_t)(p[1] | ((uint16_t)p[2] << 8)); break;  /* 取高 16 位 */
   216:            default: v = (int32_t)rd32(p) >> 16; break;                     /* 32bit 取高 16 位 */
   217:            }
   218:            if (c == 0) l = v; else r = v;
   219:        }
   220:        if (ch == 1) r = l;                 /* 单声道复制到左右，避免只接了一边没声 */
   221:        s_out[2 * i]     = (int16_t)(l * s_volume / 100);
   222:        s_out[2 * i + 1] = (int16_t)(r * s_volume / 100);
   223:    }
   224:    return frames * 4;                     /* 16bit × 2ch */
   225:}
   226:
   227:/* ---------------- MP3 ----------------
   228: * minimp3 是「喂一块数据、解一帧」的流式解码器：
   229: *   mp3dec_decode_frame(dec, in, in_len, pcm, &info)
   230: *   返回每声道采样数；info.frame_bytes 是本次消耗的输入字节数。
   231: * 调用方必须按 frame_bytes 把输入窗口前移（保留未消费的尾部），否则会丢帧或死循环。
   232: * pcm=NULL 是官方支持的「只解析帧头」模式：不解码，info 里照样填好
   233: * hz / channels / bitrate_kbps / layer，正好用于打开文件时探测格式和估算时长。
   234: */
   235:static void mp3_refill(void)
   236:{
   237:    if (s_mp3_eof || !s_file || s_mp3_len >= MP3_IN_SAFE) return;
   238:    size_t room = MP3_IN_SAFE - (size_t)s_mp3_len;
   239:    size_t n = fread(s_mp3_in + s_mp3_len, 1, room, s_file);
   240:    s_mp3_len += (int)n;
   241:    if (n == 0 || feof(s_file)) {
   242:        s_mp3_eof = true;
   243:        /* 文件末尾只剩最后一帧时，minimp3 的 mp3d_match_frame 需要「下一帧头」
   244:         * 才能确认同步，否则最后一帧会被丢弃。追加当前帧头的 4 字节副本作为
   245:         * 伪下一帧头，让最后一帧也能正常解出（这 4 字节之后会被当垃圾消费掉）。 */
   246:        if (s_mp3_len >= 4) {
   247:            memcpy(s_mp3_in + s_mp3_len, s_mp3_in, 4);
   248:            s_mp3_len += 4;
   249:        }
   250:    }
   251:}
   252:
   253:static esp_err_t mp3_open(const char *path)
   254:{
   255:    FILE *f = fopen(path, "rb");
   256:    if (!f) return ESP_ERR_NOT_FOUND;
   257:
   258:    fseek(f, 0, SEEK_END);
   259:    long fsz = ftell(f);
   260:    if (fsz < 32) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }
   261:
   262:    /* 先读开头一块，用于跳过 ID3v2 并探测首个 MP3 帧头。
   263:     * file_off = 音频数据在文件中的绝对偏移；buf_off = 它在探测缓冲内的偏移。
   264:     * 两者在大 ID3v2 时不同，混用会越界，必须分开记。 */
   265:    fseek(f, 0, SEEK_SET);
   266:    size_t   probe_len = fread(s_mp3_in, 1, MP3_IN_SAFE, f);
   267:    uint32_t file_off  = 0;
   268:    size_t   buf_off   = 0;
   269:    if (probe_len >= 10 && !memcmp(s_mp3_in, "ID3", 3)) {
   270:        uint32_t tag = ((uint32_t)(s_mp3_in[6] & 0x7f) << 21) |
   271:                       ((uint32_t)(s_mp3_in[7] & 0x7f) << 14) |
   272:                       ((uint32_t)(s_mp3_in[8] & 0x7f) << 7)  |
   273:                       (uint32_t)(s_mp3_in[9] & 0x7f);
   274:        file_off = 10 + tag + ((s_mp3_in[5] & 0x10) ? 10 : 0);  /* 0x10=有 footer */
   275:        buf_off  = file_off;
   276:    }
   277:    /* 带大封面的 ID3v2 可能超过探测块：从音频起点重新读，缓冲内偏移归 0 */
   278:    if (buf_off + 8 >= probe_len) {
   279:        if (file_off >= (uint32_t)fsz - 8) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }
   280:        fseek(f, file_off, SEEK_SET);
   281:        probe_len = fread(s_mp3_in, 1, MP3_IN_SAFE, f);
   282:        buf_off = 0;
   283:    }
   284:    uint8_t *probe_ptr = s_mp3_in + buf_off;
   285:    int      probe_avail = (int)(probe_len - buf_off);
   286:    if (probe_len < 8 || probe_avail < 8) { fclose(f); return ESP_ERR_NOT_SUPPORTED; }
   287:
   288:    /* 探测复用 PSRAM 里的解码器实例：避免在栈上再放一个 6.7KB 的 mp3dec_t，
   289:     * 与 minimp3 内部 16KB 的 mp3dec_scratch_t 叠加会吃掉任务栈。
   290:     * pcm=NULL 只解析帧头、不写解码状态，之后 memset 复位即可正式使用。 */
   291:    memset(s_mp3dec, 0, sizeof(*s_mp3dec));   /* 清掉上一首残留的 header/状态 */
   292:    mp3dec_frame_info_t info;
   293:    int spf = mp3dec_decode_frame(s_mp3dec, probe_ptr, probe_avail, NULL, &info);
   294:    /* MINIMP3_ONLY_MP3 只编了 Layer III，Layer I/II 文件会全程静音，直接拒绝 */
   295:    if (spf <= 0 || info.layer != 3 || info.hz < 8000 || info.hz > 48000 ||
   296:        info.bitrate_kbps <= 0 ||
   297:        info.frame_offset < 0 || info.frame_offset + 4 > probe_avail) {
   298:        fclose(f);
   299:        return ESP_ERR_NOT_SUPPORTED;
   300:    }
   301:
   302:    /* 优先用 Xing/Info/VBRI 的精确帧数算时长（VBR），否则按首帧码率估算（CBR） */
   303:    uint32_t frames = 0;
   304:    const uint8_t *fp = probe_ptr + info.frame_offset;
   305:    int avail = probe_avail - info.frame_offset;
   306:    int scan = avail < 256 ? avail : 256;
   307:    for (int i = 0; i + 12 <= scan; i++) {
   308:        if (!memcmp(fp + i, "Xing", 4) || !memcmp(fp + i, "Info", 4)) {
   309:            if (be32(fp + i + 4) & 1) frames = be32(fp + i + 8);
   310:            break;
   311:        }
   312:        if (i + 18 <= scan && !memcmp(fp + i, "VBRI", 4)) {
   313:            frames = be32(fp + i + 14);
   314:            break;
   315:        }
   316:    }
   317:
   318:    uint32_t audio_bytes = (uint32_t)fsz - file_off;
   319:    uint8_t  tail[3];
   320:    if (fsz >= 131 && fseek(f, fsz - 128, SEEK_SET) == 0 &&
   321:        fread(tail, 1, 3, f) == 3 && !memcmp(tail, "TAG", 3)) {
   322:        audio_bytes -= 128;                  /* 扣掉 ID3v1 尾部 */
   323:    }
   324:
   325:    if (frames > 0) {
   326:        s_trk.dur_ms = (uint32_t)(((uint64_t)frames * (uint32_t)spf * 1000) / info.hz);
   327:    } else {
   328:        /* bytes × 8bit / (kbps×1000 bit/s) × 1000 ms = bytes × 8 / kbps */
   329:        s_trk.dur_ms = (uint32_t)(((uint64_t)audio_bytes * 8) / (uint32_t)info.bitrate_kbps);
   330:    }
   331:
   332:    s_trk.rate              = (uint32_t)info.hz;
   333:    s_trk.channels          = (uint16_t)info.channels;
   334:    s_trk.bits              = 16;            /* 解码器输出 16bit PCM */
   335:    s_trk.data_off          = file_off;
   336:    s_trk.data_size         = audio_bytes;
   337:    s_trk.samples_per_frame = (uint32_t)spf;
   338:    s_fmt = FMT_MP3;
   339:    s_file = f;
   340:
   341:    /* 从音频起点正式开始解码：探测时 mp3d_find_frame 会写 free_format_bytes
   342:     * 等状态，需整块清零（mp3dec_init 只清 header[0]，不够） */
   343:    memset(s_mp3dec, 0, sizeof(*s_mp3dec));
   344:    s_mp3_len = 0;
   345:    s_mp3_eof = false;
   346:    fseek(f, file_off, SEEK_SET);
   347:    ESP_LOGI(TAG, "MP3 %uHz %uch %dkbps %ums (%s)", (unsigned)s_trk.rate,
   348:             (unsigned)s_trk.channels, info.bitrate_kbps, (unsigned)s_trk.dur_ms,
   349:             frames > 0 ? "VBR/Xing" : "CBR 估算");
   350:    return ESP_OK;
   351:}
   352:
   353:/* 返回 1=s_out 中有数据待写，0=本轮无产出需继续，-1=播放结束 */
   354:static int mp3_pump(size_t *out_bytes)
   355:{
   356:    mp3_refill();
   357:    if (s_mp3_len <= 0) return -1;
   358:
   359:    mp3dec_frame_info_t info;
   360:    int samples = mp3dec_decode_frame(s_mp3dec, s_mp3_in, s_mp3_len, s_mp3_pcm, &info);
   361:    int consumed = info.frame_bytes;
   362:    if (consumed < 0) consumed = 0;
   363:    if (consumed > s_mp3_len) consumed = s_mp3_len;
   364:
   365:    bool got = samples > 0;
   366:    if (got) {
   367:        int ch = (info.channels == 1 || info.channels == 2) ? info.channels : 2;
   368:        /* minimp3 输出 int16 交错 PCM；统一扩成双声道并施加软件音量 */
   369:        for (int i = 0; i < samples; i++) {
   370:            int32_t l = s_mp3_pcm[i * ch];
   371:            int32_t r = (ch == 2) ? s_mp3_pcm[i * ch + 1] : l;
   372:            s_out[2 * i]     = (int16_t)(l * s_volume / 100);
   373:            s_out[2 * i + 1] = (int16_t)(r * s_volume / 100);
   374:        }
   375:        *out_bytes = (size_t)samples * 4;   /* 16bit × 2ch */
   376:        s_decoded += (uint64_t)samples;
   377:        /* 进度按真实解码出的采样数算，VBR 也准（与 I2S 实际输出同步） */
   378:        g_audio.pos_ms = (uint32_t)((s_decoded * 1000) / s_trk.rate);
   379:    }
