  1909:/* ===================== 音乐播放 =====================
  1910: * SD 卡 WAV(PCM) → audio_player 解码 → I2S → MAX98357A 真正出声。
  1911: * UI 只发命令、按 g_audio.version 轮询刷新，不碰 I2S，也不需要 LVGL 锁。
  1912: * 进度由「实际写给 I2S 的字节数」推进，与真实播放速度天然一致；播完自动下一首。
  1913: * 目前只支持未压缩 PCM WAV（8/16/24/32 位、单/双声道）；
  1914: * MP3/FLAC/OGG 需先引入解码组件，扫描时会被过滤掉。
  1915: * ============================================================== */
  1916:#define MUSIC_MAX_FILES   64
  1917:#define MUSIC_DIR         "/sdcard"
  1918:
  1919:static char       g_music_files[MUSIC_MAX_FILES][384];
  1920:static int        g_music_count = 0;
  1921:static int        g_music_cur   = -1;
  1922:static uint32_t   s_music_shown_ver = 0;   /* 上次刷新过的 g_audio.version */
  1923:static lv_timer_t *s_music_timer = NULL;
  1924:static char       s_music_pending_path[384];  /* 文件管理器请求播放的路径 */
  1925:static bool       s_music_pending = false;
  1926:
  1927:static lv_obj_t  *g_music_title  = NULL;
  1928:static lv_obj_t  *g_music_slider = NULL;","totalLineCount":4453,"hasMore":true,"hint":""}},"isError":false},{"type":"tool-result","toolCallId":"chatcmpl-tool-afb7d2c3a5310a10","toolName":"read_file","result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/audio_player.c","content":"   200:/* WAV 源 PCM → 16bit 双声道 + 软件音量，写入 s_out，返回字节数 */
   201:static size_t pcm_convert(size_t n)
   202:{
   203:    const int ch  = s_trk.channels;
   204:    const int bps = s_trk.bits / 8;
   205:    size_t frames = n / s_trk.frame_bytes;
   206:
   207:    for (size_t i = 0; i < frames; i++) {
   208:        int32_t l = 0, r = 0;
   209:        for (int c = 0; c < ch; c++) {
   210:            const uint8_t *p = s_src + (i * ch + c) * bps;
   211:            int32_t v;
   212:            switch (s_trk.bits) {
   213:            case 8:  v = ((int32_t)p[0] - 128) << 8; break;   /* 8bit WAV 是无符号 */
   214:            case 16: v = (int16_t)rd16(p); break;
   215:            case 24: v = (int16_t)(p[1] | ((uint16_t)p[2] << 8)); break;  /* 取高 16 位 */
   216:            default: v = (int32_t)rd32(p) >> 16; break;                     /* 32bit 取高 16 位 */
   217:            }
   218:            if (c == 0) l = v; else r = v;
   219:        }
   220:        if (ch == 1) r = l;                 /* 单声道复制到左右，避免只接了一边没声 */
   221:        s_out[2 * i]     = (int16_t)(l * s_volume / 100);
   222:        s_out[2 * i + 1] = (int16_t)(r * s_volume / 100);
   223:    }
   224:    return frames * 4;                     /* 16bit × 2ch */
   225:}
