    74:static bool js_get_double(const char *s, const char *key, double *out)
    75:{
    76:    const char *from = s;
    77:    while (1) {
    78:        const char *v = js_find_val_from(from, key);
    79:        if (!v) {
    80:            return false;
    81:        }
    82:        /* Open-Meteo 在 current_units 里用同名键、但值是字符串单位（如 "°C"），
    83:         * 跳过字符串型值，继续找下一个同名键，直到命中数值那次。 */
    84:        if (*v == '"') {
    85:            from = v + 1;
    86:            continue;
    87:        }
    88:        char *end = NULL;
    89:        double val = strtod(v, &end);
    90:        if (end == v) {                       /* 没解析到数字，继续找下一个 */
    91:            from = v + 1;
    92:            continue;
    93:        }
    94:        *out = val;
    95:        return true;
    96:    }
    97:}
