   104:    }
   105:    const char *q = v + 1;
   106:    size_t i = 0;
   107:    while (*q && *q != '"' && i + 1 < n) {
   108:        out[i++] = *q++;
   109:    }
   110:    out[i] = '\0';
   111:    return i > 0;
   112:}
