   152:static esp_err_t http_get(const char *url, char *buf, size_t cap)
   153:{
   154:    esp_http_client_config_t cfg = {
   155:        .url = url,
   156:        .crt_bundle_attach = esp_crt_bundle_attach, /* 用 ESP 内置 CA 包校验 Let's Encrypt 等证书 */
   157:        .user_agent = "esp32-weather/1.0",          /* 部分 CDN/服务器会拦截无 UA 的请求 */
   158:        .timeout_ms = 15000,
   159:    };
   160:    esp_http_client_handle_t c = esp_http_client_init(&cfg);
   161:    if (!c) {
   162:        return ESP_FAIL;
   163:    }
   164:    /* 强制服务器返回未压缩内容；即便返回 gzip，开启 CONFIG_ESP_HTTP_CLIENT_ENABLE_GZIP
   165:     * 后 esp_http_client 也会自动解压，避免拿到二进制导致 JSON 解析失败。 */
   166:    esp_http_client_set_header(c, "Accept-Encoding", "identity");
   167:
   168:    esp_err_t err = ESP_FAIL;
   169:    if (esp_http_client_open(c, 0) == ESP_OK) {          /* 0 = GET，无请求体 */
   170:        int content_length = esp_http_client_fetch_headers(c);
   171:        int status = esp_http_client_get_status_code(c);
   172:        if (status == 200) {
   173:            int total = 0, r;
   174:            while (total < (int)cap - 1 &&
   175:                   (r = esp_http_client_read(c, buf + total, cap - 1 - total)) > 0) {
   176:                total += r;
   177:            }
   178:            buf[total] = '\0';
   179:            err = ESP_OK;
   180:        } else {
   181:            ESP_LOGE(TAG, "HTTP status %d for %s", status, url);
   182:            buf[0] = '\0';
   183:            err = ESP_FAIL;
   184:        }
   185:        (void)content_length;
   186:    } else {
   187:        ESP_LOGE(TAG, "HTTP open failed for %s", url);
   188:        buf[0] = '\0';
   189:    }
   190:    esp_http_client_cleanup(c);
   191:    return err;
   192:}
