    47:/* 找到 "key": 之后值的起始位置（要求 key 被双引号包裹，避免误命中值里的内容）。
    48: * 返回值可能是字符串（以 " 开头）或数值；由调用方按类型处理。
    49: * 用 from 指定搜索起点，便于 js_get_double 跳过同名字符串值后继续找下一个。 */
    50:static const char *js_find_val_from(const char *from, const char *key)
    51:{
    52:    size_t kl = strlen(key);
    53:    const char *p = from;
    54:    while ((p = strstr(p, key)) != NULL) {
    55:        if (p > from && p[-1] == '"' && p[kl] == '"') {
    56:            const char *c = p + kl + 1;
    57:            while (*c && *c != ':' && *c != '}' && *c != ',') c++;
    58:            if (*c == ':') {
    59:                const char *v = c + 1;
    60:                while (*v == ' ' || *v == '\t' || *v == '\n' || *v == '\r') v++;
    61:                return v;
    62:            }
    63:        }
    64:        p += kl;
    65:    }
    66:    return NULL;
    67:}
