   223:        return false;
   224:    }
   225:    if (sscanf(loc, "%lf,%lf", lat, lon) != 2) {
   226:        return false;
   227:    }
   228:    if (!js_get_str(buf, "city", city, n)) {
   229:        strncpy(city, "Unknown", n - 1);
   230:        city[n - 1] = '\0';
   231:    }
   232:    ESP_LOGI(TAG, "auto locate: %s (%.4f, %.4f)", city, *lat, *lon);
   233:    return true;
   234:}
