   295:                strncpy(s_loc_city, cname, sizeof(s_loc_city) - 1);
   296:                s_loc_city[sizeof(s_loc_city) - 1] = '\0';
   297:                s_loc_valid = true;
   298:            } else {
   299:                /* 自动定位失败，回退到默认城市地理编码 */
   300:                strncpy(cname, WX_DEFAULT_CITY, sizeof(cname) - 1);
   301:                cname[sizeof(cname) - 1] = '\0';
   302:
   303:                char geo_url[256];
   304:                snprintf(geo_url, sizeof(geo_url), WX_GEO_URL, WX_DEFAULT_CITY);
   305:                url_encode_spaces(geo_url, sizeof(geo_url));
   306:
   307:                esp_err_t geo_err = http_get(geo_url, geo, sizeof(geo));
   308:                if (geo_err == ESP_OK &&
   309:                    js_get_double(geo, "latitude", &lat) &&
   310:                    js_get_double(geo, "longitude", &lon) &&
   311:                    js_get_str(geo, "name", cname, sizeof(cname))) {
   312:                    ESP_LOGI(TAG, "geocode ok (fallback): %s (%.4f, %.4f)", cname, lat, lon);
   313:                } else {
   314:                    if (geo_err == ESP_OK) {
   315:                        ESP_LOGW(TAG, "geocode parse failed, body: %.*s",
   316:                                 (int)strnlen(geo, 160), geo);
   317:                    }
   318:                    ESP_LOGW(TAG, "auto locate & geocode failed, use default coords");
   319:                }
   320:            }
   321:        }
   322:
   323:        /* 2) 当前天气：经纬度 -> 实况 */
   324:        char fc_url[256];
   325:        snprintf(fc_url, sizeof(fc_url), WX_FC_URL, lat, lon);
   326:
   327:        double temp = 0, hum = 0, wind = 0, d_code = 0;
   328:        esp_err_t fc_err = http_get(fc_url, fc, sizeof(fc));
   329:        if (fc_err == ESP_OK &&
   330:            js_get_double(fc, "temperature_2m", &temp) &&
   331:            js_get_double(fc, "relative_humidity_2m", &hum) &&
   332:            js_get_double(fc, "weather_code", &d_code) &&
   333:            js_get_double(fc, "wind_speed_10m", &wind)) {
