   335:            g_weather.temp     = (float)temp;
   336:            g_weather.humidity = (int)hum;
   337:            g_weather.code     = (int)d_code;
   338:            g_weather.wind     = (float)wind;
   339:            strncpy(g_weather.city, cname, sizeof(g_weather.city) - 1);
   340:            g_weather.city[sizeof(g_weather.city) - 1] = '\0';
   341:            wmo_desc(g_weather.code, g_weather.desc, sizeof(g_weather.desc));
   342:            g_weather.updated_ms = esp_timer_get_time() / 1000;
   343:            g_weather.valid   = true;
   344:            g_weather.error   = false;
   345:            g_weather.version++;
   346:            ESP_LOGI(TAG, "weather updated: %s %.1fC %s (RH %d%%, wind %.1f km/h)",
   347:                     cname, temp, g_weather.desc, g_weather.humidity, wind);
   348:        } else {
   349:            if (fc_err == ESP_OK) {
   350:                ESP_LOGW(TAG, "forecast parse failed, body: %.*s",
   351:                         (int)strnlen(fc, 160), fc);
   352:            }
   353:            g_weather.error = true;
   354:            ESP_LOGW(TAG, "forecast fetch/parse failed");
   355:        }
   356:
   357:        g_weather.fetching = false;
   358:    }
   359:}
