/* ---------------- 备用天气源：wttr.in ---------------- */
/*
 * api.open-meteo.com 在部分网络（尤其国内）TCP 完全不可达，但同网络的
 * wttr.in 可达。wttr.in 使用 Let's Encrypt 证书，ESP-IDF 内置 crt_bundle
 * 可校验（已用 components/mbedtls/esp_crt_bundle/cacrt_all.pem 实测），
 * 免费、无需 API Key。仅当主源失败时启用，主源恢复后自动回到 Open-Meteo。
 *
 * 精简格式 "%%t,%%h,%%w,%%C" 返回一行（printf 的 %% 转义成字面 %）：
 *   \r\n+25°C,67%,←12km/h,Patchy rain nearby
 * 比 j1 完整 JSON（25KB）省得多，2KB 缓冲绰绰有余。
 */
#define WX_ALT_URL "https://wttr.in/%s?format=%%t,%%h,%%w,%%C"

/* 跳过前缀里的非数字字符（如风速 "←12km/h" 的 UTF-8 箭头），再取数值 */
static bool num_after_prefix(const char *s, double *out)
{
    const char *p = s;
    while (*p && !(*p >= '0' && *p <= '9') && *p != '+' && *p != '-' && *p != '.') p++;
    if (!*p) return false;
    char *end = NULL;
    double v = strtod(p, &end);
    if (end == p) return false;
    *out = v;
    return true;
}

/* wttr.in 给的是英文天气描述，粗映射到 WMO code 以复用现有中文文案表 */
static int wttr_to_wmo(const char *d)
{
    char low[96];
    size_t i = 0;
    for (; d[i] && i + 1 < sizeof(low); i++) low[i] = (char)tolower((unsigned char)d[i]);
    low[i] = '\0';

    if (strstr(low, "thunder") || strstr(low, "lightning")) return 95;
    if (strstr(low, "sleet") || strstr(low, "freezing") || strstr(low, "ice")) return 66;
    if (strstr(low, "snow") || strstr(low, "blizzard")) return 71;
    if (strstr(low, "heavy rain") || strstr(low, "torrential")) return 65;
    if (strstr(low, "moderate rain")) return 63;
    if (strstr(low, "rain") || strstr(low, "shower") || strstr(low, "drizzle")) return 61;
    if (strstr(low, "fog") || strstr(low, "mist") || strstr(low, "haze")) return 45;
    if (strstr(low, "overcast")) return 3;
    if (strstr(low, "cloud")) return 2;
    if (strstr(low, "clear") || strstr(low, "sunny")) return 0;
    return 2;   /* 认不出就按"多云" */
}

/* 主源失败时的兜底：成功则直接写 g_weather 并返回 true */
static bool wx_alt_fetch(const char *city)
{
    char city_q[64], url[256], buf[512];
    strncpy(city_q, city, sizeof(city_q) - 1);
    city_q[sizeof(city_q) - 1] = '\0';
    url_encode_spaces(city_q, sizeof(city_q));
    snprintf(url, sizeof(url), WX_ALT_URL, city_q);

    esp_err_t e = http_get(url, buf, sizeof(buf));
    if (e != ESP_OK) {
        ESP_LOGW(TAG, "alt source wttr.in request failed: %s", esp_err_to_name(e));
        return false;
    }

    /* wttr.in 输出以 CRLF 开头；跳过前导空白，并用逗号切 4 段 */
    char *p = buf;
    while (*p == '\r' || *p == '\n' || *p == ' ' || *p == '\t') p++;
    char *f1 = strchr(p, ',');
    if (!f1) { ESP_LOGW(TAG, "alt source bad format: %.*s", 120, buf); return false; }
    *f1 = '\0';
    char *f2 = strchr(f1 + 1, ',');
    if (!f2) { ...; return false; }
    *f2 = '\0';
    char *f3 = strchr(f2 + 1, ',');
    if (!f3) { ...; return false; }
    *f3 = '\0';
    const char *s_temp = p, *s_hum = f1+1, *s_wind = f2+1, *s_desc = f3+1;

    /* 末尾的 CRLF / 空白去掉 */
    char *end = (char *)s_desc + strlen(s_desc);
    while (end > s_desc && (end[-1]=='\r' || end[-1]=='\n' || end[-1]==' ')) *--end = '\0';

    double temp, hum, wind;
