/* 跳过前缀里的非数字字符（风速 "←12km/h" 前面有 UTF-8 箭头），再取数值 */
static bool num_after_prefix(const char *s, double *out)
{
    const char *p = s;
    while (*p && !(*p >= '0' && *p <= '9') && *p != '+' && *p != '-' && *p != '.') p++;
    if (!*p) return false;
    char *end = NULL;
    double v = strtod(p, &end);
