    *out = v;
    return true;
}

/* wttr.in 给英文天气描述，粗映射成 WMO code 以复用现有中文文案表 wmo_desc() */
static int wttr_to_wmo(const char *d)
{
    char low[96];
    size_t i = 0;
    for (; d[i] && i + 1 < sizeof(low); i++) {
        low[i] = (char)tolower((unsigned char)d[i]);
    }
    low[i] = '\0';

    if (strstr(low, "thunder") || strstr(low, "lightning")) return 95;
    if (strstr(low, "sleet") || strstr(low, "freezing") || strstr(low, "ice")) return 66;
    if (strstr(low, "snow") || strstr(low, "blizzard")) return 71;
    if (strstr(low, "heavy rain") || strstr(low, "torrential")) return 65;
    if (strstr(low, "moderate rain")) return 63;
    if (strstr(low, "rain") || strstr(low, "shower") || strstr(low, "drizzle")) return 61;
    if (strstr(low, "fog") || strstr(low, "mist") || strstr(low, "haze")) return 45;
    if (strstr(low, "overcast")) return 3;
    if (strstr(low, "cloud")) return 2;
    if (strstr(low, "clear") || strstr(low, "sunny")) return 0;
    return 2;                       /* 认不出就按「多云」 */
}

