/* 跳过前缀里的非数字字符（风速 "←12km/h" 前面有 UTF-8 箭头），再取数值 */
static bool num_after_prefix(const char *s, double *out)
{
    const char *p = s;
    while (*p && !(*p >= '0' && *p <= '9') && *p != '+' && *p != '-' && *p != '.') p++;
    if (!*p) return false;
    char *end = NULL;
    double v = strtod(p, &end);
    if (end == p) return false;
    *out = v;
    return true;
}

/* wttr.in 给英文天气描述，粗映射成 WMO code 以复用现有中文文案表 wmo_desc() */
static int wttr_to_wmo(const char *d)
{
    char low[96];
    size_t i = 0;
    for (; d[i] && i + 1 < sizeof(low); i++) {
        low[i] = (char)tolower((unsigned char)d[i]);
    }
    low[i] = '\0';

    if (strstr(low, "thunder") || strstr(low, "lightning")) return 95;
    if (strstr(low, "sleet") || strstr(low, "freezing") || strstr(low, "ice")) return 66;
    if (strstr(low, "snow") || strstr(low, "blizzard")) return 71;
    if (strstr(low, "heavy rain") || strstr(low, "torrential")) return 65;
    if (strstr(low, "moderate rain")) return 63;
    if (strstr(low, "rain") || strstr(low, "shower") || strstr(low, "drizzle")) return 61;
    if (strstr(low, "fog") || strstr(low, "mist") || strstr(low, "haze")) return 45;
    if (strstr(low, "overcast")) return 3;
    if (strstr(low, "cloud")) return 2;
    if (strstr(low, "clear") || strstr(low, "sunny")) return 0;
    return 2;                       /* 认不出就按「多云」 */
}

/* 主源失败时的兜底：成功则直接写 g_weather 并返回 true */
static bool wx_alt_fetch(const char *city)
{
    char city_q[64], url[256], buf[512];
    strncpy(city_q, city, sizeof(city_q) - 1);
    city_q[sizeof(city_q) - 1] = '\0';
    url_encode_spaces(city_q, sizeof(city_q));
    snprintf(url, sizeof(url), WX_ALT_URL, city_q);

    esp_err_t e = http_get(url, buf, sizeof(buf));
    if (e != ESP_OK) {
        ESP_LOGW(TAG, "alt source wttr.in request failed: %s", esp_err_to_name(e));
        return false;
    }

    /* wttr.in 输出以 CRLF 开头；跳过前导空白后用逗号切成 4 段 */
    char *p = buf;
    while (*p == '\r' || *p == '\n' || *p == ' ' || *p == '\t') p++;
    char *f1 = strchr(p, ',');
    char *f2 = f1 ? strchr(f1 + 1, ',') : NULL;
    char *f3 = f2 ? strchr(f2 + 1, ',') : NULL;
    if (!f3) {
        ESP_LOGW(TAG, "alt source bad format: %.*s", 120, buf);
        return false;
    }
    *f1 = '\0'; *f2 = '\0'; *f3 = '\0';
    const char *s_temp = p, *s_hum = f1 + 1, *s_wind = f2 + 1, *s_desc = f3 + 1;

    /* 去掉描述末尾的 CRLF / 空格 */
    char *tail = (char *)s_desc + strlen(s_desc);
    while (tail > s_desc && (tail[-1] == '\r' || tail[-1] == '\n' || tail[-1] == ' ')) {
        *--tail = '\0';
    }

    double temp = 0, hum = 0, wind = 0;
    if (!num_after_prefix(s_temp, &temp) ||
        !num_after_prefix(s_hum, &hum)  ||
        !num_after_prefix(s_wind, &wind) ||
        temp < -100 || temp > 100 || hum < 0 || hum > 100 || wind < 0) {
        ESP_LOGW(TAG, "alt source parse failed: %.*s", 120, buf);
        return false;
    }

    g_weather.temp     = (float)temp;
    g_weather.humidity = (int)hum;
    g_weather.wind     = (float)wind;
    g_weather.code     = wttr_to_wmo(s_desc);
    strncpy(g_weather.city, city, sizeof(g_weather.city) - 1);
    g_weather.city[sizeof(g_weather.city) - 1] = '\0';
    wmo_desc(g_weather.code, g_weather.desc, sizeof(g_weather.desc));
    g_weather.updated_ms = esp_timer_get_time() / 1000;
    g_weather.valid   = true;
    g_weather.error   = false;
    g_weather.version++;
    ESP_LOGI(TAG, "weather updated [wttr.in 备用源]: %s %.1fC %s (RH %d%%, wind %.1f km/h, %s)",
             city, temp, g_weather.desc, g_weather.humidity, wind, s_desc);
    return true;
}
