  1883:/* 只在「需要」时才请求天气，避免不必要的联网：
  1884: *   - 不在天气界面时，周期刷新整个跳过（见 ui_weather_periodic）；
  1885: *   - 进入界面时若数据仍然新鲜就不重复请求，来回切界面不会反复拉；
  1886: *   - force=true 用于手动点「刷新」，无视新鲜度强制拉一次。
  1887: * 返回是否真的发出了请求（weather_request 只是唤醒后台任务，不阻塞）。 */
  1888:static bool ui_weather_refresh_if_needed(bool force)
  1889:{
  1890:    if (g_wifi_state != WIFI_STA_CONNECTED) return false;
  1891:
  1892:    /* 上一次请求还在进行中，不再重复发，避免请求排队堆积 */
  1893:    if (g_weather.fetching) return false;
  1894:
  1895:    uint32_t now = lv_tick_get();
  1896:    /* 有过成功数据时按 10 分钟刷新；从未成功/上次失败时按 60 秒退避重试。
  1897:     * 旧写法是 (!stale && g_weather.valid)，valid=false 时守卫失效，
  1898:     * 导致每个 UI tick 都重发请求（15s 超时 + 立即重试的刷屏死循环）。 */
  1899:    uint32_t interval = g_weather.valid ? WX_REFRESH_MS : WX_RETRY_MS;
