   162:    uint16_t format = 0;
   163:    uint8_t  ck[8];
   164:    while (fread(ck, 1, 8, f) == 8) {
   165:        uint32_t sz = rd32(ck + 4);
   166:        long pos = ftell(f);
   167:        if (!memcmp(ck, "fmt ", 4)) {
   168:            uint8_t fmt[16];
   169:            size_t  n = sz < sizeof(fmt) ? sz : sizeof(fmt);
   170:            if (fread(fmt, 1, n, f) == n && n >= 16) {
   171:                format          = rd16(fmt);
   172:                s_trk.channels  = rd16(fmt + 2);
   173:                s_trk.rate      = rd32(fmt + 4);
   174:                s_trk.bits      = rd16(fmt + 14);
   175:            }
   176:        } else if (!memcmp(ck, "data", 4)) {
   177:            s_trk.data_off  = (uint32_t)pos;
   178:            s_trk.data_size = sz;
   179:            break;
   180:        }
   181:        fseek(f, pos + sz + (sz & 1), SEEK_SET);   /* RIFF chunk 按偶数字节对齐 */
   182:    }
