   191:    s_trk.frame_bytes   = (uint32_t)s_trk.channels * (s_trk.bits / 8);
   192:    s_trk.bytes_per_sec = s_trk.rate * s_trk.frame_bytes;
   193:    s_trk.dur_ms        = (uint32_t)(((uint64_t)s_trk.data_size * 1000) / s_trk.bytes_per_sec);
   194:    s_fmt = FMT_WAV;
