  1923:static char       g_music_files[MUSIC_MAX_FILES][384];
  1924:static int        g_music_count = 0;
  1925:static int        g_music_cur   = -1;
  1926:static uint32_t   s_music_shown_ver = 0;   /* 上次刷新过的 g_audio.version */
  1927:static lv_timer_t *s_music_timer = NULL;
  1928:static char       s_music_pending_path[384];  /* 文件管理器请求播放的路径 */
  1929:static bool       s_music_pending = false;
  1930:
  1931:static lv_obj_t  *g_music_title  = NULL;
  1932:static lv_obj_t  *g_music_slider = NULL;
  1933:static lv_obj_t  *g_music_time   = NULL;
  1934:static lv_obj_t  *g_music_time_r = NULL;   /* 进度条右侧：总时长 */
  1935:static lv_obj_t  *g_music_play_btn = NULL;
  1936:static lv_obj_t  *g_music_play_lbl = NULL;
  1937:static lv_obj_t  *g_music_vol_slider = NULL;
