  1939:static const char *music_base(const char *p)
  1940:{
  1941:    const char *s = strrchr(p, '/');
  1942:    return s ? s + 1 : p;
  1943:}
  1944:
  1945:/* 扫描 SD 卡根目录，只收当前解码器能播的文件（PCM WAV）。
  1946: * 时长不再估算 —— 由 audio_player 从 WAV 头精确计算。 */
  1947:static void music_scan(void)
  1948:{
  1949:    g_music_count = 0;
  1950:    g_music_cur   = -1;
  1951:    DIR *d = opendir(MUSIC_DIR);
  1952:    if (!d) return;
  1953:    struct dirent *ent;
  1954:    while ((ent = readdir(d)) != NULL && g_music_count < MUSIC_MAX_FILES) {
  1955:        if (!audio_player_supported(ent->d_name)) continue;
  1956:        snprintf(g_music_files[g_music_count], sizeof(g_music_files[0]),
  1957:                 "%s/%s", MUSIC_DIR, ent->d_name);
  1958:        g_music_count++;
  1959:    }
  1960:    closedir(d);
  1961:}
  1962:
  1963:/* 把后台任务的提示文本拷到普通缓冲（g_audio.hint 是 volatile char[]，
  1964: * 直接传给 LVGL 会有 volatile 限定符问题，且可能读到写一半的内容） */
  1965:static void music_copy_hint(char *dst, size_t cap)
