  1978:    snprintf(b2, sizeof(b2), "%u:%02u", (unsigned)(dur_s / 60), (unsigned)(dur_s % 60));
  1979:    lv_label_set_text(g_music_time, b1);     /* 左侧：当前 */
  1980:    lv_label_set_text(g_music_time_r, b2);   /* 右侧：总时长 */
  1981:}
