{
    uint8_t h[44] = {0};
    memcpy(h + 0, "RIFF", 4);
    put_u32le(h + 4, 36);          /* 占位，录完回填 36 + data */
    memcpy(h + 8, "WAVE", 4);
    memcpy(h + 12, "fmt ", 4);
    put_u32le(h + 16, 16);
    put_u16le(h + 20, 1);          /* PCM */
    put_u16le(h + 22, 1);          /* mono */
    put_u32le(h + 24, rate);
    put_u32le(h + 28, rate * 2);   /* byte rate: 16bit mono */
    put_u16le(h + 32, 2);          /* block align */
    put_u16le(h + 34, 16);         /* bits */
    memcpy(h + 36, "data", 4);
    put_u32le(h + 40, 0);          /* 占位 */
    return fwrite(h, 1, sizeof(h), f) == sizeof(h);
}
```

回填：
```c
static void wav_finalize(FILE *f, uint32_t data_bytes)
{
    uint8_t v[4];
    put_u32le(v, 36 + data_bytes);
    fseek(f, 4, SEEK_SET); fwrite(v, 1, 4, f);
    put_u32le(v, data_bytes);
    fseek(f, 40, SEEK_SET); fwrite(v, 1, 4, f);
    fflush(f);
}
