```c
#pragma once
#include <stdbool.h>
#include <stdint.h>
#include "esp_err.h"

/* 录音引擎：I2S 数字麦克风 → 16bit PCM WAV → /sdcard
 * 独立 I2S_NUM_1 控制器，与播放用的 I2S_NUM_0 完全隔离。
 * 全局状态 + version 轮询范式（与 audio_player.c / pc_mon.c 同构）。 */
typedef struct {
    volatile uint32_t version;
    volatile bool     recording;
    volatile uint32_t elapsed_ms;
    volatile uint32_t bytes_written;   /* 已写入的 PCM 字节数 */
    volatile uint8_t  peak;            /* 0..100 峰值电平 */
    volatile char     hint[40];
    volatile char     last_file[64];   /* 最近一次成功保存的路径 */
} mic_state_t;

extern volatile mic_state_t g_mic;

void mic_rec_init(void);
esp_err_t mic_rec_start(void);   /* 异步：投递命令后立即返回 */
void mic_rec_stop(void);
bool mic_rec_is_recording(void);
```

