static void record_session(void)
{
    ...打开文件...
    i2s start
    uint32_t data_bytes = 0;
    while (1) {
        // 检查 stop 命令
        cmd_t c;
        if (xQueueReceive(s_q, &c, 0) == pdTRUE) {
            if (c == CMD_STOP) break;
            if (c == CMD_START) { /* 忽略重复 start */ }
        }
        if (data_bytes >= max) break;
        size_t want = MIC_FRAME_SAMPLES * 8;
        size_t got = 0;
        esp_err_t e = i2s_channel_read(rx, s_raw, want, &got, pdMS_TO_TICKS(500));
        ...
        frames = got / 8;
        bytes = mic_convert(...);
        if (fwrite(s_pcm, 1, bytes, f) != bytes) { err hint "SD 写入失败"; break; }
        data_bytes += bytes;
        g_mic.elapsed_ms = data_bytes * 1000 / (MIC_SAMPLE_RATE * 2);
        ...
        publish();
    }
    i2s_channel_disable(rx); i2s_del_channel(rx);
    wav_finalize(f, data_bytes);
    fclose(f);
    ...
}
```

