WAV 头写入函数：
```c
static void put_u32le(uint8_t *p, uint32_t v) { p[0]=v; p[1]=v>>8; p[2]=v>>16; p[3]=v>>24; }
static void put_u16le(uint8_t *p, uint16_t v) { p[0]=v; p[1]=v>>8; }

static bool wav_write_header(FILE *f, uint32_t rate)
{
    uint8_t h[44] = {0};
    memcpy(h + 0, "RIFF", 4);
    put_u32le(h + 4, 36);          /* 占位，录完回填 36 + data */
    memcpy(h + 8, "WAVE", 4);
    memcpy(h + 12, "fmt ", 4);
    put_u32le(h + 16, 16);
    put_u16le(h + 20, 1);          /* PCM */
    put_u16le(h + 22, 1);          /* mono */
    put_u32le(h + 24, rate);
    put_u32le(h + 28, rate * 2);   /* byte rate: 16bit mono */
    put_u16le(h + 32, 2);          /* block align */
    put_u16le(h + 34, 16);         /* bits */
    memcpy(h + 36, "data", 4);
    put_u32le(h + 40, 0);          /* 占位 */
    return fwrite(h, 1, sizeof(h), f) == sizeof(h);
}
```

回填：
```c
static void wav_finalize(FILE *f, uint32_t data_bytes)
{
    uint8_t v[4];
    put_u32le(v, 36 + data_bytes);
    fseek(f, 4, SEEK_SET); fwrite(v, 1, 4, f);
    put_u32le(v, data_bytes);
    fseek(f, 40, SEEK_SET); fwrite(v, 1, 4, f);
    fflush(f);
}
```

I2S 初始化：
```c
static esp_err_t mic_i2s_start(i2s_chan_handle_t *out)
{
    i2s_chan_config_t ch = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_1, I2S_ROLE_MASTER);
    ch.dma_desc_num = 4;
    ch.dma_frame_num = 240;
    i2s_chan_handle_t rx = NULL;
    esp_err_t err = i2s_new_channel(&ch, NULL, &rx);
    if (err != ESP_OK) return err;
    i2s_std_config_t std = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(MIC_SAMPLE_RATE),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = MIC_I2S_BCLK_GPIO,
            .ws   = MIC_I2S_WS_GPIO,
            .dout = I2S_GPIO_UNUSED,
            .din  = MIC_I2S_DIN_GPIO,
            .invert_flags = { .mclk_inv=false, .bclk_inv=false, .ws_inv=false },
        },
    };
    err = i2s_channel_init_std_mode(rx, &std);
    if (err != ESP_OK) { i2s_del_channel(rx); return err; }
    err = i2s_channel_enable(rx);
    if (err != ESP_OK) { i2s_del_channel(rx); return err; }
    *out = rx;
    return ESP_OK;
}
```

注意：I2S1 上只有 RX，没有 TX。`i2s_new_channel(&ch, NULL, &rx)` 正确。

数据转换：32bit stereo 交错，每帧 8 字节。取左/右 slot 的 int32，`>> 16` 得 int16。

```c
static size_t mic_convert(const int32_t *raw, size_t frames, int16_t *pcm, uint8_t *peak)
{
    int32_t mx = 0;
    for (size_t i = 0; i < frames; i++) {
        int32_t v = raw[2 * i + (MIC_USE_LEFT_CHANNEL ? 0 : 1)] >> 16;
        if (v > 32767) v = 32767;
        if (v < -32768) v = -32768;
        pcm[i] = (int16_t)v;
        int32_t a = v < 0 ? -v : v;
        if (a > mx) mx = a;
    }
    *peak = (uint8_t)((uint32_t)mx * 100 / 32768);
    return frames * sizeof(int16_t);
}
```

注意 `raw` 需要按 4 字节对齐，PSRAM malloc 是对齐的；但 i2s_channel_read 按字节读，我用 `int32_t*` 强转需要保证 buf 对齐 —— heap_caps_malloc 返回 4/8 对齐，OK。

