主要录音流程：
```c
static void do_record(void)
{
    char path[64];
    if (!sd_card_is_mounted()) { hint("SD 卡未挂载"); return; }
    if (!make_rec_path(path, sizeof(path))) { hint("录音文件过多"); return; }

    FILE *f = fopen(path, "wb");
    if (!f) { hint("无法创建文件"); return; }

    uint8_t hdr[44];
    wav_header(hdr, MIC_SAMPLE_RATE, 0);
    if (fwrite(hdr, 1, sizeof(hdr), f) != sizeof(hdr)) { ... }

    i2s_chan_handle_t rx = NULL;
    esp_err_t err = mic_i2s_open(&rx);
    if (err != ESP_OK) { fclose(f); remove(path); hint("麦克风初始化失败"); return; }

    g_mic.recording = true;
    g_mic.elapsed_ms = 0; ... hint(NULL); publish();

    uint32_t data_bytes = 0;
    bool ok = true;
    while (true) {
        mic_cmd_t c;
        if (xQueueReceive(s_q, &c, 0) == pdTRUE && c == CMD_STOP) break;
        if (data_bytes >= MIC_MAX_BYTES) break;

        size_t got = 0;
        err = i2s_channel_read(rx, s_raw, sizeof(s_raw), &got, 100);
        if (err != ESP_OK && got == 0) { vTaskDelay(pdMS_TO_TICKS(5)); continue; }

        size_t frames = got / 8;
        // 转换
        int32_t peak = 0;
        for (i...) {
            int32_t v = ...;
            int16_t s = (int16_t)(v >> 16);
            s_pcm[i] = s;
            ...
        }
        size_t pcm_bytes = frames * 2;
        if (fwrite(s_pcm, 1, pcm_bytes, f) != pcm_bytes) { ok=false; hint("SD 写入失败"); break; }
        data_bytes += pcm_bytes;
        g_mic.elapsed_ms = data_bytes * 1000 / (MIC_SAMPLE_RATE * 2);
        g_mic.bytes_written = data_bytes;
        g_mic.level = ...;
        publish();
    }

    i2s_channel_disable(rx);
    i2s_del_channel(rx);
    rx = NULL;

    if (ok) {
        // 回填头
        wav_header(hdr, MIC_SAMPLE_RATE, data_bytes);
        fseek(f, 0, SEEK_SET);
        fwrite(hdr, 1, sizeof(hdr), f);
    }
    fflush(f);
    fclose(f);

    if (!ok || data_bytes == 0) {
        remove(path);
        hint(...)
    } else {
        snprintf(g_mic.last_file, ...);
        hint("已保存 REC_xxxx.wav"); // 让 UI 显示
    }
    g_mic.recording = false;
    publish();
}
```

