WAV 头结构（避免 packed struct 麻烦，直接按字节写）：
```c
static void wav_header(uint8_t h[44], uint32_t rate, uint32_t data_bytes)
{
    memcpy(h + 0, "RIFF", 4);
    put32(h + 4, 36 + data_bytes);
    memcpy(h + 8, "WAVE", 4);
    memcpy(h + 12, "fmt ", 4);
    put32(h + 16, 16);          // fmt chunk size
    put16(h + 20, 1);           // PCM
    put16(h + 22, 1);           // mono
    put32(h + 24, rate);
    put32(h + 28, rate * 2);    // byte rate (16bit mono)
    put16(h + 32, 2);           // block align
    put16(h + 34, 16);          // bits
    memcpy(h + 36, "data", 4);
    put32(h + 40, data_bytes);
}
```

