I2S 初始化：
```c
static esp_err_t mic_i2s_init(void)
{
    if (s_rx) return ESP_OK;
    i2s_chan_config_t ch = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_1, I2S_ROLE_MASTER);
    ch.dma_desc_num = 4;
    ch.dma_frame_num = 240;
    esp_err_t err = i2s_new_channel(&ch, NULL, &s_rx);
    if (err != ESP_OK) { s_rx = NULL; return err; }

    i2s_std_config_t std = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(MIC_SAMPLE_RATE),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = MIC_I2S_BCLK_GPIO,
            .ws   = MIC_I2S_WS_GPIO,
            .dout = I2S_GPIO_UNUSED,
            .din  = MIC_I2S_DIN_GPIO,
            .invert_flags = { .mclk_inv = false, .bclk_inv = false, .ws_inv = false },
        },
    };
#if MIC_SLOT_RIGHT
    /* 只采样右声道：模块 L/R 接 VDD 时数据在 WS 高的那个 slot */
    std.slot_cfg.slot_mask = I2S_STD_SLOT_RIGHT;
#endif
    err = i2s_channel_init_std_mode(s_rx, &std);
    ...
}
```

嗯，slot_mask = RIGHT 但 slot_mode = STEREO 时会怎样？驱动可能仍读两个 slot。为了简单，我不改 slot_mask，而是在转换时选择索引。stereo 读两个 slot，取 index 0 或 1（由 MIC_SLOT_RIGHT 决定）。这样最稳。

不过 INMP441 在 mono 模式下通常只在某一个 half-frame 输出数据，另一个 half-frame 是三态（可能为 0 或浮动）。stereo 读两个 slot 没问题，取需要的那个。

`bit_shift = true` 是 Philips 默认。INMP441 数据从 WS 变化后第 2 个 BCLK 开始（1-bit delay），符合 Philips。好。

注意 I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG 在 SOC_I2S_HW_VERSION_2（ESP32-S3）的定义是第 140 行那个（有 left_align/big_endian/bit_order_lsb），slot_mask = I2S_STD_SLOT_BOTH。好。

转换：
```c
static size_t mic_convert(size_t frames, uint8_t *peak_out)
{
    int32_t peak = 0;
    for (size_t i = 0; i < frames; i++) {
        int32_t v = s_raw[2 * i + MIC_SLOT_RIGHT];  /* 32bit 样本，24bit 左对齐 */
        int16_t s = (int16_t)(v >> 16);             /* 取高 16 位 */
        s_pcm[i] = s;
        int32_t a = s < 0 ? -(int32_t)s : (int32_t)s;
        if (a > peak) peak = a;
    }
    *peak_out = (uint8_t)((uint64_t)peak * 100 / 32768);
    return frames * sizeof(int16_t);
}
```

WAV 头：
```c
static void put_u32le(uint8_t *p, uint32_t v) { ... }
static void put_u16le(uint8_t *p, uint16_t v) { ... }

static bool wav_write_header(FILE *f, uint32_t data_bytes)
{
    uint8_t h[44] = {0};
    memcpy(h + 0, "RIFF", 4);
    put_u32le(h + 4, 36 + data_bytes);
    memcpy(h + 8, "WAVE", 4);
    memcpy(h + 12, "fmt ", 4);
    put_u32le(h + 16, 16);
    put_u16le(h + 20, 1);       /* PCM */
    put_u16le(h + 22, MIC_CHANNELS);
    put_u32le(h + 24, MIC_SAMPLE_RATE);
    put_u32le(h + 28, MIC_SAMPLE_RATE * MIC_CHANNELS * MIC_BITS / 8);
    put_u16le(h + 32, MIC_CHANNELS * MIC_BITS / 8);
    put_u16le(h + 34, MIC_BITS);
    memcpy(h + 36, "data", 4);
    put_u32le(h + 40, data_bytes);
    return fwrite(h, 1, sizeof(h), f) == sizeof(h);
}
```
