主循环（在任务里）：
```c
static void mic_record_session(void)
{
    char path[128];
    if (!sd_card_is_mounted()) { set_hint("SD 卡未挂载"); publish(); return; }
    if (!mic_make_path(path, sizeof(path))) { set_hint("录音文件过多"); publish(); return; }

    FILE *f = fopen(path, "wb");
    if (!f) { set_hint("无法创建录音文件"); publish(); return; }
    if (!wav_write_header(f, 0)) { ... fclose; remove; }

    esp_err_t err = mic_i2s_init();
    if (err != ESP_OK) { ... }
    err = i2s_channel_enable(s_rx);
    ...
    g_mic.recording = true; ...
    uint32_t data_bytes = 0;
    bool ok = true;
    while (true) {
        mic_cmd_t c;
        if (xQueueReceive(s_q, &c, 0) == pdTRUE && c == MIC_CMD_STOP) break;
        if (data_bytes >= limit) break;
        size_t got = 0;
        esp_err_t e = i2s_channel_read(s_rx, s_raw, MIC_READ_FRAMES * 2 * sizeof(int32_t), &got, 200);
        if (e != ESP_OK && got == 0) {
            // 超时无数据，继续等命令
            continue;
        }
        size_t frames = got / (2 * sizeof(int32_t));
        uint8_t pk;
        size_t pcm_bytes = mic_convert(frames, &pk);
        if (fwrite(s_pcm, 1, pcm_bytes, f) != pcm_bytes) { ok = false; set_hint("SD 写入失败"); break; }
        data_bytes += pcm_bytes;
        g_mic.elapsed_ms = data_bytes * 1000 / (MIC_SAMPLE_RATE * 2);
        g_mic.bytes_written = data_bytes;
        g_mic.peak = pk;
        publish();
    }
    i2s_channel_disable(s_rx);
    // 回填
    if (ok) { fseek(f,0,SEEK_SET); wav_write_header(f, data_bytes); }
    fflush(f); fclose(f);
    if (!ok || data_bytes == 0) { remove(path); ... }
    else { strncpy(last_path ...); set_hint("已保存 ..."); }
    g_mic.recording = false; g_mic.done = true; publish();
}
```

注意 i2s_channel_read 的 timeout 单位是毫秒（内部 pdMS_TO_TICKS）。传 200 → 200ms。但如果 FREERTOS_HZ=100，pdMS_TO_TICKS(200)=20 ticks，OK。

还要处理 i2s_channel_read 返回 ESP_ERR_TIMEOUT 但 got>0 的情况（部分数据）。

停止时队列里可能残留 START 命令，任务外层循环会再开一个新 session。需要注意：任务循环用 xQueueReceive(portMAX_DELAY) 等命令，收到 START 才进入 session。停止后回到等待。如果用户快速连点，队列里可能有 START/STOP 交替。可以在进入 session 前先清空队列？不，简单处理即可。

任务：
```c
static void mic_task(void *arg)
{
    for (;;) {
        mic_cmd_t c;
        if (xQueueReceive(s_q, &c, portMAX_DELAY) != pdTRUE) continue;
        if (c == MIC_CMD_START && !g_mic.recording) mic_record_session();
    }
}
```
START/STOP 都进队列；STOP 在 session 内被消费，外层收到 STOP 就忽略。

