转换：
```c
static size_t mic_convert(size_t frames, uint8_t *peak_out)
{
    int32_t peak = 0;
    for (size_t i = 0; i < frames; i++) {
        int32_t v = s_raw[2 * i + MIC_SLOT_RIGHT];  /* 32bit 样本，24bit 左对齐 */
        int16_t s = (int16_t)(v >> 16);             /* 取高 16 位 */
        s_pcm[i] = s;
        int32_t a = s < 0 ? -(int32_t)s : (int32_t)s;
        if (a > peak) peak = a;
    }
    *peak_out = (uint8_t)((uint64_t)peak * 100 / 32768);
    return frames * sizeof(int16_t);
}
```

