static void put_u32le(uint8_t *p, uint32_t v) { ... }
static void put_u16le(uint8_t *p, uint16_t v) { ... }

static bool wav_write_header(FILE *f, uint32_t data_bytes)
{
    uint8_t h[44] = {0};
    memcpy(h + 0, "RIFF", 4);
    put_u32le(h + 4, 36 + data_bytes);
    memcpy(h + 8, "WAVE", 4);
    memcpy(h + 12, "fmt ", 4);
    put_u32le(h + 16, 16);
    put_u16le(h + 20, 1);       /* PCM */
    put_u16le(h + 22, MIC_CHANNELS);
    put_u32le(h + 24, MIC_SAMPLE_RATE);
    put_u32le(h + 28, MIC_SAMPLE_RATE * MIC_CHANNELS * MIC_BITS / 8);
    put_u16le(h + 32, MIC_CHANNELS * MIC_BITS / 8);
    put_u16le(h + 34, MIC_BITS);
    memcpy(h + 36, "data", 4);
    put_u32le(h + 40, data_bytes);
    return fwrite(h, 1, sizeof(h), f) == sizeof(h);
}
