```c
static void music_timer_cb(lv_timer_t *t)
{
    (void)t;
    uint32_t now = lv_tick_get();
    bool mic_changed = (g_mic.version != s_mic_shown_ver);
    bool aud_changed = (g_audio.version != s_music_shown_ver);
    bool mic_msg_on  = (s_mic_msg_until != 0 && (int32_t)(now - s_mic_msg_until) < 0);
    bool mic_msg_exp = (s_mic_msg_until != 0 && (int32_t)(now - s_mic_msg_until) >= 0);

    if (!aud_changed && !mic_changed && !mic_msg_exp) return;

    if (mic_changed) {
        s_mic_shown_ver = g_mic.version;
        if (g_mic_btn_lbl)
            lv_label_set_text(g_mic_btn_lbl, g_mic.recording ? "停止" : "录音");
        if (g_mic.recording) {
            s_mic_msg_until = 0;
        } else {
            char h[40]; mic_copy_hint(h, sizeof(h));
            if (h[0]) s_mic_msg_until = now + 3000;
            if (g_mic.done) { mic_rec_ack_done(); music_scan(); }
        }
    }
    if (mic_msg_exp) s_mic_msg_until = 0;

    if (aud_changed) s_music_shown_ver = g_audio.version;

    /* 录音进行中或刚结束的提示期，曲名栏让给录音状态 */
    bool mic_active = g_mic.recording || mic_msg_on;
    if (mic_active) {
        char b[48];
        if (g_mic.recording) {
            unsigned sec = g_mic.elapsed_ms / 1000;
            snprintf(b, sizeof(b), "录音中 %u:%02u  电平 %u%%", sec/60, sec%60, (unsigned)g_mic.peak);
        } else {
            mic_copy_hint(b, sizeof(b));
            if (!b[0]) strncpy(b, "录音已结束", sizeof(b));
        }
        if (g_music_title) lv_label_set_text(g_music_title, b);
        // 录音时进度条当电平表用
        if (g_music_slider) lv_slider_set_value(g_music_slider, (int)g_mic.peak * 10, LV_ANIM_OFF);
    } else {
        music_update_title();
        ... 原有进度等
    }
    music_update_time();  // 嗯，这个会写时间标签，录音时可能不合适但无妨
    ...
}
```

