static void music_timer_cb(lv_timer_t *t)
{
    (void)t;
    bool mic_changed = (g_mic.version != s_mic_shown_ver);
    bool aud_changed = (g_audio.version != s_music_shown_ver);

    if (mic_changed) {
        s_mic_shown_ver = g_mic.version;
        /* 录完时重扫一次播放列表，让新 WAV 出现在列表里；
         * music_scan() 会把 g_music_cur 置 -1，先记住当前曲目再找回 */
        if (g_mic.done) {
            char cur[sizeof(g_music_files[0])] = "";
            if (g_music_cur >= 0)
                snprintf(cur, sizeof(cur), "%s", music_base(g_music_files[g_music_cur]));
            music_scan();
            ... 找回 ...
            mic_rec_ack_done();
            s_mic_msg_until = lv_tick_get() + 3000;
        }
        /* 按钮外观 */
        if (g_mic_btn_lbl)
            lv_label_set_text(g_mic_btn_lbl, g_mic.recording ? "停止" : "录音");
        if (g_mic_btn)
            lv_obj_set_style_bg_color(g_mic_btn,
                lv_color_hex(g_mic.recording ? 0xC0392B : 0x8E4B2B), 0);
    }

    /* 播放进度/标题：录音期间不覆盖曲名栏 */
    if (aud_changed) {
        s_music_shown_ver = g_audio.version;
        if (!g_mic.recording) music_update_title();
        music_update_time();
        ... slider ...
        ... play lbl ...
        if (g_audio.eof) ...
    }

    /* 录音状态优先级最高 */
    if (g_mic.recording) {
        char b[40];
        unsigned sec = g_mic.elapsed_ms / 1000;
        snprintf(b, sizeof(b), "录音中 %u:%02u  峰值%u%%",
                 (unsigned)(sec / 60), (unsigned)(sec % 60), (unsigned)g_mic.peak);
        lv_label_set_text(g_music_title, b);
        /* 进度条借用为电平表 */
        lv_slider_set_value(g_music_slider, (int)g_mic.peak * 10, LV_ANIM_OFF);
        return;
    }
    if (s_mic_msg_until && (int32_t)(lv_tick_get() - s_mic_msg_until) < 0) {
        char h[40]; mic_copy_hint(h, sizeof(h));
        if (h[0]) lv_label_set_text(g_music_title, h);
        return;
    }
    if (s_mic_msg_until) {   /* 提示到期，恢复曲名一次 */
        s_mic_msg_until = 0;
        music_update_title();
    }
}
