   309:static void mic_task(void *arg)
   310:{
   311:    (void)arg;
   312:    for (;;) {
   313:        mic_cmd_t cmd;
   314:        if (xQueueReceive(s_q, &cmd, portMAX_DELAY) != pdTRUE) continue;
   315:        if (cmd == MIC_CMD_START && !g_mic.recording) {
   316:            record_session();
   317:        }
