   322:/* ---------------- 对外 API ---------------- */
   323:void mic_rec_init(void)
   324:{
   325:#if MIC_HW_PRESENT
   326:    const uint32_t caps = MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT;
   327:    s_raw = (int32_t *)heap_caps_malloc(MIC_READ_FRAMES * 2 * sizeof(int32_t), caps);
   328:    s_pcm = (int16_t *)heap_caps_malloc(MIC_READ_FRAMES * sizeof(int16_t), caps);
   329:    if (!s_raw || !s_pcm) {
   330:        ESP_LOGE(TAG, "PSRAM buffers alloc failed, recorder disabled");
   331:        set_hint("录音内存不足"); publish();
   332:        return;
   333:    }
   334:    s_q = xQueueCreate(4, sizeof(mic_cmd_t));
