   161:static esp_err_t http_get(const char *url, char *buf, size_t cap)
   162:{
   163:    esp_http_client_config_t cfg = {
   164:        .url = url,
   165:        .crt_bundle_attach = esp_crt_bundle_attach, /* 用 ESP 内置 CA 包校验 Let's Encrypt 等证书 */
   166:        .user_agent = "esp32-weather/1.0",          /* 部分 CDN/服务器会拦截无 UA 的请求 */
   167:        .timeout_ms = 15000,
   168:    };
   169:    esp_http_client_handle_t c = esp_http_client_init(&cfg);
   170:    if (!c) {
   171:        return ESP_FAIL;
   172:    }
   173:    /* 强制服务器返回未压缩内容；即便返回 gzip，开启 CONFIG_ESP_HTTP_CLIENT_ENABLE_GZIP
   174:     * 后 esp_http_client 也会自动解压，避免拿到二进制导致 JSON 解析失败。 */
   175:    esp_http_client_set_header(c, "Accept-Encoding", "identity");
   176:
   177:    esp_err_t err = ESP_FAIL;
   178:    esp_err_t open_err = esp_http_client_open(c, 0);     /* 0 = GET，无请求体 */
   179:    if (open_err == ESP_OK) {
   180:        int content_length = esp_http_client_fetch_headers(c);
   181:        int status = esp_http_client_get_status_code(c);
   182:        if (status == 200) {
   183:            int total = 0, r;
   184:            while (total < (int)cap - 1 &&
   185:                   (r = esp_http_client_read(c, buf + total, cap - 1 - total)) > 0) {
   186:                total += r;
   187:            }
   188:            buf[total] = '\0';
   189:            err = ESP_OK;
   190:        } else {
   191:            ESP_LOGE(TAG, "HTTP status %d for %s", status, url);
   192:            buf[0] = '\0';
   193:            err = ESP_FAIL;
   194:        }
   195:        (void)content_length;
   196:        esp_http_client_close(c);       /* 显式关闭，避免半开连接残留占 socket */
   197:    } else {
   198:        /* 打印错误码：ESP_ERR_HTTP_CONNECT / ESP_ERR_TIMEOUT 等能直接区分
