   330:    s_raw = (int32_t *)heap_caps_malloc(MIC_READ_FRAMES * 2 * sizeof(int32_t), caps);
   331:    s_pcm = (int16_t *)heap_caps_malloc(MIC_READ_FRAMES * sizeof(int16_t), caps);
   332:    if (!s_raw || !s_pcm) {
