   341:    BaseType_t ok = xTaskCreateWithCaps(mic_task, "mic_rec", 12288, NULL, 4, NULL,
   342:                                        MALLOC_CAP_SPIRAM);
   343:    if (ok != pdPASS) {
   344:        ok = xTaskCreate(mic_task, "mic_rec", 12288, NULL, 4, &s_task);
   345:    }
   346:    if (ok != pdPASS) {
   347:        ESP_LOGE(TAG, "recorder task create failed");
   348:        return;
   349:    }
   350:    ESP_LOGI(TAG, "init ok (%uHz 16bit mono -> %s), WS=%d BCLK=%d DIN=%d",
   351:             (unsigned)MIC_SAMPLE_RATE, SD_MOUNT_POINT,
   352:             (int)MIC_I2S_WS_GPIO, (int)MIC_I2S_BCLK_GPIO, (int)MIC_I2S_DIN_GPIO);
   353:#else
   354:    /* 第一版 PCB：IO1/IO2 是 SD D2/D3、IO42 是 SD CMD，不能接麦克风 */
   355:    set_hint("本板未引出麦克风"); publish();
   356:    ESP_LOGW(TAG, "BOARD_REV 1 has no mic pins wired, recorder disabled");
   357:#endif","totalLineCount":396,"hasMore":true,"hint":""}}}}}

