    16:/* ui.c 创建的 LVGL 主任务句柄, DMA 完成时通过 xTaskNotifyGive 唤醒它,
    17: * 替代 vTaskDelay 固定 10ms 等待, 滑动 FPS 46→80+。 */
    18:extern TaskHandle_t g_lvgl_task;
    19:
    20:/* 额外给 LVGL 挂的 PSRAM 内存池总大小（KB）。
    21: * 内置的 LV_MEM（sdkconfig: CONFIG_LV_MEM_SIZE_KILOBYTES，当前 16KB）装不下所有
    22: * App 屏幕的常驻对象——实测开 3~4 个 App 就用到 99%，maxfree 只剩 608 字节，
    23: * 之后 lv_malloc 失败会触发断言死循环，进而 task_wdt 复位。
    24: *
    25: * ★ 关键：TLSF 不能跨池合并，所以「LVGL 单次最大可分配块」= 单个池的大小。
    26: *   全用 64KB 小池堆到 512KB，maxfree 就永远只有 64KB —— 看图时 PNG 解码要
    27: *   320*240*4 = 307KB 连续块，必然失败，屏幕上就是一片黑（已实测踩坑）。
    28: *   所以第一块必须挂一整块大的，剩下的再用小块补足总量。
    29: *
    30: * 单池上限（见 lv_tlsf.c）：
    31: *     #define TLSF_MAX_POOL_SIZE (LV_MEM_SIZE + LV_MEM_POOL_EXPAND_SIZE)
    32: *     block_size_max = 1 << log2_ceil(TLSF_MAX_POOL_SIZE)
    33: * 现在 LV_MEM_SIZE=16KB、LV_MEM_POOL_EXPAND_SIZE=512KB → 上限 1MB，
    34: * 挂 512KB 单池没问题（EXPAND 只抬高上限，本身不占内存）。 */
    35:/* 池子总量 = k_pool_chunks[] 之和 = 1024KB（PSRAM 空闲约 1.0MB，够用）
    36: *
    37: * 看图解码一次 PNG，LVGL 池里同时活着四块（都是 lodepng 的 lv_malloc）：
    38: *   文件缓冲    = 整个文件大小（lodepng_load_file 整读）        320x240 那张 = 162KB
    39: *   idat        = 压缩数据（≈ 文件大小）                                    ≈ 162KB
    40: *   解压扫描线  = w*h*4 + h                                                   307KB
    41: *   zlib window = 32KB
    42: * 合计 ≈ 663KB，再加上 App 常驻对象，池子得给到 1MB 左右才转得开。
    43: * 注意：解出来的那一帧（w*h*4）已经改走系统 PSRAM，不占这里的池。
    44: *
    45: * 384KB 那个池是给「文件/idat」这种中等块用的：TLSF 是最佳适配，
    46: * 有它接着，512KB 的大池就不会被切碎，扫描线那 307KB 才有地方落脚。 */
    47:static const size_t k_pool_chunks[] = {
    48:    512 * 1024,     /* 看图：扫描线（w*h*4）要连续空间，320x240 就是 307KB */
    49:    384 * 1024,     /* 解码时同时活着的文件缓冲 + idat */
    50:    64 * 1024,
    51:    64 * 1024,
    52:};
    53:
    54:/* PARTIAL 渲染模式: 两个内部 RAM draw buf, 每个 320×40×2=25KB。
    55: * 内部 SRAM 访问速度比 PSRAM 快 5-10 倍, LVGL 渲染加速;
    56: * 两个 buf 让 LVGL 渲染下一块时上一块同时 DMA 发送, 双缓冲流水线。
    57: * 内部 RAM 空闲 240KB, 50KB 占用绰绰有余。 */
    58:#define DISP_BUF_H    40
    59:#define DISP_BUF_SIZE (LCD_W * DISP_BUF_H * sizeof(lv_color_t))
    60:
