    46: * 有它接着，512KB 的大池就不会被切碎，扫描线那 307KB 才有地方落脚。 */
    47:static const size_t k_pool_chunks[] = {
    48:    512 * 1024,     /* 看图：扫描线（w*h*4）要连续空间，320x240 就是 307KB */
    49:    384 * 1024,     /* 解码时同时活着的文件缓冲 + idat */
