def load_font(path, name):
    lines = open(path, encoding='utf-8', errors='replace').read().splitlines()
    # opts line
    opts = next((l for l in lines[:8] if 'Opts:' in l), '')
    # glyph_dsc
    s = next((i for i, l in enumerate(lines) if 'glyph_dsc[] = {' in l), None)
    dsc = []
    if s is not None:
        for l in lines[s+1:]:
            if '};' in l:
                break
            dsc.append(l)
    # cmap ranges
    cmap = [(int(a), int(b), int(c)) for a, b, c in
            re.findall(r'range_start = (\d+), range_length = (\d+), glyph_id_start = (\d+)', '\n'.join(lines))]
    print('=== %s ===' % name)
    print(opts.strip()[:180])
    print('glyph count:', len(dsc), ' rcmap segs:', len(cmap))
    return lines, dsc, cmap

def gid_of(cmap, cp):
    for start, length, base in cmap:
        if start <= cp < start + length:
            return base + (cp - start)
    return None

