  1620:
  1621:/* 创建密码面板：SSID 提示 + 密码框 + OK/Cancel + 屏幕键盘。
  1622: * 最后创建，所以会盖在详情页之上。 */
  1623:static void build_pwd_panel(lv_obj_t *parent)
  1624:{
  1625:    g_pwd_panel = lv_obj_create(parent);
  1626:    lv_obj_set_size(g_pwd_panel, LCD_W, LCD_H);
  1627:    lv_obj_align(g_pwd_panel, LV_ALIGN_TOP_LEFT, 0, 0);
  1628:    lv_obj_set_style_bg_color(g_pwd_panel, lv_color_hex(0x101018), 0);
  1629:    lv_obj_set_style_bg_opa(g_pwd_panel, LV_OPA_COVER, 0);
  1630:    lv_obj_set_style_radius(g_pwd_panel, 0, 0);
  1631:    lv_obj_set_style_border_opa(g_pwd_panel, LV_OPA_TRANSP, 0);
  1632:    lv_obj_clear_flag(g_pwd_panel, LV_OBJ_FLAG_SCROLLABLE);
  1633:    lv_obj_set_scrollbar_mode(g_pwd_panel, LV_SCROLLBAR_MODE_OFF);
  1634:
  1635:    g_pwd_ssid = lv_label_create(g_pwd_panel);
  1636:    lv_label_set_text(g_pwd_ssid, "");
  1637:    lv_obj_set_style_text_font(g_pwd_ssid, &lv_font_cn_16, 0);
  1638:    lv_obj_set_style_text_color(g_pwd_ssid, lv_color_hex(0x9AA0B5), 0);
  1639:    lv_obj_set_width(g_pwd_ssid, LCD_W - 32);
  1640:    lv_label_set_long_mode(g_pwd_ssid, LV_LABEL_LONG_DOT);
  1641:    lv_obj_set_pos(g_pwd_ssid, 16, 6);
  1642:
  1643:    g_pwd_ta = lv_textarea_create(g_pwd_panel);
  1644:    lv_obj_set_size(g_pwd_ta, 288, 34);
  1645:    lv_obj_set_pos(g_pwd_ta, 16, 26);
  1646:    lv_textarea_set_one_line(g_pwd_ta, true);
  1647:    lv_textarea_set_password_mode(g_pwd_ta, true);
  1648:    lv_textarea_set_placeholder_text(g_pwd_ta, "密码");
  1649:    lv_obj_set_style_text_font(g_pwd_ta, &lv_font_montserrat_20, 0);
  1650:
  1651:    lv_obj_t *ok = lv_button_create(g_pwd_panel);
  1652:    lv_obj_set_size(ok, 92, 32);
  1653:    lv_obj_set_pos(ok, 16, 66);
  1654:    lv_obj_set_style_bg_color(ok, lv_color_hex(0x2E7DE0), 0);
  1655:    lv_obj_t *okl = lv_label_create(ok);
  1656:    lv_label_set_text(okl, "加入");
  1657:    lv_obj_set_style_text_font(okl, &lv_font_cn_16, 0);
  1658:    lv_obj_center(okl);
  1659:    lv_obj_add_event_cb(ok, pwd_ok_cb, LV_EVENT_CLICKED, NULL);
  1660:
  1661:    lv_obj_t *ca = lv_button_create(g_pwd_panel);
  1662:    lv_obj_set_size(ca, 92, 32);
  1663:    lv_obj_set_pos(ca, 120, 66);
  1664:    lv_obj_t *cal = lv_label_create(ca);
  1665:    lv_label_set_text(cal, "取消");
  1666:    lv_obj_set_style_text_font(cal, &lv_font_cn_16, 0);
  1667:    lv_obj_center(cal);
  1668:    lv_obj_add_event_cb(ca, pwd_cancel_cb, LV_EVENT_CLICKED, NULL);
  1669:
  1670:    g_pwd_kb = lv_keyboard_create(g_pwd_panel);
  1671:    lv_obj_set_size(g_pwd_kb, LCD_W, 140);
  1672:    lv_obj_align(g_pwd_kb, LV_ALIGN_BOTTOM_MID, 0, 0);
  1673:    lv_keyboard_set_textarea(g_pwd_kb, g_pwd_ta);
  1674:
  1675:    /* 键盘自带的“OK”键触发 textarea 的 LV_EVENT_READY、“关闭”键触发
  1676:     * LV_EVENT_CANCEL，并不会走 Join/Cancel 按钮的 LV_EVENT_CLICKED，
  1677:     * 这里补上，让点键盘的确定键也能提交密码/取消。 */
  1678:    lv_obj_add_event_cb(g_pwd_ta, pwd_ok_cb, LV_EVENT_READY, NULL);
  1679:    lv_obj_add_event_cb(g_pwd_ta, pwd_cancel_cb, LV_EVENT_CANCEL, NULL);
