{"role":"assistant","content":[{"type":"text","text":"用 `esp_http_client_perform()` + `set_post_field` 最简单。现在写完整实现："},{"type":"tool-call","toolCallId":"chatcmpl-tool-9e28a5bdfeb6f68f","toolName":"write_to_file","args":{"filePath":"c:/esp32/LCD/main/ai_chat.c","content":"#include "ai_chat.h"
#include "esp_log.h"
#include "esp_err.h"
#include "esp_heap_caps.h"
#include "esp_http_client.h"
#include "esp_crt_bundle.h"
#include "nvs_flash.h"
#include "nvs.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/semaphore.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

/* DeepSeek OpenAI 兼容端点：国内 IP（120.232.x），实测 443 可直连。
 * 默认模型 deepseek-chat；价格低、中文好。Key 存 NVS，不硬编码在固件里。 */
#define AI_URL        "https://api.deepseek.com/chat/completions"
#define AI_MODEL      "deepseek-chat"
#define AI_TIMEOUT_MS 20000

#define NVS_NS    "aichat"
#define NVS_KEY   "apikey"

static const char *TAG = "AI";

volatile ai_chat_state_t g_ai;

static SemaphoreHandle_t s_sem = NULL;
/* 用户问题在 PSRAM 里排队，避免把 LVGL textarea 的指针留给后台任务 */
static char  s_question[1024];
static char *s_req_buf = NULL;   /* 请求 JSON，PSRAM */
static char *s_res_buf = NULL;   /* 响应 JSON，PSRAM */
#define REQ_CAP  (8 * 1024)
#define RES_CAP  (16 * 1024)

/* 最近一轮上下文（PSRAM 缓冲，跟随请求一起发），提升多轮连贯性 */
static char s_last_q[512];
static char s_last_a[1024];

/* ---------------- NVS Key ---------------- */
bool ai_chat_key_get(char *out, size_t cap)
{
    if (!out || cap == 0) return false;
    out[0] = '\0';
    nvs_handle_t h;
    if (nvs_open(NVS_NS, NVS_READONLY, &h) != ESP_OK) return false;
    size_t len = cap;
    esp_err_t e = nvs_get_str(h, NVS_KEY, out, &len);
    nvs_close(h);
    if (e != ESP_OK || out[0] == '\0') { out[0] = '\0'; return false; }
    return true;
}

bool ai_chat_key_set(const char *key)
{
    if (!key) return false;
    nvs_handle_t h;
    if (nvs_open(NVS_NS, NVS_READWRITE, &h) != ESP_OK) return false;
    esp_err_t e = nvs_set_str(h, NVS_KEY, key);
    if (e == ESP_OK) e = nvs_commit(h);
    nvs_close(h);
    return e == ESP_OK;
}

bool ai_chat_key_has(void)
{
    char k[8];
    return ai_chat_key_get(k, sizeof(k));
}

/* ---------------- JSON 辅助 ---------------- */
/* 把字符串按 JSON 规则转义后追加到 buf（处理引号、反斜杠、换行、制表符、
 * 以及 <0x20 的控制字符），返回是否成功。 */
static bool json_append_escaped(char *buf, size_t cap, size_t *len, const char *s)
{
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        char esc[8];
        int n = 0;
        switch (c) {
            case '"':  n = snprintf(esc, sizeof(esc), "\\\""); break;
            case '\\': n = snprintf(esc, sizeof(esc), "\\\\"); break;
            case '\n': n = snprintf(esc, sizeof(esc), "\\n");  break;
            case '\r': n = snprintf(esc, sizeof(esc), "\\r");  break;
            case '\t': n = snprintf(esc, sizeof(esc), "\\t");  break;
            default:
                if (c < 0x20) n = snprintf(esc, sizeof(esc), "\\u%04x", c);
                else { esc[0] = (char)c; esc[1] = '\0'; n = 1; }
                break;
        }
        if (*len + n + 1 >= cap) return false;
        memcpy(buf + *len, esc, n);
        *len += n;
    }
    return true;
}

/* 从 JSON 里找 "content": "..." 并做反转义，写入 out。
 * DeepSeek 响应结构里 content 是唯一含长文本的字符串字段，
 * 用简单扫描即可，不需要完整 JSON 解析器。 */
static bool parse_content(const char *json, char *out, size_t cap)
{
    const char *p = strstr(json, "\"content\"");
    if (!p) return false;
    p = strchr(p, ':');
    if (!p) return false;
    p++;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    if (*p != '"') return false;
    p++;

    size_t n = 0;
    while (*p && n + 1 < cap) {
        if (*p == '"') { n++; break; }
        if (*p == '\\') {
            p++;
            switch (*p) {
                case 'n': out[n++] = '\n'; break;
                case 'r': out[n++] = '\r'; break;
                case 't': out[n++] = '\t'; break;
                case '"': out[n++] = '"';  break;
                case '\\': out[n++] = '\\'; break;
                case '/': out[n++] = '/';  break;
                case 'u': {
                    /* \uXXXX：DeepSeek 中文通常直接 UTF-8 输出，这里只兜底
                     * BMP 内字符；代理对(emoji)不做处理，跳过。 */
                    if (p[1] && p[2] && p[3] && p[4]) {
                        unsigned cp = 0;
                        sscanf(p + 1, "%4x", &cp);
                        if (cp >= 0x20 && cp < 0x10000 && cp < 0xD800) {
                            if (cp < 0x80) out[n++] = (char)cp;
                            else if (cp < 0x800) {
                                out[n++] = (char)(0xC0 | (cp >> 6));
                                out[n++] = (char)(0x80 | (cp & 0x3F));
                            } else {
                                out[n++] = (char)(0xE0 | (cp >> 12));
                                out[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                                out[n++] = (char)(0x80 | (cp & 0x3F));
                            }
                        }
                        p += 4;
                    }
                    break;
                }
                default: out[n++] = *p; break;
            }
            p++;
        } else {
            out[n++] = *p++;
        }
    }
    out[n] = '\0';
    return n > 0;
}

/* ---------------- 后台任务 ---------------- */
static esp_err_t ai_http_post(const char *body, char *out, size_t out_cap)
{
    esp_http_client_config_t cfg = {
        .url = AI_URL,
        .method = HTTP_METHOD_POST,
        .crt_bundle_attach = esp_crt_bundle_attach,
        .timeout_ms = AI_TIMEOUT_MS,
        .user_agent = "esp32-ai-chat/1.0",
    };
    esp_http_client_handle_t c = esp_http_client_init(&cfg);
    if (!c) return ESP_FAIL;

    esp_http_client_set_header(c, "Content-Type", "application/json");
    esp_http_client_set_header(c, "Accept", "application/json");
    esp_http_client_set_header(c, "Accept-Encoding", "identity");

    char auth[160];
    char key[96];
    if (!ai_chat_key_get(key, sizeof(key))) {
        esp_http_client_cleanup(c);
        return ESP_ERR_INVALID_STATE;
    }
    snprintf(auth, sizeof(auth), "Bearer %s", key);
    esp_http_client_set_header(c, "Authorization", auth);

    esp_err_t err = ESP_FAIL;
    int len = (int)strlen(body);
    esp_err_t e = esp_http_client_set_post_field(c, body, len);
    if (e != ESP_OK) { ESP_LOGE(TAG, "set_post_field: %s", esp_err_to_name(e)); goto done; }
    e = esp_http_client_perform(c);
    if (e != ESP_OK) {
        ESP_LOGE(TAG, "perform: %s", esp_err_to_name(e));
        err = e;
        goto done;
    }
    int status = esp_http_client_get_status_code(c);
    if (status != 200) {
        ESP_LOGE(TAG, "HTTP status %d", status);
        /* 读一小段错误体帮助定位（额度不足/Key 错误） */
        int r = esp_http_client_read(c, out, out_cap - 1);
        if (r > 0) out[r] = '\0'; else out[0] = '\0';
        err = ESP_FAIL;
        goto done;
    }
    int total = 0, r;
    while (total < (int)out_cap - 1 &&
           (r = esp_http_client_read(c, out + total, out_cap - 1 - total)) > 0) {
        total += r;
    }
    out[total] = '\0';
