  2373:    lv_obj_t *cont = lv_obj_create(parent);
  2374:    lv_obj_set_size(cont, LCD_W - 24, LV_SIZE_CONTENT);  /* 高度按内容自适应，避免末行溢出压到按钮 */
  2375:    lv_obj_align(cont, LV_ALIGN_TOP_MID, 0, 62);
  2376:    lv_obj_set_style_bg_opa(cont, LV_OPA_TRANSP, 0);
  2377:    lv_obj_set_style_border_opa(cont, LV_OPA_TRANSP, 0);
  2378:    lv_obj_set_style_shadow_opa(cont, LV_OPA_TRANSP, 0);
