  2380:    lv_obj_set_style_pad_all(cont, 0, 0);
  2381:    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
  2382:    lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_COLUMN);
  2383:    lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  2384:    lv_obj_set_style_pad_row(cont, 4, 0);   /* 标签之间的竖直间距 */
  2385:
  2386:    g_wx_city = lv_label_create(cont);
  2387:    lv_obj_set_style_text_font(g_wx_city, &lv_font_montserrat_20, 0);
  2388:    lv_obj_set_style_text_color(g_wx_city, lv_color_white(), 0);
  2389:    lv_label_set_text(g_wx_city, "--");
  2390:
  2391:    g_wx_temp = lv_label_create(cont);
  2392:    lv_obj_set_style_text_font(g_wx_temp, &lv_font_cn_16, 0);
  2393:    lv_obj_set_style_text_color(g_wx_temp, lv_color_white(), 0);
  2394:    lv_label_set_text(g_wx_temp, "--.- C");
  2395:
  2396:    g_wx_desc = lv_label_create(cont);
