  2521:/* 点 Key 输入框才弹键盘，平时收起，不遮挡下方按钮 */
  2522:static void ai_key_ta_focus_cb(lv_event_t *e)
  2523:{
  2524:    (void)e;
  2525:    if (g_ai_key_kb) {
  2526:        lv_obj_clear_flag(g_ai_key_kb, LV_OBJ_FLAG_HIDDEN);
  2527:        lv_keyboard_set_textarea(g_ai_key_kb, g_ai_key_ta);
  2528:    }
  2529:}
  2530:
  2531:static void ai_key_save_cb(lv_event_t *e)
  2532:{
  2533:    (void)e;
  2534:    if (!g_ai_key_ta) return;
  2535:    const char *k = lv_textarea_get_text(g_ai_key_ta);
  2536:    if (k && k[0]) {
  2537:        ai_chat_key_set(k);
  2538:        ESP_LOGI("AI", "API key saved (%u chars)", (unsigned)strlen(k));
