  2551:static void ai_key_open_cb(lv_event_t *e)
  2552:{
  2553:    (void)e;
  2554:    if (!g_ai_key_panel) return;
  2555:    /* 从输入态直接点 Key 时先复位聊天屏布局（Key 浮层有自己的键盘） */
  2556:    if (g_ai_kb) {
  2557:        lv_keyboard_set_textarea(g_ai_kb, NULL);
  2558:        lv_obj_add_flag(g_ai_kb, LV_OBJ_FLAG_HIDDEN);
  2559:    }
  2560:    if (g_ai_ime) {
  2561:        lv_obj_t *cand = lv_ime_pinyin_get_cand_panel(g_ai_ime);
  2562:        if (cand) lv_obj_add_flag(cand, LV_OBJ_FLAG_HIDDEN);
