  2564:    if (g_ai_chat_box) lv_obj_clear_flag(g_ai_chat_box, LV_OBJ_FLAG_HIDDEN);
  2565:    if (g_ai_bar)      lv_obj_clear_flag(g_ai_bar, LV_OBJ_FLAG_HIDDEN);
  2566:    /* 打开即显示 Key 键盘并绑定输入框：浮层里的 textarea 不会自动触发
  2567:     * LV_EVENT_FOCUSED，光靠 focus 回调会导致「键盘根本出不来」。 */
