static void go_home_cb(lv_event_t *e)
{
    (void)e;
    ui_go_home();   /* 内部会停掉 pc_mon 拉取 + 做收缩动画 */
}

/* ---------------- App 切换动画 ----------------
 * 结论：本硬件上只能用「整块位移」，不能用「整屏改透明度」。
 *
 * 之前试过 LV_SCREEN_LOAD_ANIM_FADE_IN，实测进 App 时屏幕明显暗一档、结束时闪一下。
 * 原因不是 LVGL 的 bug，是 PARTIAL 刷新模式的固有性质（lvgl_port.c:238 注册的是
 * PARTIAL + 两个 40 行 draw buf）：
 *   1. draw buf 里**从来不是整帧图像**，只有最近渲染过的若干行的像素，40 行缓冲区
 *      被从头到尾循环复用，所以任意时刻 buf 里装的是各种历史残留像素。
 *   2. 屏幕 opa<100% 时（lv_display.c 的 opa_scale_anim → lv_obj_set_style_opa），
 *      LVGL 渲染新屏是往 draw buf 上做 **alpha 混合**，混合对象是 buf 里那些残留像素，
 *      而不是"旧屏画面"（旧屏此时已经被标脏清除、且没有被重绘，见 lv_refr.c:1069-1078
 *      虽然遍历了 prev_scr，但对象没 invalidate 就不会画）。
 *      → 画面混合出一堆历史的暗像素 = 看着发暗、局部发花。
 *   3. 动画一结束 scr_anim_completed 立刻 lv_obj_remove_local_style_prop(scr, OPA)
 *      （lv_display.c:1535）把 opa 恢复成 255，残留像素的那份混色瞬间消失
 *      → 亮度整屏跳变一下 = 那个"闪"。
 *
 * 所以：任何依赖屏幕半透明的动画（FADE_IN / FADE_OUT）在 PARTIAL 模式下都不成立。
 * OVER_* 位移动画没有这个问题：新屏是**不透明**的，画到哪算哪，没盖住的区域不脏、
 * 不刷新，LCD 自带 GRAM 保持原画面即可，既干净又省。
","startLine":539,"endLine":571,"size":"","modifyTime":""},{"filePath":"main/ui.c","content":"static lv_obj_t *make_app_screen(const char *title)
{
    lv_obj_t *scr = lv_obj_create(NULL);
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x101018), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(scr, 0, 0);
    lv_obj_set_style_border_opa(scr, LV_OPA_TRANSP, 0);
    lv_obj_clear_flag(scr, LV_OBJ_FLAG_SCROLLABLE);   // 固定界面，不滚动
    lv_obj_set_scrollbar_mode(scr, LV_SCROLLBAR_MODE_OFF);
    /* 状态栏由 lvgl_ui_bootstrap 在 lv_layer_top() 上统一创建，不随 screen 切换/滚动 */

    lv_obj_t *bar = lv_obj_create(scr);
    lv_obj_set_size(bar, LCD_W, 40);
    lv_obj_align(bar, LV_ALIGN_TOP_LEFT, 0, 22);
    lv_obj_set_style_bg_color(bar, lv_color_hex(0x16161F), 0);
    lv_obj_set_style_radius(bar, 0, 0);
    lv_obj_set_style_border_opa(bar, LV_OPA_TRANSP, 0);
    /* 返回栏是纯展示条，关掉滚动（否则 lv_obj_create 默认带 SCROLLABLE，
     * 整条栏会被手指拖动上下滑，既无作用又空耗 LVGL 滚动引擎） */
    lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(bar, LV_SCROLLBAR_MODE_OFF);
    lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_hor(bar, 8, 0);
    lv_obj_set_style_pad_column(bar, 8, 0);
    lv_obj_t *bk = lv_button_create(bar);
    lv_obj_set_size(bk, 80, 32);
    lv_obj_t *bkl = lv_label_create(bk);
    lv_label_set_text(bkl, "< 返回");
    lv_obj_set_style_text_font(bkl, &lv_font_cn_16, 0);
    lv_obj_center(bkl);
    lv_obj_add_event_cb(bk, go_home_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *t = lv_label_create(bar);
