  3531:/* 扫描 SD 卡小说文件夹 NOVEL_DIR 下的 .txt/.md，填入 g_sd_books */
  3532:static void novel_scan_sd(void)
  3533:{
  3534:    g_sd_count = 0;
  3535:    if (!sd_card_is_mounted()) {
  3536:        ESP_LOGI("NOVEL", "SD not mounted, try mount...");
  3537:        (void)sd_card_mount(true);
  3538:    }
  3539:    ESP_LOGI("NOVEL", "scan %s, mounted=%d", NOVEL_DIR, sd_card_is_mounted());
  3540:    DIR *d = opendir(NOVEL_DIR);
  3541:    if (!d) {
  3542:        ESP_LOGW("NOVEL", "opendir failed: %s missing or SD not mounted", NOVEL_DIR);
  3543:        return;
  3544:    }
  3545:    struct dirent *e;
  3546:    while ((e = readdir(d)) != NULL) {
  3547:        if (g_sd_count >= NOVEL_SD_MAX) break;
  3548:        const char *nm = e->d_name;
  3549:        size_t L = strlen(nm);
  3550:        if (L < 4) continue;
  3551:        bool is_txt = (L >= 5 && strcasecmp(nm + L - 4, ".txt") == 0);
  3552:        bool is_md  = (L >= 4 && strcasecmp(nm + L - 3, ".md") == 0);
  3553:        if (!is_txt && !is_md) continue;
  3554:        novel_sd_book_t *b = &g_sd_books[g_sd_count];
  3555:        size_t ext = is_txt ? 4 : 3;
  3556:        size_t tl = L - ext;
  3557:        if (tl >= sizeof(b->title)) tl = sizeof(b->title) - 1;
  3558:        memcpy(b->title, nm, tl);
  3559:        b->title[tl] = '\0';
  3560:        snprintf(b->path, sizeof(b->path), "%s/%s", NOVEL_DIR, nm);
  3561:        b->fp = NULL; b->page_off = NULL; b->pages = 0;
  3562:        ESP_LOGI("NOVEL", "  + %s", b->title);
  3563:        g_sd_count++;
  3564:    }
  3565:    closedir(d);
  3566:    ESP_LOGI("NOVEL", "total %d book(s)", g_sd_count);
  3567:}
