  4253:{
  4254:    lv_obj_t *active = lv_screen_active();
  4255:    if (!g_weather_screen || active != g_weather_screen || !g_wx_temp) return;
  4256:
  4257:    bool changed = (g_weather.version != s_wx_shown_ver) ||
  4258:                   (g_weather.fetching != s_wx_fetching) ||
  4259:                   s_wx_need_redraw ||
  4260:                   (g_wifi_state != s_wx_wifi_state);
  4261:    if (!changed) return;
