   562:/* ---------------- App 切换动画 ----------------
   563: * 结论：本硬件上只能用「整块位移」，不能用「整屏改透明度」。
   564: *
   565: * 之前试过 LV_SCREEN_LOAD_ANIM_FADE_IN，实测进 App 时屏幕明显暗一档、结束时闪一下。
   566: * 原因不是 LVGL 的 bug，是 PARTIAL 刷新模式的固有性质（lvgl_port.c:238 注册的是
   567: * PARTIAL + 两个 40 行 draw buf）：
   568: *   1. draw buf 里**从来不是整帧图像**，只有最近渲染过的若干行的像素，40 行缓冲区
   569: *      被从头到尾循环复用，所以任意时刻 buf 里装的是各种历史残留像素。
   570: *   2. 屏幕 opa<100% 时（lv_display.c 的 opa_scale_anim → lv_obj_set_style_opa），
   571: *      LVGL 渲染新屏是往 draw buf 上做 **alpha 混合**，混合对象是 buf 里那些残留像素，
   572: *      而不是"旧屏画面"（旧屏此时已经被标脏清除、且没有被重绘，见 lv_refr.c:1069-1078
   573: *      虽然遍历了 prev_scr，但对象没 invalidate 就不会画）。
   574: *      → 画面混合出一堆历史的暗像素 = 看着发暗、局部发花。
   575: *   3. 动画一结束 scr_anim_completed 立刻 lv_obj_remove_local_style_prop(scr, OPA)
   576: *      （lv_display.c:1535）把 opa 恢复成 255，残留像素的那份混色瞬间消失
   577: *      → 亮度整屏跳变一下 = 那个"闪"。
   578: *
   579: * 所以：任何依赖屏幕半透明的动画（FADE_IN / FADE_OUT）在 PARTIAL 模式下都不成立。
   580: * OVER_* 位移动画没有这个问题：新屏是**不透明**的，画到哪算哪，没盖住的区域不脏、
   581: * 不刷新，LCD 自带 GRAM 保持原画面即可，既干净又省。
   582: *
   583: * 各种动画每帧的重绘量（一屏要切成 6 块渲染+DMA）：
   584: *   MOVE_* : 新旧两屏同时位移，两个 anim 一起跑 → 12 块/帧（实测卡）
   585: *   OVER_* : 只动新屏                            →  6 块/帧  ← 用它
   586: *
   587: * 最后一个参数 auto_del 一律 false —— App 屏幕是懒加载后复用的对象，
   588: * 让 LVGL 自动删掉的话，下次打开这个 App 就没对象了。
   589: *
   590: * 如果你确实想要淡入淡出且不想发花，唯一干净的做法是「黑幕法」：
   591: * 先 lv_screen_load(scr) 原样切过去，再在整屏铺一层**不透明黑矩形**，
   592: * 把这个矩形的 opa 从 255 动到 0。黑幕和它下面的内容是同一个 tile 内先后绘制的，
   593: * alpha 混合的下层是这一帧刚画好的新屏像素，而不是 buf 残留，所以不会脏。
   594: * 代价同样是 6 块/帧（外加一层纯色 fill，很便宜）。把下面的
   595: * UI_ANIM_USE_MASK_FADE 改 1 就能用，实现在其下方。
   596: */
   597:
   598:#define APP_ANIM_MS  200   /* 切换动画时长：帧数少了，掉帧也不明显 */
   599:
   600:/* 0 = 方向滑动（当前在用，见上面分析）；1 = 黑幕淡入（实验） */
   601:#define UI_ANIM_USE_MASK_FADE  0
   602:
   603:#if UI_ANIM_USE_MASK_FADE
   604:static void ui_switch_mask(lv_obj_t *scr);   /* 实现在下面 */
   605:
   606:static lv_obj_t *s_fade_mask = NULL;   /* 正在播放的黑幕（同时只允许一个） */
   607:
   608:static void mask_opa_anim(void *obj, int32_t v)
   609:{
   610:    lv_obj_set_style_opa((lv_obj_t *)obj, v, 0);
   611:}
   612:
   613:static void mask_ready_cb(lv_anim_t *a)
   614:{
   615:    if (a->var == (void *)s_fade_mask) s_fade_mask = NULL;
   616:    lv_obj_delete((lv_obj_t *)a->var);
   617:}
   618:
   619:/* 「黑幕淡入」：不用 LV_SCREEN_LOAD_ANIM_FADE_*（那玩意儿在 PARTIAL 模式下会把
   620: * draw buf 里的残留像素混进来，画面发暗发花，见上面分析）。
   621: * 这里改成：先原样切屏，再盖一层不透明黑矩形，矩形 opa 255→0。
   622: * 黑幕和新屏内容在同一个 tile 内先后绘制，混合的下层是这一帧刚画好的新屏像素，
   623: * 不是 buf 残留 → 干净。开销同样是 6 块/帧，只多一层纯色 fill。 */
   624:static void ui_switch_mask(lv_obj_t *scr)
   625:{
   626:    /* 上一次的黑幕还没播完就又切屏：直接删掉旧的，避免多个黑幕叠着变不透明 */
   627:    if (s_fade_mask) {
   628:        lv_anim_delete(s_fade_mask, NULL);
   629:        lv_obj_delete(s_fade_mask);
   630:        s_fade_mask = NULL;
   631:    }
   632:
   633:    lv_screen_load(scr);            /* 不带动画, 立刻生效 */
   634:
   635:    lv_display_t *d = lv_display_get_default();
   636:    lv_obj_t *m = lv_obj_create(lv_layer_top());
   637:    lv_obj_remove_style_all(m);
   638:    lv_obj_remove_flag(m, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
   639:    lv_obj_set_pos(m, 0, 0);
   640:    lv_obj_set_size(m, lv_display_get_horizontal_resolution(d),
   641:                       lv_display_get_vertical_resolution(d));
   642:    lv_obj_set_style_bg_color(m, lv_color_black(), 0);
   643:    lv_obj_set_style_bg_opa(m, LV_OPA_COVER, 0);
   644:    lv_obj_set_style_opa(m, LV_OPA_COVER, 0);
   645:    s_fade_mask = m;
   646:
   647:    lv_anim_t a;
   648:    lv_anim_init(&a);
   649:    lv_anim_set_var(&a, m);
   650:    lv_anim_set_exec_cb(&a, mask_opa_anim);
   651:    lv_anim_set_values(&a, LV_OPA_COVER, LV_OPA_TRANSP);
   652:    lv_anim_set_duration(&a, APP_ANIM_MS);
   653:    lv_anim_set_completed_cb(&a, mask_ready_cb);
   654:    lv_anim_start(&a);
   655:}
   656:#endif
   657:
   658:static void ui_switch(lv_obj_t *scr, bool back)
   659:{
   660:#if UI_ANIM_USE_MASK_FADE
   661:    ui_switch_mask(scr);
   662:#else
   663:    lv_screen_load_anim(scr,
   664:                        back ? LV_SCREEN_LOAD_ANIM_OVER_RIGHT : LV_SCREEN_LOAD_ANIM_OVER_LEFT,
   665:                        APP_ANIM_MS, 0, false);
   666:#endif
   667:}
   668:
   669:void ui_open_screen_anim(lv_obj_t *scr, app_id_t id)
   670:{
   671:    if (!scr) return;
   672:    ui_switch(scr, false);      /* 进 App：新屏从右边压进来 */
   673:    g_active_app = id;
   674:    /* 系统信息定时器仅在“关于本机”屏可见时运行，进出时启停避免常驻空刷 */
   675:    if (g_sysinfo_timer) {
   676:        if (id == APP_SYSINFO) lv_timer_resume(g_sysinfo_timer);
   677:        else                   lv_timer_pause(g_sysinfo_timer);
   678:    }
   679:}
   680:
   681:/* 供 pvz.c 等外部界面调用: 跳回主界面（往回退，方向相反） */
   682:void ui_go_home(void) {
   683:    pc_mon_set_active(false);   /* 离开 App 界面，停止监控数据拉取 */
   684:    g_active_app = APP_NONE;
   685:    if (g_sysinfo_timer) lv_timer_pause(g_sysinfo_timer);
   686:    ui_switch(g_home, true);    /* 回主页：主页从左边推回来 */
   687:}
   688:
   689:/* 打开某个 App 屏幕：仅记录待跳转 id，真正的建屏/加载放到主循环里执行。","totalLineCount":5242,"hasMore":true,"hint":""}}}}}

