   623: * 不是 buf 残留 → 干净。开销同样是 6 块/帧，只多一层纯色 fill。 */
   624:static void ui_switch_mask(lv_obj_t *scr)
   625:{
   626:    /* 上一次的黑幕还没播完就又切屏：直接删掉旧的，避免多个黑幕叠着变不透明 */
   627:    if (s_fade_mask) {
   628:        lv_anim_delete(s_fade_mask, NULL);
   629:        lv_obj_delete(s_fade_mask);
   630:        s_fade_mask = NULL;
   631:    }
   632:
   633:    lv_screen_load(scr);            /* 不带动画, 立刻生效 */
   634:
   635:    lv_display_t *d = lv_display_get_default();
   636:    lv_obj_t *m = lv_obj_create(lv_layer_top());
   637:    lv_obj_remove_style_all(m);
   638:    lv_obj_remove_flag(m, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
   639:    lv_obj_set_pos(m, 0, 0);
   640:    lv_obj_set_size(m, lv_display_get_horizontal_resolution(d),
   641:                       lv_display_get_vertical_resolution(d));
   642:    lv_obj_set_style_bg_color(m, lv_color_black(), 0);
   643:    lv_obj_set_style_bg_opa(m, LV_OPA_COVER, 0);
   644:    lv_obj_set_style_opa(m, LV_OPA_COVER, 0);
   645:    s_fade_mask = m;
   646:
   647:    lv_anim_t a;
   648:    lv_anim_init(&a);
   649:    lv_anim_set_var(&a, m);
   650:    lv_anim_set_exec_cb(&a, mask_opa_anim);
   651:    lv_anim_set_values(&a, LV_OPA_COVER, LV_OPA_TRANSP);
   652:    lv_anim_set_duration(&a, APP_ANIM_MS);
   653:    lv_anim_set_completed_cb(&a, mask_ready_cb);
   654:    lv_anim_start(&a);
   655:}
   656:#endif
   657:
   658:static void ui_switch(lv_obj_t *scr, bool back)
   659:{
   660:#if UI_ANIM_USE_MASK_FADE
   661:    ui_switch_mask(scr);
   662:#else
   663:    lv_screen_load_anim(scr,
   664:                        back ? LV_SCREEN_LOAD_ANIM_OVER_RIGHT : LV_SCREEN_LOAD_ANIM_OVER_LEFT,
   665:                        APP_ANIM_MS, 0, false);
   666:#endif
   667:}
   668:
   669:void ui_open_screen_anim(lv_obj_t *scr, app_id_t id)
   670:{
   671:    if (!scr) return;
   672:    ui_switch(scr, false);      /* 进 App：新屏从右边压进来 */
   673:    g_active_app = id;
   674:    /* 系统信息定时器仅在“关于本机”屏可见时运行，进出时启停避免常驻空刷 */
   675:    if (g_sysinfo_timer) {
   676:        if (id == APP_SYSINFO) lv_timer_resume(g_sysinfo_timer);
   677:        else                   lv_timer_pause(g_sysinfo_timer);
   678:    }
   679:}
   680:
   681:/* 供 pvz.c 等外部界面调用: 跳回主界面（往回退，方向相反） */
   682:void ui_go_home(void) {
   683:    pc_mon_set_active(false);   /* 离开 App 界面，停止监控数据拉取 */
   684:    g_active_app = APP_NONE;
   685:    if (g_sysinfo_timer) lv_timer_pause(g_sysinfo_timer);
   686:    ui_switch(g_home, true);    /* 回主页：主页从左边推回来 */
   687:}
