{"requestId":"4249bf22936649fbab141fb376445c9c","modelId":"hy4flash-free","modelName":"Hy4 flash","isHelperMessage":false,"traceId":"fed59f0137682199b5790106325970b1","toolStatus":{"chatcmpl-tool-8ab409b05d469577":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/ui.c","offset":1980,"limit":42},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/ui.c","content":"  1980:/* ---------------- Weather 屏（英文显示，连上网自动拉取） ---------------- */
  1981:
  1982:/* 天气刷新间隔：数据超过这个时长即视为过期，过期才重新请求 */
  1983:#define WX_REFRESH_MS (10 * 60 * 1000)
  1984:/* 失败 / 从未成功过时的重试退避：目标服务器不可达时单次连接要等满 15s 超时，
  1985: * 若无节流会变成「超时→立刻重试」死循环，占满网络任务并刷屏。 */
  1986:#define WX_RETRY_MS  (60 * 1000)
  1987:
  1988:/* 只在「需要」时才请求天气，避免不必要的联网：
  1989: *   - 不在天气界面时，周期刷新整个跳过（见 ui_weather_periodic）；
  1990: *   - 进入界面时若数据仍然新鲜就不重复请求，来回切界面不会反复拉；
  1991: *   - force=true 用于手动点「刷新」，无视新鲜度强制拉一次。
  1992: * 返回是否真的发出了请求（weather_request 只是唤醒后台任务，不阻塞）。 */
  1993:static bool ui_weather_refresh_if_needed(bool force)
  1994:{
  1995:    if (g_wifi_state != WIFI_STA_CONNECTED) return false;
  1996:
  1997:    /* 上一次请求还在进行中，不再重复发，避免请求排队堆积 */
  1998:    if (g_weather.fetching) return false;
  1999:
  2000:    uint32_t now = lv_tick_get();
  2001:    /* 有过成功数据时按 10 分钟刷新；从未成功/上次失败时按 60 秒退避重试。
  2002:     * 旧写法是 (!stale && g_weather.valid)，valid=false 时守卫失效，
  2003:     * 导致每个 UI tick 都重发请求（15s 超时 + 立即重试的刷屏死循环）。 */
  2004:    uint32_t interval = g_weather.valid ? WX_REFRESH_MS : WX_RETRY_MS;
  2005:    if (!force && (now - s_last_wx_req_ms) < interval) return false;
  2006:
  2007:    weather_request(NULL);
  2008:    s_last_wx_req_ms = now;
  2009:    return true;
  2010:}
  2011:
  2012:static void wx_refresh_cb(lv_event_t *e)
  2013:{
  2014:    (void)e;
  2015:    ui_weather_refresh_if_needed(true);   /* 手动刷新：强制拉一次 */
  2016:}
  2017:
  2018:/* ===================== 音乐播放 =====================
  2019: * SD 卡 WAV(PCM) / MP3(minimp3) → audio_player → I2S → MAX98357A 真正出声。
  2020: * UI 只发命令、按 g_audio.version 轮询刷新，不碰 I2S，也不需要 LVGL 锁。
  2021: * 进度由实际解码/送出的数据推进，与真实播放速度天然一致；播完自动下一首。","totalLineCount":5241,"hasMore":true,"hint":""}}},"chatcmpl-tool-973744469b7ed7fb":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/ui.c","offset":801,"limit":75},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/ui.c","content":"   801:/* ---------------- 背光亮度：LEDC PWM 驱动 LCD_BLK 引脚 ---------------- */
   802:/* BLK 原来是普通 GPIO 常亮，这里改成 PWM 输出，占空比即亮度 */
   803:#define BLK_PWM_FREQ_HZ   1000
   804:#define BLK_PWM_RES       LEDC_TIMER_10_BIT                 /* 分辨率 10bit -> 0..1023 */
   805:#define BLK_MAX_DUTY      ((1u << LEDC_TIMER_10_BIT) - 1u)
   806:#define BLK_MIN_PERCENT   10        /* 最低亮度，避免调到 0 后屏幕全黑 */
   807:#define BLK_DEFAULT_PERCENT 100
   808:
   809:static uint8_t   g_brightness = BLK_DEFAULT_PERCENT;
   810:static lv_obj_t *g_br_label   = NULL;   /* 百分比数字标签 */
   811:
   812:/* 设置背光亮度（percent: BLK_MIN_PERCENT ~ 100） */
   813:static void backlight_set(uint8_t percent)
   814:{
   815:    if (percent < BLK_MIN_PERCENT) percent = BLK_MIN_PERCENT;
   816:    if (percent > 100) percent = 100;
   817:    g_brightness = percent;
   818:    uint32_t duty = (uint32_t)BLK_MAX_DUTY * percent / 100;
   819:    /* 注意：不能用 ledc_set_duty_and_update()！
   820:     * 它属于 fade 系列的线程安全 API，内部会先检查 fade 服务是否已安装，
   821:     * 未安装时会直接返回 ESP_FAIL 并打印 "Fade service not installed"，
   822:     * 占空比根本不会写入（readback 一直是初始值）。
   823:     * ledc_set_duty + ledc_update_duty 走的是非 fade 通路，不需要 fade 服务。 */
   824:    esp_err_t e1 = ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0, duty);
   825:    esp_err_t e2 = ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0);
   826:    /* 注：不要在这里用 ledc_get_duty() 做校验。它直接读硬件 duty 寄存器，
   827:     * 而新占空比要等下一个 PWM 周期才生效，紧跟着读必然读到「上一次」的值，
   828:     * 看起来像没写进去，其实是正常现象。用示波器看波形最准。 */
   829:    if (e1 != ESP_OK || e2 != ESP_OK) {
   830:        ESP_LOGE("BLK", "duty %lu failed (set=%d upd=%d)", (unsigned long)duty, (int)e1, (int)e2);
   831:    }
   832:}
   833:
   834:/* 初始化 LEDC，把 LCD_BLK 接到 PWM 通道上 */
   835:static void backlight_init(void)
   836:{
   837:    ledc_timer_config_t tcfg = {
   838:        .speed_mode      = LEDC_LOW_SPEED_MODE,
   839:        .duty_resolution = BLK_PWM_RES,
   840:        .timer_num       = LEDC_TIMER_0,
   841:        .freq_hz         = BLK_PWM_FREQ_HZ,
   842:        .clk_cfg         = LEDC_AUTO_CLK,
   843:    };
   844:    ESP_ERROR_CHECK(ledc_timer_config(&tcfg));
   845:
   846:    /* 注意：intr_type 在新版 IDF 已废弃，不要赋值，否则会有编译告警 */
   847:    ledc_channel_config_t ccfg = {
   848:        .gpio_num   = LCD_BLK_GPIO,
   849:        .speed_mode = LEDC_LOW_SPEED_MODE,
   850:        .channel    = LEDC_CHANNEL_0,
   851:        .timer_sel  = LEDC_TIMER_0,
   852:        .duty       = BLK_MAX_DUTY,      /* 默认最亮 */
   853:        .hpoint     = 0,
   854:    };
   855:    ESP_ERROR_CHECK(ledc_channel_config(&ccfg));
   856:    ESP_LOGI("BLK", "LEDC ready: GPIO%d, %luHz, %dbit",
   857:             (int)LCD_BLK_GPIO,
   858:             (unsigned long)ledc_get_freq(LEDC_LOW_SPEED_MODE, LEDC_TIMER_0),
   859:             (int)LEDC_TIMER_10_BIT);
   860:}
   861:
   862:/* 亮度滑块回调 */
   863:static void brightness_cb(lv_event_t *e)
   864:{
   865:    lv_obj_t *sl = lv_event_get_target(e);
   866:    int v = lv_slider_get_value(sl);
   867:    backlight_set((uint8_t)v);
   868:    if (g_br_label) {
   869:        lv_label_set_text_fmt(g_br_label, "%d%%", v);
   870:    }
   871:}
   872:
   873:/* 设置列表里的一条手机风格分隔线（左右各留 14px 缩进） */
   874:static void settings_add_separator(lv_obj_t *parent)
   875:{","totalLineCount":5241,"hasMore":true,"hint":""}}}}}

