  2564:static lv_obj_t *ai_add_bubble(const volatile char *text, bool is_user, lv_color_t text_color)
  2565:{
  2566:    if (!g_ai_chat_box) return NULL;
  2567:    char buf[512];
  2568:    ai_copy_volatile(text, buf, sizeof(buf));
  2569:
  2570:    /* 行容器：整行宽、高自适应，透明无边框 */
  2571:    lv_obj_t *row = lv_obj_create(g_ai_chat_box);
  2572:    lv_obj_set_width(row, LV_PCT(100));
  2573:    lv_obj_set_height(row, LV_SIZE_CONTENT);
  2574:    lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
  2575:    lv_obj_set_style_border_opa(row, LV_OPA_TRANSP, 0);
  2576:    lv_obj_set_style_pad_all(row, 0, 0);
  2577:    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
  2578:
  2579:    /* 气泡：宽度按内容自适应但设最大宽，圆角，用户/AI 不同底色 */
  2580:    lv_obj_t *bub = lv_obj_create(row);
  2581:    lv_obj_set_width(bub, LV_SIZE_CONTENT);
  2582:    lv_obj_set_style_max_width(bub, LCD_W - 60, 0);
  2583:    lv_obj_set_height(bub, LV_SIZE_CONTENT);
  2584:    lv_obj_set_style_bg_color(bub, is_user ? lv_color_hex(0x2E7DE0) : lv_color_hex(0x2A2A38), 0);
  2585:    lv_obj_set_style_radius(bub, 8, 0);
  2586:    lv_obj_set_style_border_opa(bub, LV_OPA_TRANSP, 0);
  2587:    lv_obj_set_style_pad_all(bub, 6, 0);
  2588:    lv_obj_set_style_pad_gap(bub, 0, 0);
  2589:    lv_obj_clear_flag(bub, LV_OBJ_FLAG_SCROLLABLE);
  2590:    if (is_user) lv_obj_align(bub, LV_ALIGN_RIGHT_MID, 0, 0);
  2591:    else         lv_obj_align(bub, LV_ALIGN_LEFT_MID, 0, 0);
  2592:
  2593:    /* 气泡内文字：自动换行、中文字库、按传入色（错误时红） */
  2594:    lv_obj_t *lab = lv_label_create(bub);
  2595:    lv_obj_set_width(lab, LV_SIZE_CONTENT);
  2596:    lv_obj_set_style_max_width(lab, LCD_W - 72, 0);
  2597:    lv_label_set_long_mode(lab, LV_LABEL_LONG_WRAP);
  2598:    lv_obj_set_style_text_font(lab, &lv_font_cn_16, 0);
  2599:    lv_obj_set_style_text_color(lab, text_color, 0);
  2600:    lv_label_set_text(lab, buf);
  2601:
  2602:    lv_obj_scroll_to_y(g_ai_chat_box, LV_COORD_MAX, LV_ANIM_OFF);
  2603:    return lab;   /* 返回 label 便于更新「思考中」 */
  2604:}
  2605:
  2606:/* 兼容旧调用：按 who 判断左右，颜色由调用方给 */
  2607:static void ai_add_msg(const char *who, const volatile char *text, lv_color_t color)
  2608:{
  2609:    bool is_user = (who && strcmp(who, "我") == 0);
  2610:    ai_add_bubble(text, is_user, color);
  2611:}","totalLineCount":5302,"hasMore":true,"hint":""}}}}}

