 * 超出时删最老的，避免长时间聊天累积 LVGL 对象耗尽内存池。 */
#define AI_MAX_BUBBLES 10

/* 微信式气泡：is_user=true 靠右绿色，false 靠左深灰。返回气泡对象供复用。
 * text 是 volatile，先拷到局部。每行一个行容器 + 一个气泡 + 一个 label，
 * 消息列表用 flex column 自动往下排，不再重叠。 */
static lv_obj_t *ai_add_bubble(const volatile char *text, bool is_user, lv_color_t text_color)
{
    if (!g_ai_chat_box) return NULL;
    char buf[512];
    ai_copy_volatile(text, buf, sizeof(buf));

    /* 超出上限删最老的气泡（child[0] 是最早那轮）。思考中气泡总是最新创建的，
     * 不会被删到；但仍校验句柄，万一被删就置空，避免刷新回调操作失效对象。 */
    while (lv_obj_get_child_count(g_ai_chat_box) >= AI_MAX_BUBBLES) {
        lv_obj_t *oldest = lv_obj_get_child(g_ai_chat_box, 0);
        if (!oldest) break;
        if (g_ai_thinking_bubble && lv_obj_is_child(g_ai_thinking_bubble, oldest))
            g_ai_thinking_bubble = NULL;
        lv_obj_delete(oldest);
    }

    /* 行容器：整行宽、高自适应，透明无边框 */
    lv_obj_t *row = lv_obj_create(g_ai_chat_box);","explanation":"加聊天气泡上限，超过 5 轮删最老的。"},"result":{"status":"success","success":true,"errorCode":"0","result":{"type":"replace_in_file_result","path":"c:/esp32/LCD/main/ui.c","addLineCount":14,"removedLines":0,"addedChars":936,"removedChars":415,"matchCount":1}}}},"responseId":"gen-1795139807-LRLxJ6FjUgaEvKWrMKLV"}

