def utf8_strncpy(src, cap):
    data = src.encode('utf-8')
    n = 0
    while n < len(data) and n < cap - 1:
        n += 1
    buf = list(data[:n])
    while len(buf) > 0:
        start = len(buf) - 1
        while start > 0 and (buf[start] & 0xC0) == 0x80:
            start -= 1
        lead = buf[start]
        need = 1 if lead < 0x80 else 2 if lead < 0xE0 else 3 if lead < 0xF0 else 4
        if len(buf) - start >= need:
            break
        buf = buf[:start]
    out = bytes(buf)
    try:
        return len(out), True, out.decode('utf-8')
    except Exception:
        return len(out), False, ''

