{"role":"assistant","content":[{"type":"text","text":"转义逻辑清楚。现在写完整的 `voice_tts.c`："},{"type":"tool-call","toolCallId":"chatcmpl-tool-923d4b12cc4b5d54","toolName":"write_to_file","args":{"filePath":"c:/esp32/LCD/main/voice_tts.c","content":"#include "voice_tts.h"
#include "ai_chat.h"          /* ai_chat_key_cached：从缓存读 Key，PSRAM 栈禁止 NVS */
#include "audio_player.h"     /* audio_player_play：播放生成的 WAV */
#include "sd_card.h"          /* SD_MOUNT_POINT / sd_card_is_mounted */
#include "esp_log.h"
#include "esp_heap_caps.h"
#include "esp_http_client.h"
#include "esp_crt_bundle.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/semphr.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *TAG = "TTS";

/* 智谱 GLM-TTS：POST /api/paas/v4/audio/speech，返回裸 WAV 二进制 */
#define TTS_URL       "https://open.bigmodel.cn/api/paas/v4/audio/speech"
#define TTS_MODEL     "glm-tts"
#define TTS_VOICE     "tongtong"
#define TTS_TIMEOUT_MS 20000      /* TTS 生成较慢，给 20s */

volatile voice_tts_state_t g_tts;

static SemaphoreHandle_t s_sem = NULL;
static char  s_text[600];          /* 待合成文本（PSRAM 任务只读） */
static char *s_body = NULL;        /* JSON 请求体，PSRAM */
#define BODY_CAP (4 * 1024)

static void tts_task(void *arg);

static void publish(void) { g_tts.version++; }

static void set_hint(const char *s)
{
    size_t i = 0;
    if (s) for (; i + 1 < sizeof(g_tts.hint) && s[i]; i++) g_tts.hint[i] = s[i];
    g_tts.hint[i] = '\0';
}

/* JSON 字符串转义（引号/反斜杠/控制字符），UTF-8 中文原样拷贝 */
static void json_escape(const char *s, char *out, size_t cap)
{
    size_t n = 0;
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        if (n + 7 >= cap) break;
        switch (c) {
            case '"':  memcpy(out + n, "\\\"", 2); n += 2; break;
            case '\\': memcpy(out + n, "\\\\", 2); n += 2; break;
            case '\n': memcpy(out + n, "\\n", 2);  n += 2; break;
            case '\r': memcpy(out + n, "\\r", 2);  n += 2; break;
            case '\t': memcpy(out + n, "\\t", 2);  n += 2; break;
            default:
                if (c < 0x20) { snprintf(out + n, 8, "\\u%04x", c); n += 6; }
                else out[n++] = (char)c;
                break;
        }
    }
    out[n] = '\0';
}

/* 生成一个不重复的 WAV 路径：/sdcard/TTS_xxxx.wav（递增计数） */
static void make_tts_path(char *out, size_t cap)
{
    static int counter = 0;
    int id = ++counter;
    snprintf(out, cap, "%s/TTS_%04d.wav", SD_MOUNT_POINT, id);
}

void voice_tts_init(void)
{
    s_body = heap_caps_malloc(BODY_CAP, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!s_body) {
        ESP_LOGE(TAG, "PSRAM alloc failed for TTS body");
        return;
    }
    s_sem = xSemaphoreCreateBinary();
    if (!s_sem) {
        ESP_LOGE(TAG, "sem create failed");
        return;
    }
    BaseType_t ok = xTaskCreateWithCaps(tts_task, "tts", 24576, NULL, 3, NULL,
                                        MALLOC_CAP_SPIRAM);
    if (ok != pdPASS) {
        ESP_LOGE(TAG, "PSRAM-stack task create failed (%d)", (int)ok);
        ok = xTaskCreate(tts_task, "tts", 16384, NULL, 3, NULL);
    }
    if (ok == pdPASS) ESP_LOGI(TAG, "tts task started");
}

void voice_tts_speak(const char *text)
{
    if (!s_sem || !text || !text[0]) return;
    if (g_tts.busy) return;              /* 正在合成，忽略新请求 */
    size_t n = 0;
    while (n + 1 < sizeof(s_text) && text[n]) { s_text[n] = text[n]; n++; }
    s_text[n] = '\0';
    g_tts.busy = true;
    g_tts.error = false;
    set_hint("");
    publish();
    xSemaphoreGive(s_sem);
}

bool voice_tts_is_busy(void) { return g_tts.busy; }

void voice_tts_stop(void)
{
    audio_player_stop();
}

/* 单次合成：POST JSON，成功返回 true 且写好了 WAV 到 g_tts.path */
static bool tts_post_once(const char *key, const char *path)
{
    /* 组装 JSON：input 文本做转义 */
    char esc[2 * sizeof(s_text) + 8];
    json_escape(s_text, esc, sizeof(esc));
    int n = snprintf(s_body, BODY_CAP,
                     "{\"model\":\"%s\",\"input\":\"%s\",\"voice\":\"%s\","
                     "\"response_format\":\"wav\",\"speed\":1.0}",
                     TTS_MODEL, esc, TTS_VOICE);
    if (n < 0 || n >= BODY_CAP) {
        set_hint("文本过长");
        return false;
    }

    char auth[160];
    snprintf(auth, sizeof(auth), "Bearer %s", key);

    esp_http_client_config_t cfg = {
        .url = TTS_URL,
        .method = HTTP_METHOD_POST,
        .crt_bundle_attach = esp_crt_bundle_attach,
        .timeout_ms = TTS_TIMEOUT_MS,
        .user_agent = "esp32-voice-tts/1.0",
    };
    esp_http_client_handle_t c = esp_http_client_init(&cfg);
    if (!c) { set_hint("HTTP 初始化失败"); return false; }
    esp_http_client_set_header(c, "Content-Type", "application/json");
    esp_http_client_set_header(c, "Authorization", auth);

    bool ok = false;
    FILE *f = NULL;
    if (esp_http_client_open(c, n) == ESP_OK) {
        esp_http_client_write(c, s_body, n);
        esp_http_client_fetch_headers(c);
        int status = esp_http_client_get_status_code(c);
        if (status == 200) {
            f = fopen(path, "wb");
            if (!f) {
                ESP_LOGE(TAG, "open wav file failed: %s", path);
                set_hint("写文件失败");
            } else {
                /* 流式读 WAV 直接写文件，不占内存 */
                char chunk[2048];
                int total = 0, r;
                while (total < 4 * 1024 * 1024 &&
                       (r = esp_http_client_read(c, chunk, sizeof(chunk))) > 0) {
                    if (fwrite(chunk, 1, r, f) != (size_t)r) {
                        ESP_LOGE(TAG, "wav write failed");
                        break;
                    }
                    total += r;
                }
                fclose(f);
                f = NULL;
                if (total > 44) {   /*至少要有 WAV 头 */
                    ESP_LOGI(TAG, "wav saved: %s (%d bytes)", path, total);
                    ok = true;
                } else {
                    set_hint("音频数据为空");
                }
            }
        } else {
            char err[128];
            int er = esp_http_client_read(c, err, sizeof(err) - 1);
            if (er > 0) err[er] = '\0'; else err[0] = '\0';
            ESP_LOGE(TAG, "HTTP status %d body: %.120s", status, err);
            if (status == 429) set_hint("额度不足或请求过频");
            else if (status >= 400 && status < 500) set_hint("Key 或参数错误");
            else set_hint("合成服务异常");
        }
        esp_http_client_close(c);
    } else {
        set_hint("连接失败");
    }
    esp_http_client_cleanup(c);
    if (f) fclose(f);
    return ok;
}

static void tts_task(void *arg)
{
    (void)arg;
    for (;;) {
        if (xSemaphoreTake(s_sem, portMAX_DELAY) != pdTRUE) continue;

        /* 从缓存读 Key（PSRAM 栈任务禁止 NVS） */
        char key[128];
        if (!ai_chat_key_cached(key, sizeof(key))) {
            set_hint("请先配置智谱 API Key");
            g_tts.error = true; g_tts.busy = false; publish();
            continue;
        }
        if (!sd_card_is_mounted()) {
            set_hint("无 SD 卡");
            g_tts.error = true; g_tts.busy = false; publish();
            continue;
        }

        char path[160];
        make_tts_path(path, sizeof(path));

        /* 连接失败重试 1 次（对抗偶发丢 SYN） */
        bool ok = tts_post_once(key, path);
        if (!ok && g_tts.hint[0] && strcmp(g_tts.hint, "连接失败") == 0) {
            ESP_LOGW(TAG, "retry once after connect failure");
            ok = tts_post_once(key, path);
        }

        if (ok) {
            size_t i = 0;
            for (; i + 1 < sizeof(g_tts.path) && path[i]; i++) g_tts.path[i] = path[i];
            g_tts.path[i] = '\0';
            set_hint("");
            /* 播放交给 audio_player（命令队列，线程安全） */
            audio_player_play(g_tts.path);
        } else {
            g_tts.error = true;
        }
        g_tts.busy = false;
        publish();
    }
}
