        ESP_LOGE(TAG, "sem create failed");
        return;
    }
    BaseType_t ok = xTaskCreateWithCaps(tts_task, "tts", 24576, NULL, 3, NULL,
                                        MALLOC_CAP_SPIRAM);
    if (ok != pdPASS) {
        ESP_LOGE(TAG, "PSRAM-stack task create failed (%d)", (int)ok);
        ok = xTaskCreate(tts_task, "tts", 16384, NULL, 3, NULL);
    }
    if (ok == pdPASS) ESP_LOGI(TAG, "tts task started");
}

void voice_tts_speak(const char *text)
{
    if (!s_sem || !text || !text[0]) return;
    if (g_tts.busy) return;              /* 正在合成，忽略新请求 */
    size_t n = 0;
    while (n + 1 < sizeof(s_text) && text[n]) { s_text[n] = text[n]; n++; }
    s_text[n] = '\0';
    g_tts.busy = true;
    g_tts.error = false;
    set_hint("");
    publish();
    xSemaphoreGive(s_sem);
}

bool voice_tts_is_busy(void) { return g_tts.busy; }

void voice_tts_stop(void)
{
    audio_player_stop();
}

/* 单次合成：POST JSON，成功返回 true 且写好了 WAV 到 g_tts.path */
static bool tts_post_once(const char *key, const char *path)
{
    /* 组装 JSON：input 文本做转义 */
    char esc[2 * sizeof(s_text) + 8];
    json_escape(s_text, esc, sizeof(esc));
    int n = snprintf(s_body, BODY_CAP,
                     "{\"model\":\"%s\",\"input\":\"%s\",\"voice\":\"%s\","
                     "\"response_format\":\"wav\",\"speed\":1.0}",
                     TTS_MODEL, esc, TTS_VOICE);
    if (n < 0 || n >= BODY_CAP) {
        set_hint("文本过长");
        return false;
    }

    char auth[160];
    snprintf(auth, sizeof(auth), "Bearer %s", key);

    esp_http_client_config_t cfg = {
        .url = TTS_URL,
        .method = HTTP_METHOD_POST,
        .crt_bundle_attach = esp_crt_bundle_attach,
        .timeout_ms = TTS_TIMEOUT_MS,
        .user_agent = "esp32-voice-tts/1.0",
    };
    esp_http_client_handle_t c = esp_http_client_init(&cfg);
    if (!c) { set_hint("HTTP 初始化失败"); return false; }
    esp_http_client_set_header(c, "Content-Type", "application/json");
    esp_http_client_set_header(c, "Authorization", auth);

    bool ok = false;
    FILE *f = NULL;
    if (esp_http_client_open(c, n) == ESP_OK) {
        esp_http_client_write(c, s_body, n);
        esp_http_client_fetch_headers(c);
        int status = esp_http_client_get_status_code(c);
        if (status == 200) {
            f = fopen(path, "wb");
            if (!f) {
                ESP_LOGE(TAG, "open wav file failed: %s", path);
                set_hint("写文件失败");
            } else {
                /* 流式读 WAV 直接写文件，不占内存 */
                char chunk[2048];
                int total = 0, r;
                while (total < 4 * 1024 * 1024 &&
                       (r = esp_http_client_read(c, chunk, sizeof(chunk))) > 0) {
                    if (fwrite(chunk, 1, r, f) != (size_t)r) {
                        ESP_LOGE(TAG, "wav write failed");
                        break;
                    }
                    total += r;
                }
                fclose(f);
                f = NULL;
                if (total > 44) {   /*至少要有 WAV 头 */
                    ESP_LOGI(TAG, "wav saved: %s (%d bytes)", path, total);
                    ok = true;
                } else {
                    set_hint("音频数据为空");
                }
            }
        } else {
            char err[128];
            int er = esp_http_client_read(c, err, sizeof(err) - 1);
            if (er > 0) err[er] = '\0'; else err[0] = '\0';
            ESP_LOGE(TAG, "HTTP status %d body: %.120s", status, err);
            if (status == 429) set_hint("额度不足或请求过频");
            else if (status >= 400 && status < 500) set_hint("Key 或参数错误");
            else set_hint("合成服务异常");
        }
        esp_http_client_close(c);
    } else {
        set_hint("连接失败");
    }
    esp_http_client_cleanup(c);
    if (f) fclose(f);
    return ok;
}

static void tts_task(void *arg)
{
    (void)arg;
    for (;;) {
        if (xSemaphoreTake(s_sem, portMAX_DELAY) != pdTRUE) continue;

        /* 从缓存读 Key（PSRAM 栈任务禁止 NVS） */
        char key[128];
        if (!ai_chat_key_cached(key, sizeof(key))) {
            set_hint("请先配置智谱 API Key");
            g_tts.error = true; g_tts.busy = false; publish();
            continue;
        }
        if (!sd_card_is_mounted()) {
            set_hint("无 SD 卡");
            g_tts.error = true; g_tts.busy = false; publish();
            continue;
        }

        char path[160];
        make_tts_path(path, sizeof(path));

        /* 连接失败重试 1 次（对抗偶发丢 SYN） */
        bool ok = tts_post_once(key, path);
        if (!ok && g_tts.hint[0] && strcmp(g_tts.hint, "连接失败") == 0) {
            ESP_LOGW(TAG, "retry once after connect failure");
            ok = tts_post_once(key, path);
        }

        if (ok) {
            size_t i = 0;
            for (; i + 1 < sizeof(g_tts.path) && path[i]; i++) g_tts.path[i] = path[i];
            g_tts.path[i] = '\0';
            set_hint("");
            /* 播放交给 audio_player（命令队列，线程安全） */
            audio_player_play(g_tts.path);
        } else {
            g_tts.error = true;
        }
        g_tts.busy = false;
        publish();
    }
}
