    42:/* MAX98357A 的 SD_MODE：低=关断(静音省电)，高=工作。开机保持关断，避免上电噗声 */
    43:static void amp_enable(bool on)
    44:{
    45:    gpio_num_t pin = AUDIO_I2S_SD_MODE_GPIO;
    46:    if (pin < 0) return;                 /* 宏设为 GPIO_NUM_NC：硬件已上拉，跳过 */
    47:    gpio_set_level(pin, on ? 1 : 0);
    48:}
    49:
    50:static esp_err_t i2s_set_rate(uint32_t rate)
    51:{
    52:    if (!s_tx) {
    53:        i2s_chan_config_t ch = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    54:        /* 默认 6×240 帧 ≈ 5.7KB 内部 DMA 内存，本项目内部 DRAM 紧张，减到 4×240 */
    55:        ch.dma_desc_num  = 4;
    56:        ch.dma_frame_num = 240;
    57:        esp_err_t err = i2s_new_channel(&ch, &s_tx, NULL);
    58:        if (err != ESP_OK) return err;
    59:
    60:        i2s_std_config_t std = {
    61:            .clk_cfg  = I2S_STD_CLK_DEFAULT_CONFIG(rate),
    62:            /* 统一输出 16bit / 双声道。MAX98357A 无 MCLK，内部从 BCLK 恢复时钟 */
    63:            .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT,
    64:                                                             I2S_SLOT_MODE_STEREO),
    65:            .gpio_cfg = {
    66:                .mclk = I2S_GPIO_UNUSED,
    67:                .bclk = AUDIO_I2S_BCLK_GPIO,
    68:                .ws   = AUDIO_I2S_LRCK_GPIO,
    69:                .dout = AUDIO_I2S_DOUT_GPIO,
    70:                .din  = I2S_GPIO_UNUSED,
    71:                .invert_flags = { .mclk_inv = false, .bclk_inv = false, .ws_inv = false },
    72:            },
    73:        };
    74:        err = i2s_channel_init_std_mode(s_tx, &std);
    75:        if (err != ESP_OK) return err;
    76:    } else {
    77:        if (s_tx_enabled) {
    78:            i2s_channel_disable(s_tx);
    79:            s_tx_enabled = false;
    80:        }
    81:        i2s_std_clk_config_t clk = I2S_STD_CLK_DEFAULT_CONFIG(rate);
    82:        esp_err_t err = i2s_channel_reconfig_std_clock(s_tx, &clk);
    83:        if (err != ESP_OK) return err;
    84:    }
    85:    esp_err_t err = i2s_channel_enable(s_tx);
    86:    if (err == ESP_OK) s_tx_enabled = true;
    87:    return err;
    88:}
