   365:
   366:    bool got = samples > 0;
   367:    if (got) {
   368:        int ch = (info.channels == 1 || info.channels == 2) ? info.channels : 2;
   369:        /* minimp3 输出 int16 交错 PCM；统一扩成双声道并施加软件音量 */
   370:        for (int i = 0; i < samples; i++) {
   371:            int32_t l = s_mp3_pcm[i * ch];
   372:            int32_t r = (ch == 2) ? s_mp3_pcm[i * ch + 1] : l;
   373:            s_out[2 * i]     = (int16_t)(l * s_volume / 100);
   374:            s_out[2 * i + 1] = (int16_t)(r * s_volume / 100);
   375:        }
