   377:        s_decoded += (uint64_t)samples;
   378:        /* 进度按真实解码出的采样数算，VBR 也准（与 I2S 实际输出同步） */
   379:        g_audio.pos_ms = (uint32_t)((s_decoded * 1000) / s_trk.rate);
   380:    }
