        esp_err_t e3 = gpio_set_level(pin, on ? 1 : 0);
        ESP_LOGW(TAG, "amp pin %d mismatch: set=%d lvl=%d | cfg=%d set2=%d lvl2=%d",
                 (int)pin, (int)e1, lvl, (int)e2, (int)e3, gpio_get_level(pin));
    }
}","explanation":"诊断 GPIO 写入返回值，区分软件/硬件问题。"}}]}

