   620:void audio_player_init(void)
   621:{
   622:    /* g_audio 是 volatile 且由后台任务写，这里任务尚未创建，BSS 已清零，
   623:     * 只显式初始化常量字段即可（不对 volatile 对象做 memset） */
   624:    g_audio.volume = s_volume;
   625:    g_audio.hint[0] = '\0';
   626:
   627:    gpio_num_t sd = AUDIO_I2S_SD_MODE_GPIO;
   628:    if (sd >= 0) {
   629:        gpio_config_t io = {
   630:            .pin_bit_mask = 1ULL << (unsigned)sd,
   631:            .mode         = GPIO_MODE_OUTPUT,
   632:            .pull_up_en   = GPIO_PULLUP_DISABLE,
   633:            .pull_down_en = GPIO_PULLDOWN_DISABLE,
   634:            .intr_type    = GPIO_INTR_DISABLE,
   635:        };
   636:        gpio_config(&io);
   637:        gpio_set_level(sd, 0);
   638:    }
   639:
   640:    /* 缓冲在开机、内存最空时一次性分配，之后常驻（合计约 20KB PSRAM） */
   641:    const uint32_t caps = MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT;
   642:    s_src     = (uint8_t *)heap_caps_malloc(SRC_BYTES, caps);
   643:    s_out     = (int16_t *)heap_caps_malloc(OUT_SAMPLES * sizeof(int16_t), caps);
   644:    s_mp3_in  = (uint8_t *)heap_caps_malloc(MP3_IN_CAP, caps);
   645:    s_mp3_pcm = (int16_t *)heap_caps_malloc(MINIMP3_MAX_SAMPLES_PER_FRAME * sizeof(int16_t), caps);
   646:    s_mp3dec  = (mp3dec_t *)heap_caps_malloc(sizeof(mp3dec_t), caps);
   647:    if (!s_src || !s_out || !s_mp3_in || !s_mp3_pcm || !s_mp3dec) {
   648:        ESP_LOGE(TAG, "audio buffers alloc failed (PSRAM), player disabled");
   649:        return;
   650:    }
   651:    mp3dec_init(s_mp3dec);
   652:
   653:    s_q = xQueueCreate(4, sizeof(audio_cmd_t));
   654:    if (!s_q) { ESP_LOGE(TAG, "cmd queue create failed"); return; }
   655:
   656:    /* minimp3 的 mp3dec_scratch_t ≈16KB 是栈变量，任务栈必须 ≥24KB；
