   658:    BaseType_t ok = xTaskCreateWithCaps(audio_task, "audio", 28672, NULL, 5, NULL,
   659:                                        MALLOC_CAP_SPIRAM);
   660:    if (ok != pdPASS) {
   661:        ok = xTaskCreate(audio_task, "audio", 28672, NULL, 5, &s_task);
   662:    }
   663:    if (ok != pdPASS) {
   664:        ESP_LOGE(TAG, "audio task create failed");
   665:        return;
   666:    }
   667:    ESP_LOGI(TAG, "init ok (WAV+MP3), I2S BCLK=%d LRCK=%d DOUT=%d SD_MODE=%d",
   668:             (int)AUDIO_I2S_BCLK_GPIO, (int)AUDIO_I2S_LRCK_GPIO,
   669:             (int)AUDIO_I2S_DOUT_GPIO, (int)AUDIO_I2S_SD_MODE_GPIO);
