   192:                    if (fwrite(chunk, 1, r, f) != (size_t)r) {
   193:                        ESP_LOGE(TAG, "wav write failed");
   194:                        break;
   195:                    }
   196:                    total += r;
   197:                }
   198:                fclose(f);
   199:                f = NULL;
   200:                if (total > 44) {   /*至少要有 WAV 头 */
   201:                    ESP_LOGI(TAG, "wav saved: %s (%d bytes)", path, total);
   202:                    ok = true;
   203:                } else {
