   226:static void tts_task(void *arg)
   227:{
   228:    (void)arg;
   229:    for (;;) {
   230:        if (xSemaphoreTake(s_sem, portMAX_DELAY) != pdTRUE) continue;
   231:
   232:        /* 从缓存读 Key（PSRAM 栈任务禁止 NVS） */
   233:        char key[128];
   234:        if (!ai_chat_key_cached(key, sizeof(key))) {
   235:            set_hint("请先配置智谱 API Key");
   236:            g_tts.error = true; g_tts.busy = false; publish();
   237:            continue;
   238:        }
   239:        if (!sd_card_is_mounted()) {
   240:            set_hint("无 SD 卡");
   241:            g_tts.error = true; g_tts.busy = false; publish();
   242:            continue;
   243:        }
   244:
   245:        char path[160];
   246:        make_tts_path(path, sizeof(path));
   247:
   248:        /* 连接失败重试 1 次（对抗偶发丢 SYN）；HTTP 400/429 等业务错误不重试用 */
   249:        bool ok = tts_post_once(key, path);
   250:        if (!ok && s_conn_failed) {
   251:            ESP_LOGW(TAG, "retry once after connect failure");
   252:            ok = tts_post_once(key, path);
   253:        }
   254:
   255:        if (ok) {
   256:            size_t i = 0;
   257:            for (; i + 1 < sizeof(g_tts.path) && path[i]; i++) g_tts.path[i] = path[i];
   258:            g_tts.path[i] = '\0';
   259:            set_hint("");
   260:            /* 播放交给 audio_player（命令队列，线程安全）。传局部 path（非 volatile） */
   261:            audio_player_play(path);
   262:        } else {
   263:            g_tts.error = true;
   264:        }
   265:        g_tts.busy = false;
   266:        publish();
   267:    }
   268:}
