static char *s_body = NULL;        /* JSON 请求体，PSRAM */
static bool  s_conn_failed = false; /* 上次请求是否连接失败（供重试判断，避免比较 volatile 字符串） */
#define BODY_CAP (8 * 1024)   /* 留足转义膨胀空间，避免 json_escape 在多字节字符中间截断 */

