/* JSON 字符串转义（引号/反斜杠/控制字符），UTF-8 中文原样拷贝。返回写入字节数。 */
static size_t json_escape(const char *s, char *out, size_t cap)
{
    size_t n = 0;
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        if (n + 7 >= cap) break;
        switch (c) {
            case '"':  memcpy(out + n, "\\\"", 2); n += 2; break;
            case '\\': memcpy(out + n, "\\\\", 2); n += 2; break;
            case '\n': memcpy(out + n, "\\n", 2);  n += 2; break;
            case '\r': memcpy(out + n, "\\r", 2);  n += 2; break;
            case '\t': memcpy(out + n, "\\t", 2);  n += 2; break;
            default:
                if (c < 0x20) { snprintf(out + n, 8, "\\u%04x", c); n += 6; }
                else out[n++] = (char)c;
                break;
        }
    }
    out[n] = '\0';
    return n;
}

/* 生成一个不重复的 WAV 路径：/sdcard/TTS_xxxx.wav（递增计数） */
static void make_tts_path(char *out, size_t cap)
{
    static int counter = 0;
    int id = ++counter;
    snprintf(out, cap, "%s/TTS_%04d.wav", SD_MOUNT_POINT, id);
}

void voice_tts_init(void)
{
    s_body = heap_caps_malloc(BODY_CAP, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!s_body) {
