   305:                for (size_t k = 0; k < clen && *p; k++) dst[dn++] = *p++;
   306:                chars++;
   307:            }
   308:            dst[dn] = '\0';
   309:            if (dn == 0) break;
   310:            seg_count++;
   311:        }
   312:
   313:        bool all_ok = true;
   314:        for (int i = 0; i < seg_count && g_tts.busy; i++) {
   315:            char path[160];
