   317:            bool ok = baidu_tts_once(segs[i], path);
   318:            if (!ok) { all_ok = false; break; }
   319:
   320:            if (i == 0) {
   321:                size_t k = 0;
   322:                for (; k + 1 < sizeof(g_tts.path) && path[k]; k++) g_tts.path[k] = path[k];
   323:                g_tts.path[k] = '\0';
   324:            }
   325:            set_hint("");
   326:            audio_player_play(path);
   327:            publish();
   328:            if (!wait_play_done(60000)) break;   /* 等待本段播完再合成下一段 */
   329:        }
   330:
   331:        if (!all_ok) g_tts.error = true;
   332:        g_tts.busy = false;
   333:        publish();
   334:    }
