重写这段逻辑："},{"type":"tool-call","toolCallId":"chatcmpl-tool-b93a6299591a921f","toolName":"replace_in_file","args":{"filePath":"c:/esp32/LCD/main/voice_tts.c","old_str":"        int status = esp_http_client_get_status_code(c);
