                    set_hint("音频数据为空");
                }
            }
        } else {
            /* 失败：head 已读出，拼上剩余错误体打印 */
            char err[160];
            int n = hn > 0 ? hn : 0;
            if (n > (int)sizeof(err) - 1) n = sizeof(err) - 1;
            memcpy(err, head, n);
            int er = esp_http_client_read(c, err + n, sizeof(err) - 1 - n);
            if (er > 0) n += er;
            err[n] = '\0';
            ESP_LOGE(TAG, "HTTP %d body: %.150s", status, err);
            if (strstr(err, "502") || strstr(err, "token")) {
                s_token[0] = '\0'; s_token_expire_ms = 0;   /* token 失效，强制下次重取 */
                set_hint("鉴权失效，正在重试");
            } else {
                set_hint("合成失败，检查额度/网络");
            }
        }","explanation":"改用 WAV 魔数 RIFF 判断成功，兼容百度错误的 Content-Type。"}}]}

