                if (r2 <= 0) break;
                wlen += r2;
            }
            uint32_t expect = 0;
            for (int off = 12; off + 8 <= wlen; ) {
                uint32_t cksz = (uint8_t)wh[off+4] | ((uint8_t)wh[off+5] << 8) |
                                ((uint32_t)(uint8_t)wh[off+6] << 16) | ((uint32_t)(uint8_t)wh[off+7] << 24);
                if (!memcmp(wh + off, "data", 4)) { expect = cksz; break; }
                int next = off + 8 + (int)cksz + (cksz & 1);
                if (next <= off) break;
