                else total += wlen;
                char chunk[2048];
                int r;
                while (total < 2 * 1024 * 1024 &&
                       (r = esp_http_client_read(c, chunk, sizeof(chunk))) > 0) {
                    if (fwrite(chunk, 1, r, f) != (size_t)r) { ESP_LOGE(TAG, "wav write failed"); break; }
