        /* 百度的 Content-Type 不一定标 audio，改用响应体魔数判断成功：
         * MP3 以 "ID3" 或 MPEG 帧同步 0xFF 0xEx 开头；WAV 以 "RIFF" 开头（兼容旧版）。 */
        char *head = (char *)s_rxbuf;   /* 内部 RAM：TLS 解密目标不能在 PSRAM */
        int hn = esp_http_client_read(c, head, 16);
        bool is_mp3 = (hn >= 3 && !memcmp(head, "ID3", 3)) ||
                      (hn >= 2 && (uint8_t)head[0] == 0xFF && ((uint8_t)head[1] & 0xE0) == 0xE0);
        bool is_wav = (hn >= 4 && !memcmp(head, "RIFF", 4));
        /* Content-Length 用于完整性校验（TLS 中途报错会截断，只下到几 KB） */
        char *cl_str = NULL;
        esp_http_client_get_header(c, "Content-Length", &cl_str);
        uint32_t cl = cl_str ? (uint32_t)strtoul(cl_str, NULL, 10) : 0;
        if (status == 200 && (is_mp3 || is_wav)) {
            f = fopen(path, "wb");
            if (!f) {
                set_hint("写文件失败");
            } else {
                int total = 0;
                if (fwrite(head, 1, hn, f) != (size_t)hn) { ESP_LOGE(TAG, "audio head write failed"); }
                else total += hn;
                /* chunk 也用内部 RAM 的 s_rxbuf（head 已写入文件，可安全覆盖） */
                int r;
                while (total < 2 * 1024 * 1024 &&
                       (r = esp_http_client_read(c, (char *)s_rxbuf, sizeof(s_rxbuf))) > 0) {
                    if (fwrite(s_rxbuf, 1, r, f) != (size_t)r) { ESP_LOGE(TAG, "audio write failed"); break; }
                    total += r;
                }
                fclose(f);
                f = NULL;
                /* 完整性校验：有 Content-Length 时必须下满；无则只要求 > 头长度。
                 * 不足=被 TLS 错误截断，删掉残缺文件重试，绝不当成功。 */
                bool complete = cl ? ((uint32_t)total >= cl) : (total > (is_wav ? 44 : 4));
                if (complete) {
                    ESP_LOGI(TAG, "audio saved: %s (%d bytes, CL=%u)", path, total, (unsigned)cl);
                    ok = true;
                } else {
                    ESP_LOGE(TAG, "audio truncated: got %d bytes, CL=%u -> retry", total, (unsigned)cl);
                    remove(path);
                    s_conn_fail = true;   /* 触发任务层重试 */
                    set_hint("音频下载不全，重试中");
                }
            }
        } else {
            /* 失败：head 已读出，拼上剩余错误体打印 */
            char err[160];
            int n = hn > 0 ? hn : 0;
            if (n > (int)sizeof(err) - 1) n = sizeof(err) - 1;
