   292:void voice_tts_init(void)
   293:{
   294:    s_body = heap_caps_malloc(BODY_CAP, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
   295:    if (!s_body) { ESP_LOGE(TAG, "PSRAM alloc failed for TTS body"); return; }
   296:    s_sem = xSemaphoreCreateBinary();
   297:    if (!s_sem) { ESP_LOGE(TAG, "sem create failed"); return; }
   298:    BaseType_t ok = xTaskCreateWithCaps(tts_task, "tts", 24576, NULL, 3, NULL, MALLOC_CAP_SPIRAM);
   299:    if (ok != pdPASS) ok = xTaskCreate(tts_task, "tts", 16384, NULL, 3, NULL);
   300:    if (ok == pdPASS) ESP_LOGI(TAG, "tts task started (baidu, free tier)");
   301:}
   302:
   303:void voice_tts_speak(const char *text)
   304:{
   305:    if (!s_sem || !text || !text[0]) return;
   306:    if (g_tts.busy) return;
   307:    /* 逐字节拷贝 + UTF-8 合法性校验：残缺字节截断，避免非法序列发给 API。 */
   308:    size_t n = 0;
   309:    while (n + 1 < sizeof(s_text) && text[n]) {
   310:        unsigned char c = (unsigned char)text[n];
   311:        size_t need = (c < 0x80) ? 1 : (c >= 0xC2 && c <= 0xDF) ? 2
   312:                    : (c >= 0xE0 && c <= 0xEF) ? 3
   313:                    : (c >= 0xF0 && c <= 0xF4) ? 4 : 0;
   314:        if (need == 0) break;
   315:        if (n + need >= sizeof(s_text)) break;
   316:        bool valid = true;
   317:        for (size_t k = 1; k < need; k++) {
   318:            unsigned char cc = (unsigned char)text[n + k];
   319:            if (cc == 0 || (cc & 0xC0) != 0x80) { valid = false; break; }
   320:        }
   321:        if (!valid) break;
   322:        for (size_t k = 0; k < need; k++) s_text[n + k] = text[n + k];
   323:        n += need;
   324:    }
   325:    s_text[n] = '\0';
   326:    if (n == 0) return;
   327:    g_tts.busy = true;
   328:    g_tts.error = false;
   329:    set_hint("");
   330:    publish();
   331:    xSemaphoreGive(s_sem);
   332:}
   333:
   334:bool voice_tts_is_busy(void) { return g_tts.busy; }
   335:
   336:void voice_tts_stop(void)
   337:{
   338:    g_tts.busy = false;         /* 让分段循环的 wait 提前退出 */
   339:    audio_player_stop();
   340:}
