{"requestId":"08a7fcdfd4b74be7b649183f9aaf3dee","modelId":"hy4flash-free","modelName":"Hy4 flash","isHelperMessage":false,"traceId":"0b9ae49ef8c2f6599bfe7d2aee6523ee","toolStatus":{"chatcmpl-tool-b1fd6ee0017e27e8":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/sd_card.c","offset":119,"limit":90},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/sd_card.c","content":"   119:/* 挂载尝试顺序（(宽度, 时钟)）：
   120: *   1) 1 线 40MHz   —— 本次试验主档：只留 D0 避开 D1~D3 走线不等长问题，
   121: *                      同时把时钟拉到 SD High Speed 上限（SDMMC_FREQ_HIGHSPEED）。
   122: *                      注意：卡不支持 HS 时驱动会自行降到 20MHz，看日志的「实际」值。
   123: *   2) 1 线 4MHz    —— 40MHz 在 GPIO 矩阵 + 内部上拉下容易 CRC/超时，回退保底
   124: *   3) 4 线 4MHz    —— 4 线降速重试
   125: *   4) 4 线 40MHz   —— 4 线高速（卡座信号好时使用）
   126: */
   127:typedef struct { int width; int freq_khz; } sd_try_t;
   128:static const sd_try_t s_try_list[] = {
   129:    { 1, SD_FREQ_KHZ },     /* 1 线 40MHz */
   130:    { 1, 4000 },            /* 40MHz 不稳时回退 1 线 4MHz */
   131:    { 4, 4000 },            /* 4 线降速重试 */
   132:    { 4, SD_FREQ_KHZ },     /* 4 线 40MHz */
   133:};
   134:
   135:/* 4 线全部失败后的「体检」：用 400kHz（SD 初始化速率，几乎不受走线影响）探一次。
   136: *   成功 → D1~D3 是接通的，只是高速下信号质量差（缺 10k 上拉 / 走线不等长）；
   137: *   失败 → D1/D2/D3(GPIO48/1/2) 大概率没接或接错，只能一直用 1 线。
   138: * 探测成功后立刻卸载，不留在 400kHz（比 1 线 40MHz 慢得多）。 */
   139:static void probe_4bit_lowspeed(void)
   140:{
   141:    if (mount_with_width(4, SDMMC_FREQ_PROBING) == ESP_OK) {
   142:        ESP_LOGW(TAG, "体检: 4 线在 %d kHz 能通 → D1~D3 已接通，是高速信号质量问题；"
   143:                      "给 CMD/D0~D3 各加 10k 上拉、走线尽量等长后可跑 4 线",
   144:                 SDMMC_FREQ_PROBING);
   145:        sd_card_unmount();
   146:    } else {
   147:        ESP_LOGW(TAG, "体检: 4 线在 %d kHz 也不通 → 检查 D1/D2/D3 = GPIO%d/%d/%d 是否接错、虚焊或未接",
   148:                 SDMMC_FREQ_PROBING, SDMMC_PIN_D1, SDMMC_PIN_D2, SDMMC_PIN_D3);
   149:    }
   150:}
   151:
   152:esp_err_t sd_card_mount(bool width4)
   153:{
   154:    if (g_sdcard.mounted) {
   155:        return ESP_OK;
   156:    }
   157:
   158:    sd_log_heap("挂载前");
   159:
   160:    esp_err_t err = ESP_FAIL;
   161:    for (size_t i = 0; i < sizeof(s_try_list) / sizeof(s_try_list[0]); i++) {
   162:        int w = s_try_list[i].width;
   163:        int f = s_try_list[i].freq_khz;
   164:        if (w == 4 && !width4) {
   165:            continue;                       /* 调用方只要 1 线 */
   166:        }
   167:        err = mount_with_retry(w, f);
   168:        if (err == ESP_OK) {
   169:            return ESP_OK;
   170:        }
   171:        if (w == 4 && err == ESP_ERR_INVALID_CRC) {
