{"requestId":"cc58e2bd7b5d48d2997242f40720666c","modelId":"hy4flash-free","modelName":"Hy4 flash","isHelperMessage":false,"traceId":"c6072eae871b4b0368000b0f6f1045ff","toolStatus":{"chatcmpl-tool-9b5f5ec35ba49830":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/lvgl_port.c","offset":90,"limit":130},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/lvgl_port.c","content":"    90:    return false;
    91:}
    92:
    93:/* 实际刷屏次数计数器, ui.c 的 ui_fps_update 每秒读差值作为真实 FPS 显示。
    94: * 替代之前的主循环圈数计数(包括空转, 不准)。 */
    95:uint32_t g_flush_cnt = 0;
    96:
    97:/* flush 回调：LVGL 在 draw buf 里渲染完一块脏区后调用。
    98: * PARTIAL 模式: area 是脏区, px_map 是 LVGL 渲染好的像素(在 s_draw_buf1/2 里)。
    99: * 用 esp_lcd_panel_draw_bitmap 直接把 px_map DMA 到屏幕对应坐标,
   100: * 坐标左闭右开(area 是闭区间, 需 +1)。
   101: * 字节序由 LCD_CAM 硬件 LITTLE_ENDIAN 处理, 无需 CPU 翻转。 */
   102:static void disp_flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
   103:{
   104:    (void)disp;
   105:    if (area->x2 < area->x1 || area->y2 < area->y1) {
   106:        /* 空区域直接通知完成, 避免 DMA 空事务 */
   107:        lv_disp_flush_ready(disp);
   108:        return;
   109:    }
   110:    g_flush_cnt++;   /* 真实刷屏计数, ui_fps_update 读 */
   111:    esp_lcd_panel_draw_bitmap(g_lcd_panel,
   112:                              area->x1, area->y1,
   113:                              area->x2 + 1, area->y2 + 1,
   114:                              px_map);
   115:    /* 不在此处调 flush_ready —— 等 on_color_trans_done 中断里通知 LVGL */
   116:}
   117:
   118:/* 给 LVGL 追加内存池（lv_mem_add_pool() 会把每块加进 LVGL 的 TLSF 分配器）。
   119: * cap 是 heap_caps 能力：MALLOC_CAP_SPIRAM（外部 PSRAM）或 MALLOC_CAP_INTERNAL。
   120: * 按 k_pool_chunks[] 依次挂载（先大块后小块），返回实际挂上的总字节数。
   121: * 注意：LVGL 内部日志(LV_USE_LOG)默认关闭，add_pool 失败时其 printf 也看不到，
   122: * 所以这里每一步都用 ESP_LOG 打点，便于确认卡在哪一步。 */
   123:static size_t lvgl_add_mem_pool(uint32_t cap, const char *cap_name)
   124:{
   125:    const size_t n = sizeof(k_pool_chunks) / sizeof(k_pool_chunks[0]);
   126:    size_t added = 0;
   127:
   128:    for (size_t i = 0; i < n; i++) {
   129:        size_t chunk = k_pool_chunks[i];
   130:        void *p = heap_caps_malloc(chunk, cap);
   131:        if (p == NULL) {
   132:            ESP_LOGW(TAG, "%s: malloc %uKB failed (已挂 %uKB)，继续试小块",
   133:                     cap_name, (unsigned)(chunk / 1024), (unsigned)(added / 1024));
   134:            continue;                            /* 大块挂不上就退到小块 */
   135:        }
   136:        if (lv_mem_add_pool(p, chunk) == NULL) {
   137:            ESP_LOGE(TAG, "%s: lv_mem_add_pool(%uKB @ %p) 失败（单池上限？）",
   138:                     cap_name, (unsigned)(chunk / 1024), p);
   139:            heap_caps_free(p);
   140:            continue;
   141:        }
   142:        added += chunk;
   143:        ESP_LOGI(TAG, "%s: +%uKB pool @ %p (total %uKB)",
   144:                 cap_name, (unsigned)(chunk / 1024), p, (unsigned)(added / 1024));
   145:    }
   146:    ESP_LOGI(TAG, "%s: 共挂 %uKB，单次最大可分配 <= %uKB（TLSF 不能跨池合并）",
   147:             cap_name, (unsigned)(added / 1024), (unsigned)(k_pool_chunks[0] / 1024));
   148:    return added;
