   151:/* 图片解码出来的那一帧改走系统 PSRAM 堆，不再占 LVGL 内存池。
   152: *
   153: * 原因：LVGL 解 PNG 时三块内存是同时活着的（都在 lv_malloc = LVGL 池里）：
   154: *   ① 文件缓冲   = 整个文件大小（lodepng_load_file 整读）
   155: *   ② 解压扫描线 = w*h*4 + h（idat 解压结果）
   156: *   ③ 解出的帧   = w*h*4（lv_draw_buf_create_ex）
   157: * ② 要等 postProcessScanlines 用完才释放，③ 在那之前就分配好了，
   158: * 所以 320x240 的 PNG 峰值 ≈ 文件 + 2*w*h*4 ≈ 777KB，比池总量还大，
   159: * 必然 err=83（memory allocation failed）。
   160: * ③ 走的是这里的 draw_buf 分配回调，把它挪到系统 PSRAM 后，
   161: * 池里只剩 ①+② ≈ 470KB，512KB 的池就装得下了。 */
   162:static void * img_buf_malloc(size_t size, lv_color_format_t color_format)
   163:{
   164:    LV_UNUSED(color_format);
   165:    void * p = heap_caps_malloc(size, MALLOC_CAP_SPIRAM);
   166:    if (p == NULL) {
   167:        /* 万一 PSRAM 也不够，退回 LVGL 池，别比原来更糟 */
   168:        ESP_LOGW(TAG, "图片缓冲 %u 字节 PSRAM 分配失败（空闲 %u，最大块 %u），退回 LVGL 池",
   169:                 (unsigned)size,
   170:                 (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM),
   171:                 (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM));
   172:        return lv_malloc(size);
   173:    }
   174:    ESP_LOGI(TAG, "图片缓冲 %u 字节 → PSRAM @ %p", (unsigned)size, p);
   175:    return p;
   176:}
