    68: * 截成非法序列——那会导致下一轮请求带坏 UTF-8 被 API 以 400 拒绝。 */
    69:static void utf8_strncpy(volatile char *dst, const volatile char *src, size_t cap)
    70:{
    71:    if (cap == 0) return;
    72:    size_t n = 0;
    73:    while (src[n] && n < cap - 1) { dst[n] = src[n]; n++; }  /* 逐字节拷贝（volatile 不能 memcpy） */
    74:    dst[n] = '\0';
    75:    /* 回退到完整字符边界：从末尾往前找最后一个起始字节(非 10xxxxxx)，
    76:     * 若从它到末尾的字节数 >= 它要求的长度，则该字符完整、保留；
    77:     * 否则这个字符被截断了，把起始字节也删掉，继续往前找。 */
    78:    while (n > 0) {
    79:        size_t start = n - 1;
    80:        /* 往前跳过连续的续字节，找到当前字符的起始字节 */
    81:        while (start > 0 && ((unsigned char)dst[start] & 0xC0) == 0x80) start--;
    82:        unsigned char lead = (unsigned char)dst[start];
    83:        size_t need = (lead < 0x80) ? 1 : (lead < 0xE0) ? 2 : (lead < 0xF0) ? 3 : 4;
    84:        if (n - start >= need) break;    /* 末尾字符完整，到此为止 */
    85:        n = start;                       /* 末尾字符不完整，删掉整个字符 */
    86:    }
    87:    dst[n] = '\0';
    88:}
