```c
static void utf8_strncpy(volatile char *dst, const volatile char *src, size_t cap)
{
    if (cap == 0) return;
    size_t n = 0;
    while (n < cap - 1 && src[n]) { dst[n] = src[n]; n++; }
    dst[n] = '\0';
    /* 严格验证末尾字符：找 lead byte，要求到末尾的字节数恰好等于 need，
     * 且中间全是续字节；不满足则删除整个字符，继续往前检查。 */
    while (n > 0) {
        size_t start = n - 1;
        while (start > 0 && ((unsigned char)dst[start] & 0xC0) == 0x80) start--;
        unsigned char lead = (unsigned char)dst[start];
        size_t need = (lead < 0x80) ? 1 : (lead < 0xE0) ? 2 : (lead < 0xF0) ? 3 : 4;
        if (lead >= 0x80 && lead < 0xC0) {  // 孤立续字节，直接删
            n = start; continue;
        }
        if (n - start == need) {
            // 验证中间都是续字节
            bool ok = true;
            for (size_t k = start + 1; k < n; k++) {
                if (((unsigned char)dst[k] & 0xC0) != 0x80) { ok = false; break; }
            }
            if (ok) break;
        }
        n = start;
    }
    dst[n] = '\0';
}
```

