    23:{
    24:    (void)arg;
    25:
    26:    audio_proc_apply_output(buf, len);
    27:
    28:    size_t written = 0;
    29:    esp_err_t err = audio_hw_tx_write(buf, len, &written, portMAX_DELAY);
    30:    if (err != ESP_OK || written != len) {
    31:        ESP_LOGE(TAG, "TX write failed, err=%d, wrote=%d/%d", err, (int)written, (int)len);
    32:        return ESP_FAIL;
    33:    }
    34:
    35:    /* 动态频率调谐（仅 TX，因为 TX 是 Master 产生时钟） */
    36:#if EXAMPLE_DYNAMIC_TUNING_EN
    37:    {
    38:        static uint32_t overflow_cnt  = 0;
    39:        static uint32_t underflow_cnt = 0;
    40:        static uint32_t normal_cnt    = 0;
    41:        i2s_tuning_info_t info = { 0 };
    42:        if (audio_hw_tx_rate_tune(NULL, &info) != ESP_OK) {
    43:            return ESP_OK;
    44:        }
    45:
    46:        if (info.water_mark >= 90) {
    47:            if (++overflow_cnt >= 5000) {
    48:                uint32_t init_mclk = audio_hw_tx_get_init_mclk_hz();
    49:                i2s_tuning_config_t tune_cfg = EXAMPLE_I2S_DEFAULT_TUNING_CFG(init_mclk, true);
    50:                /* 重配 TX 时钟：disable → tune → enable
    51:                 * 注：在回调里做通道重配会暂时阻塞下一帧，正常 1~3ms 可接受 */
    52:                audio_hw_tx_rate_tune(&tune_cfg, &info);
    53:                ESP_LOGI(TAG, "overflow: MCLK=%"PRIu32"Hz delta=%"PRId32"Hz wm=%"PRIu32,
    54:                         info.curr_mclk_hz, info.delta_mclk_hz, info.water_mark);
    55:                overflow_cnt = 0;
    56:                normal_cnt   = 0;
    57:            }
    58:        } else if (info.water_mark < 10) {
    59:            if (++underflow_cnt >= 5000) {
    60:                uint32_t init_mclk = audio_hw_tx_get_init_mclk_hz();
    61:                i2s_tuning_config_t tune_cfg = EXAMPLE_I2S_DEFAULT_TUNING_CFG(init_mclk, false);
    62:                audio_hw_tx_rate_tune(&tune_cfg, &info);
    63:                ESP_LOGI(TAG, "underflow: MCLK=%"PRIu32"Hz delta=%"PRId32"Hz wm=%"PRIu32,
    64:                         info.curr_mclk_hz, info.delta_mclk_hz, info.water_mark);
    65:                underflow_cnt = 0;
    66:                normal_cnt    = 0;
    67:            }
    68:        } else {
    69:            normal_cnt = (normal_cnt + 1) % 1000;
    70:            if (normal_cnt == 0) {
    71:                overflow_cnt  = 0;
    72:                underflow_cnt = 0;
    73:            }
    74:        }
    75:    }
    76:#endif  /* EXAMPLE_DYNAMIC_TUNING_EN */
    77:
    78:    return ESP_OK;
    79:}
