    if (on && s_usb_msc_pending == 0) {
        s_usb_msc_pending = 1;
        if (g_usb_msc_label) lv_label_set_text(g_usb_msc_label, "正在切换U盘模式...");
    } else if (!on && s_usb_msc_pending == 0) {
