   182:/* ---------------- UAC 回调：麦克风（I2S1 → USB） ----------------
   183: * I2S 读 32bit stereo（每帧 8 字节），取左声道高 16 位，输出 16bit mono。 */
   184:static esp_err_t uac_input_cb(uint8_t *buf, size_t len, size_t *bytes_read, void *ctx)
   185:{
   186:    (void)ctx;
   187:    static uint8_t raw[2048];      /* 静态缓冲 */
   188:    size_t want_frames = len / 2;  /* 要输出的 16bit mono 采样数 */
   189:    size_t raw_bytes = want_frames * 8;
   190:    if (raw_bytes > sizeof(raw)) raw_bytes = sizeof(raw);
   191:    if (raw_bytes == 0) { if (bytes_read) *bytes_read = 0; return ESP_OK; }
   192:
   193:    size_t got = 0;
   194:    esp_err_t err = i2s_channel_read(s_rx, raw, raw_bytes, &got, 1000);
   195:    if (err != ESP_OK) {
   196:        if (bytes_read) *bytes_read = 0;
   197:        return ESP_OK;
   198:    }
   199:    /* 每 8 字节 = 左32 + 右32（小端），取左声道高 16 位 */
   200:    size_t in_frames = got / 8;
   201:    size_t out_frames = in_frames < want_frames ? in_frames : want_frames;
   202:    for (size_t i = 0; i < out_frames; i++) {
   203:        int32_t sample;
   204:        memcpy(&sample, raw + i * 8, 4);      /* 左声道 32bit */
   205:        int16_t s16 = (int16_t)(sample >> 16); /* 取高 16 位 */
   206:        memcpy(buf + i * 2, &s16, 2);
   207:    }
   208:    if (bytes_read) *bytes_read = out_frames * 2;
   209:    return ESP_OK;","totalLineCount":272,"hasMore":true,"hint":""}}}}}

