{"role":"assistant","content":[{"type":"text","text":"现在改 `uac_output_cb` 应用增益："},{"type":"tool-call","toolCallId":"chatcmpl-tool-bd3c0495a2bd89c4","toolName":"replace_in_file","args":{"filePath":"c:/esp32/LCD/main/usb_uac.c","old_str":"/* ---------------- UAC 回调：喇叭（USB → I2S0） ----------------
 * USB 送来 16bit mono（每帧 2 字节），复制到左右声道变 16bit stereo 写 I2S。 */
static esp_err_t uac_output_cb(uint8_t *buf, size_t len, void *ctx)
{
    (void)ctx;
    static int16_t stereo[1024];   /* 静态缓冲，避免回调里 malloc */
    size_t frames = len / 2;       /* 16bit mono 采样数 */
    if (frames == 0 || frames > 1024) return ESP_OK;

    for (size_t i = 0; i < frames; i++) {
        int16_t s;
        memcpy(&s, buf + i * 2, 2);
        stereo[i * 2] = s;         /* 左 */
        stereo[i * 2 + 1] = s;     /* 右 */
    }","new_str":"/* ---------------- UAC 回调：喇叭（USB → I2S0） ----------------
 * USB 送来 16bit mono（每帧 2 字节），复制到左右声道变 16bit stereo 写 I2S。
 * 同时应用数字音量（平方律 Q15）和静音——MAX98357A 无硬件音量，只能改 PCM。 */
static esp_err_t uac_output_cb(uint8_t *buf, size_t len, void *ctx)
{
    (void)ctx;
    static int16_t stereo[1024];   /* 静态缓冲，避免回调里 malloc */
    size_t frames = len / 2;       /* 16bit mono 采样数 */
    if (frames == 0 || frames > 1024) return ESP_OK;

    bool muted = s_muted;
    int32_t gain = s_gain_q15;

    for (size_t i = 0; i < frames; i++) {
        int16_t s;
        memcpy(&s, buf + i * 2, 2);
        if (muted) {
            s = 0;
        } else if (gain != 32768) {
            int32_t v = ((int32_t)s * gain) >> 15;
            if (v >  32767) v =  32767;
            if (v < -32768) v = -32768;
            s = (int16_t)v;
        }
        stereo[i * 2] = s;         /* 左 */
        stereo[i * 2 + 1] = s;     /* 右 */
    }","explanation":"output_cb 应用数字音量和静音。"}}]}

