{"requestId":"ce2a944430e14a4cacbe62a9d1ee4946","modelId":"hy4flash-free","modelName":"Hy4 flash","isHelperMessage":false,"traceId":"7eeaa542f60db5bbd234e65b3ab9fcfc","toolStatus":{"chatcmpl-tool-9a9635e7a6ff5a58":{"ready":true,"status":"executed","args":{"filePath":"c:/esp32/LCD/main/usb_cdc.c","offset":60,"limit":50},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"c:/esp32/LCD/main/usb_cdc.c","content":"    60:static bool              s_attached = false;
    61:static tinyusb_config_t  s_tusb_cfg = {0};   /* 异步任务只存指针，必须 static */
    62:static TaskHandle_t      s_task = NULL;
    63:
    64:static void cdc_event_cb(tinyusb_event_t *event, void *arg)
    65:{
    66:    (void)arg;
    67:    if (event->id == TINYUSB_EVENT_ATTACHED) {
    68:        s_attached = true;
    69:        ESP_LOGI(TAG, "USB 已连接到电脑（CDC 调试口）");
    70:    } else if (event->id == TINYUSB_EVENT_DETACHED) {
    71:        s_attached = false;
    72:    }
    73:}
    74:
    75:/* ---------------- CDC 任务：收命令回显 + 周期状态上报 ---------------- */
    76:static void cdc_task(void *arg)
    77:{
    78:    (void)arg;
    79:    uint8_t rx[128];
    80:    char    line[64];
    81:    TickType_t last_report = xTaskGetTickCount();
    82:
    83:    while (s_active) {
    84:        /* 1. 读取电脑发来的数据，原样回显 */
    85:        size_t got = 0;
    86:        if (tinyusb_cdcacm_read(TINYUSB_CDC_ACM_0, rx, sizeof(rx), &got) == ESP_OK && got > 0) {
    87:            tinyusb_cdcacm_write_queue(TINYUSB_CDC_ACM_0, rx, got);
    88:            tinyusb_cdcacm_write_flush(TINYUSB_CDC_ACM_0, 0);
    89:        }
    90:
    91:        /* 2. 每 5 秒上报一次设备状态（仅连接后） */
    92:        if (s_attached && (xTaskGetTickCount() - last_report) >= pdMS_TO_TICKS(5000)) {
    93:            last_report = xTaskGetTickCount();
