    62:static tinyusb_config_t  s_tusb_cfg = {0};   /* 异步任务只存指针，必须 static */
    63:static TaskHandle_t      s_task = NULL;
    64:
    65:/* ---------------- ESP_LOG 日志镜像到 CDC ----------------
    66: * 钩子在任何任务上下文被调用，绝不能在此直接操作 CDC（会阻塞/重入）。
    67: * 做法：格式化到静态缓冲，由 cdc_task 定期刷出；同时仍写原 UART console。 */
    68:#define CDC_LOG_BUF_SIZE  2048
    69:static char          s_log_buf[CDC_LOG_BUF_SIZE];
    70:static size_t        s_log_len = 0;
    71:static portMUX_TYPE  s_log_mux = portMUX_INITIALIZER_UNLOCKED;
    72:static vprintf_like_t s_old_vprintf = NULL;   /* 保存原 UART 输出函数，stop 时恢复 */
    73:static bool          s_log_hooked = false;
    74:
    75:static int cdc_log_vprintf(const char *fmt, va_list args)
    76:{
    77:    /* 先格式化一份到缓冲给 CDC（va_list 只能用一次，另一份给原 UART） */
    78:    char tmp[256];
    79:    va_list args2;
    80:    va_copy(args2, args);
    81:    int len = vsnprintf(tmp, sizeof(tmp), fmt, args);
