     7:/* DESCRIPTION:
     8: * This example contains code to make ESP32-S2/S3 as a USB network Device.
     9: */
    10:#include <stdio.h>
    11:#include "esp_log.h"
    12:#include "esp_netif.h"
    13:#include "esp_event.h"
    14:#include "tinyusb.h"
    15:#include "tinyusb_default_config.h"
    16:#include "tinyusb_net.h"
    17:#include "wired_iface.h"
    18:#include "dhcpserver/dhcpserver_options.h"
    19:#include "lwip/esp_netif_net_stack.h"
    20:#include "esp_mac.h"
    21:
    22:static const char *TAG = "example_wired_tusb_ncm";
    23:static esp_netif_t *s_netif = NULL;
    24:
    25:/**
    26: *  In this scenario of WiFi station to Ethernet bridge mode, we have this configuration
    27: *
    28: *   (ISP) router        ESP32               PC
    29: *      [ AP ] <->   [ sta -- USB ] <->  [ USB-NCM device acting as eth-NIC ]
    30: *
    31: *  From the PC's NIC perspective the L2 forwarding should be transparent and resemble this configuration:
    32: *
    33: *   (ISP) router                           PC
    34: *      [ AP ]       <---------->       [ virtual wifi-NIC ]
    35: *
    36: *  In order for the ESP32 to act as L2 bridge it needs to accept the frames for the NCM device,
    37: *  which we have fully under control, we can modify it's MAC address, as well as the WiFi station
    38: *  MAC address, which need to be the same so the AP would see one device (virtual eth-NIC).
    39: *  No need to modify the ethernet frames here, as we can set the station's MAC to the USB NCM device.
    40: */
    41:void mac_spoof(mac_spoof_direction_t direction, uint8_t *buffer, uint16_t len, uint8_t own_mac[6])
    42:{
    43:
    44:}
    45:
    46:esp_err_t wired_bridge_init(wired_rx_cb_t rx_cb, wired_free_cb_t free_cb)
    47:{
    48:    const tinyusb_config_t tusb_cfg = TINYUSB_DEFAULT_CONFIG();
    49:    ESP_ERROR_CHECK(tinyusb_driver_install(&tusb_cfg));
    50:
    51:    tinyusb_net_config_t net_config = {
    52:        .on_recv_callback = rx_cb,
    53:        .free_tx_buffer = free_cb,
    54:    };
    55:
    56:    esp_read_mac(net_config.mac_addr, ESP_MAC_WIFI_STA);
    57:
    58:    esp_err_t ret = tinyusb_net_init(&net_config);
    59:    if (ret != ESP_OK) {
    60:        ESP_LOGE(TAG, "USB net init but not connect wifi");
    61:        return ret;
    62:    }
    63:    return ESP_OK;
    64:}
    65:
    66:
    67:esp_err_t wired_send(void *buffer, uint16_t len, void *buff_free_arg)
    68:{
    69:    return tinyusb_net_send_sync(buffer, len, buff_free_arg, pdMS_TO_TICKS(100));
    70:}
    71:
    72:static void l2_free(void *h, void *buffer)
    73:{
    74:    free(buffer);
    75:}
    76:
    77:static esp_err_t netif_transmit (void *h, void *buffer, size_t len)
    78:{
    79:    if (wired_send(buffer, len, NULL) != ESP_OK) {
    80:        ESP_LOGE(TAG, "Failed to send buffer to USB!");
    81:    }
    82:    return ESP_OK;
    83:}
    84:
    85:static esp_err_t netif_recv_callback(void *buffer, uint16_t len, void *ctx)
    86:{
    87:    if (s_netif) {
    88:        void *buf_copy = malloc(len);
    89:        if (!buf_copy) {
    90:            return ESP_ERR_NO_MEM;
    91:        }
    92:        memcpy(buf_copy, buffer, len);
    93:        return esp_netif_receive(s_netif, buf_copy, len, NULL);
    94:    }
    95:    return ESP_OK;
    96:}
    97:
    98:/**
    99: *  In this scenario of configuring WiFi, we setup USB-Ethernet to create a virtual network and run DHCP server,
   100: *  so it could assign an IP address to the PC
   101: *
   102: *           ESP32               PC
   103: *      |    lwip MAC=...01   |                        eth NIC MAC=...02
   104: *      | <DHCP server>   usb | <->  [ USB-NCM device acting as eth-NIC ]
   105: *      | <HTTP server>       |
   106: *      | (wifi-provisioning) |
   107: *
   108: *  From the PC's NIC perspective the board acts as a separate network with it's own IP and MAC address,
   109: *  but the virtual ethernet NIC has also it's own IP and MAC address (configured via tinyusb_net_init()).
   110: *  That's why we need to create the virtual network with *different* MAC address.
   111: *  Here, we use two different OUI range MAC addresses.
   112: */
   113:esp_err_t wired_netif_init(void)
   114:{
   115:    const tinyusb_config_t tusb_cfg = TINYUSB_DEFAULT_CONFIG();
   116:    ESP_ERROR_CHECK(tinyusb_driver_install(&tusb_cfg));
   117:
   118:    const tinyusb_net_config_t net_config = {
   119:        // locally administrated address for the ncm device as it's going to be used internally
   120:        // for configuration only
   121:        .mac_addr = {0x02, 0x02, 0x11, 0x22, 0x33, 0x01},
   122:        .on_recv_callback = netif_recv_callback,
   123:    };
   124:
   125:    esp_err_t ret = tinyusb_net_init(&net_config);
   126:    if (ret != ESP_OK) {
   127:        ESP_LOGE(TAG, "Cannot initialize USB Net device");
   128:        return ret;
   129:    }
   130:
   131:    // with OUI range MAC to create a virtual netif running http server
   132:    // this needs to be different to usb_interface_mac (==client)
   133:    uint8_t lwip_addr[6] =  {0x02, 0x02, 0x11, 0x22, 0x33, 0x02};
   134:
   135:    // Definition of
   136:    // 1) Derive the base config (very similar to IDF's default WiFi AP with DHCP server)
   137:    esp_netif_inherent_config_t base_cfg =  {
   138:        .flags = ESP_NETIF_DHCP_SERVER | ESP_NETIF_FLAG_AUTOUP, // Run DHCP server; set the netif "ip" immediately
   139:        .ip_info = &_g_esp_netif_soft_ap_ip,                    // Use the same IP ranges as IDF's soft AP
   140:        .if_key = "wired",                                      // Set mame, key, priority
   141:        .if_desc = "usb ncm config device",
   142:        .route_prio = 10
   143:    };
   144:    // 2) Use static config for driver's config pointing only to static transmit and free functions
   145:    esp_netif_driver_ifconfig_t driver_cfg = {
   146:        .handle = (void *)1,                // not using an instance, USB-NCM is a static singleton (must be != NULL)
   147:        .transmit = netif_transmit,         // point to static Tx function
   148:        .driver_free_rx_buffer = l2_free    // point to Free Rx buffer function
   149:    };
   150:
   151:    // 3) USB-NCM is an Ethernet netif from lwip perspective, we already have IO definitions for that:
   152:    struct esp_netif_netstack_config lwip_netif_config = {
   153:        .lwip = {
   154:            .init_fn = ethernetif_init,
   155:            .input_fn = ethernetif_input
   156:        }
   157:    };
   158:
   159:    // Config the esp-netif with:
   160:    //   1) inherent config (behavioural settings of an interface)
   161:    //   2) driver's config (connection to IO functions -- usb)
   162:    //   3) stack config (using lwip IO functions -- derive from eth)
   163:    esp_netif_config_t cfg = {
   164:        .base = &base_cfg,
   165:        .driver = &driver_cfg,
   166:        .stack = &lwip_netif_config
   167:    };
   168:
   169:    s_netif = esp_netif_new(&cfg);
   170:    if (s_netif == NULL) {
   171:        return ESP_FAIL;
   172:    }
   173:    esp_netif_set_mac(s_netif, lwip_addr);
   174:
   175:    // set the minimum lease time
   176:    uint32_t  lease_opt = 1;
   177:    esp_netif_dhcps_option(s_netif, ESP_NETIF_OP_SET, IP_ADDRESS_LEASE_TIME, &lease_opt, sizeof(lease_opt));
   178:
   179:    // start the interface manually (as the driver has been started already)
   180:    esp_netif_action_start(s_netif, 0, 0, 0);
   181:    return ESP_OK;
   182:}
   183:","totalLineCount":183,"hasMore":false,"hint":""}}}}}

