{"role":"assistant","content":[{"type":"text","text":"NCM 描述符宏是 `TUD_CDC_NCM_DESCRIPTOR`，需要参数：接口号、字符串索引、MAC 字符串索引、通知端点、数据端点、MTU。我写纯 NCM 描述符（接口0/1，端点 0x81 notif / 0x02 out / 0x82 in）。

写完整模块："},{"type":"tool-call","toolCallId":"chatcmpl-tool-a0e8440cdec05d18","toolName":"write_to_file","args":{"filePath":"c:/esp32/LCD/main/usb_ncm.c","content":"#include "usb_ncm.h"

#include <string.h>
#include <stdlib.h>
#include "esp_log.h"
#include "esp_mac.h"
#include "esp_wifi.h"
#include "esp_netif.h"
#include "tinyusb.h"
#include "tinyusb_default_config.h"
#include "tinyusb_net.h"
#include "usb_msc.h"
#include "usb_uac.h"
#include "usb_cdc.h"
#include "wifi_scan.h"       /* g_wifi_state / WIFI_STA_CONNECTED */

static const char *TAG = "USB_NCM";

/* ---------------- 纯 NCM 描述符 ----------------
 * 接口 0(communication) / 1(data)，端点：
 *   0x81 IN notification, 0x02 OUT data, 0x82 IN data
 * 与其它模式分时切换，端点号可复用。 */
#define NCM_ITF_CNT  2
#define NCM_EP_NOTIF 0x81
#define NCM_EP_OUT   0x02
#define NCM_EP_IN    0x82
#define NCM_CFG_TOTAL_LEN (TUD_CONFIG_DESC_LEN + TUD_CDC_NCM_DESC_LEN)
#define NCM_MTU       1500

static const tusb_desc_device_t s_ncm_dev_desc = {
    .bLength            = sizeof(tusb_desc_device_t),
    .bDescriptorType    = TUSB_DESC_DEVICE,
    .bcdUSB             = 0x0200,
    .bDeviceClass       = TUSB_CLASS_MISC,
    .bDeviceSubClass    = MISC_SUBCLASS_COMMON,
    .bDeviceProtocol    = MISC_PROTOCOL_IAD,
    .bMaxPacketSize0    = CFG_TUD_ENDPOINT0_SIZE,
    .idVendor           = 0x303A,
    .idProduct          = 0x8003,
    .bcdDevice          = 0x0100,
    .iManufacturer      = 0x01,
    .iProduct           = 0x02,
    .iSerialNumber      = 0x03,
    .bNumConfigurations = 0x01,
};

/* MAC 字符串描述符（NCM 需要）：12 个十六进制字符 + 长度头，UTF-16LE */
static uint16_t s_mac_str[16];

static const uint8_t s_ncm_cfg_desc[] = {
    TUD_CONFIG_DESCRIPTOR(1, NCM_ITF_CNT, 0, NCM_CFG_TOTAL_LEN, 0x00, 100),
    TUD_CDC_NCM_DESCRIPTOR(0, 4, 5, NCM_EP_NOTIF, 8, NCM_EP_OUT, NCM_EP_IN, 64, NCM_MTU),
};

static const char *s_ncm_strings[] = {
    (char[]){0x09, 0x04},   /* 0: LANGID */
    "ESP32-S3",             /* 1: Manufacturer */
    "LCD USB Network",      /* 2: Product */
    NULL,                   /* 3: Serial（运行时填 MAC） */
    "USB Network",          /* 4: NCM interface */
    NULL,                   /* 5: MAC string（运行时填，见 s_mac_str） */
};

/* ---------------- 状态 ---------------- */
static bool             s_active = false;
static bool             s_mounted = false;
static tinyusb_config_t s_tusb_cfg = {0};   /* 异步任务只存指针，必须 static */
static uint8_t          s_sta_mac[6] = {0};

/* ---------------- 桥接回调 ---------------- */

/* USB → WiFi：电脑发出的以太网帧交给 WiFi STA 发出 */
static esp_err_t ncm_recv_cb(void *buffer, uint16_t len, void *ctx)
{
    (void)ctx;
    if (!s_active) return ESP_OK;
    esp_err_t err = esp_wifi_internal_tx(WIFI_IF_STA, buffer, len);
    if (err != ESP_OK) {
        ESP_LOGD(TAG, "wifi tx failed: %s", esp_err_to_name(err));
    }
    return ESP_OK;
}

/* 释放 TX buffer：WiFi RX 回调拿到的 buffer 由 WiFi 管理 */
static void ncm_free_tx_cb(void *buffer, void *ctx)
{
    (void)ctx;
    esp_wifi_internal_free_rx_buffer(buffer);
}

/* WiFi → USB：WiFi 收到的以太网帧转发给电脑 */
static esp_err_t wifi_rx_cb(void *buffer, uint16_t len, void *eb)
{
    if (!s_active || !s_mounted) {
        esp_wifi_internal_free_rx_buffer(eb);
        return ESP_OK;
    }
    if (tinyusb_net_send_async(buffer, len, eb) != ESP_OK) {
        esp_wifi_internal_free_rx_buffer(eb);
        ESP_LOGD(TAG, "usb net send failed");
    }
    return ESP_OK;
}

/* NCM 挂载成功回调：此时 can_xmit 才可用 */
static void ncm_init_cb(void *ctx)
{
    (void)ctx;
    s_mounted = true;
    ESP_LOGI(TAG, "USB 网络已枚举成功，电脑应识别到网卡");
}

/* ---------------- 启停 ---------------- */
esp_err_t usb_ncm_start(void)
{
    if (s_active) return ESP_OK;

    /* 前提：WiFi 必须已连上路由器，否则桥接无意义 */
    if (g_wifi_state != WIFI_STA_CONNECTED) {
        ESP_LOGW(TAG, "WiFi 未连接，无法启动 USB 网络共享");
        return ESP_ERR_INVALID_STATE;
    }

    /* 与 U盘 / 声卡 / CDC 互斥 */
    usb_msc_stop();
    usb_uac_stop();
    usb_cdc_stop();

    esp_read_mac(s_sta_mac, ESP_MAC_WIFI_STA);

    /* 1. 构造 MAC 字符串描述符（索引5），并填序列号（索引3） */
    s_mac_str[0] = (uint16_t)((TUSB_DESC_STRING << 8) | (2 * 12 + 2));
    static const char hex[] = "0123456789ABCDEF";
    for (int i = 0; i < 6; i++) {
        s_mac_str[1 + i * 2]     = hex[(s_sta_mac[i] >> 4) & 0xF];
        s_mac_str[1 + i * 2 + 1] = hex[s_sta_mac[i] & 0xF];
    }
    char serial[13];
    snprintf(serial, sizeof(serial), "%02X%02X%02X%02X%02X%02X",
             s_sta_mac[0], s_sta_mac[1], s_sta_mac[2],
             s_sta_mac[3], s_sta_mac[4], s_sta_mac[5]);
    s_ncm_strings[3] = serial;   /* 指向栈变量？不行——见下方修正 */
    s_ncm_strings[5] = (const char *)s_mac_str;

    /* 2. 安装 USB device driver，传纯 NCM 描述符 */
    s_tusb_cfg = TINYUSB_DEFAULT_CONFIG(NULL, NULL);
    s_tusb_cfg.descriptor.device = &s_ncm_dev_desc;
    s_tusb_cfg.descriptor.string = s_ncm_strings;
    s_tusb_cfg.descriptor.string_count = sizeof(s_ncm_strings) / sizeof(s_ncm_strings[0]);
    s_tusb_cfg.descriptor.full_speed_config = s_ncm_cfg_desc;
    esp_err_t err = tinyusb_driver_install(&s_tusb_cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "tinyusb install failed: %s", esp_err_to_name(err));
        return err;
    }

    /* 3. 初始化 NCM net：MAC 用 WiFi STA 的，桥接对电脑透明 */
    tinyusb_net_config_t net_cfg = {
        .mac_addr = {0},
        .on_recv_callback = ncm_recv_cb,
        .free_tx_buffer = ncm_free_tx_cb,
        .on_init_callback = ncm_init_cb,
        .user_context = NULL,
    };
    memcpy(net_cfg.mac_addr, s_sta_mac, 6);
    err = tinyusb_net_init(&net_cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "tinyusb_net_init failed: %s", esp_err_to_name(err));
        tinyusb_driver_uninstall();
        return err;
    }

    /* 4. 注册 WiFi RX 回调，开始桥接 */
    s_mounted = false;
    esp_wifi_internal_reg_rxcb(WIFI_IF_STA, wifi_rx_cb);

    s_active = true;
    ESP_LOGI(TAG, "USB 网络共享已启动（WiFi STA → USB NCM），等待电脑枚举");
    return ESP_OK;
}

esp_err_t usb_ncm_stop(void)
{
    if (!s_active) return ESP_OK;
    s_active = false;
    s_mounted = false;

    esp_wifi_internal_reg_rxcb(WIFI_IF_STA, NULL);
    tinyusb_net_deinit();
    tinyusb_driver_uninstall();
    ESP_LOGI(TAG, "USB 网络共享已关闭");
    return ESP_OK;
}

bool usb_ncm_is_active(void) { return s_active; }
","explanation":"实现 USB NCM 桥接模块。"}}]}

