    (char[]){0x09, 0x04},   /* 0: LANGID (English) */
    "ESP32-S3",             /* 1: Manufacturer */
    "LCD U盘",             /* 2: Product */
    NULL,                   /* 3: Serial（运行时由 eFuse MAC 填充） */
    "Mass Storage",         /* 4: MSC/CDC 接口（占位，兼容两种 STRID 布局） */
    "Mass Storage",         /* 5: MSC 接口 */
