static void ncm_init_cb(void *ctx)
{
    (void)ctx;
    s_mounted = true;
    ESP_LOGI(TAG, "USB 网络已枚举成功，电脑应识别到网卡");
}","new_str":"/* 新版 TinyUSB 的 NCM class 不再调用 tud_network_init_cb()，on_init_callback
 * 永远不会触发；改为周期查询 tud_mounted() 检测真实枚举状态。 */
static void ncm_monitor_task(void *arg)
{
    (void)arg;
    bool was_mounted = false;
    while (s_active) {
        bool mounted = tud_mounted();
        if (mounted != was_mounted) {
            was_mounted = mounted;
            s_mounted = mounted;
            if (mounted) ESP_LOGI(TAG, "USB 网络已枚举成功，电脑应识别到网卡");
            else        ESP_LOGW(TAG, "USB 枚举断开，等待电脑重新连接");
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
    s_monitor_task = NULL;
    vTaskDelete(NULL);
}","explanation":"改用 tud_mounted 轮询检测枚举。"}}]}

