   161:    s_tusb_cfg.descriptor.device = &s_ncm_dev_desc;
   162:    s_tusb_cfg.descriptor.string = s_ncm_strings;
   163:    s_tusb_cfg.descriptor.string_count = sizeof(s_ncm_strings) / sizeof(s_ncm_strings[0]);
   164:    s_tusb_cfg.descriptor.full_speed_config = s_ncm_cfg_desc;
   165:    esp_err_t err = tinyusb_driver_install(&s_tusb_cfg);
