   172:    tinyusb_net_config_t net_cfg = {
   173:        .mac_addr = {0},
   174:        .on_recv_callback = ncm_recv_cb,
   175:        .free_tx_buffer = ncm_free_tx_cb,
   176:        .on_init_callback = ncm_init_cb,
   177:        .user_context = NULL,
   178:    };
   179:    memcpy(net_cfg.mac_addr, s_sta_mac, 6);
   180:    err = tinyusb_net_init(&net_cfg);
   181:    if (err != ESP_OK) {
   182:        ESP_LOGE(TAG, "tinyusb_net_init failed: %s", esp_err_to_name(err));
   183:        tinyusb_driver_uninstall();
   184:        return err;
   185:    }
