   187:    /* 4. 注册 WiFi RX 回调，开始桥接 */
   188:    s_mounted = false;
   189:    esp_wifi_internal_reg_rxcb(WIFI_IF_STA, wifi_rx_cb);
   190:
   191:    s_active = true;
   192:    ESP_LOGI(TAG, "USB 网络共享已启动（WiFi STA → USB NCM），等待电脑枚举");","totalLineCount":210,"hasMore":true,"hint":""}}}}}

