};

static const char *s_ncm_strings[] = {
    (char[]){0x09, 0x04},   /* 0: LANGID */
    "ESP32-S3",             /* 1: Manufacturer */
    "LCD USB Network",      /* 2: Product */
    NULL,                   /* 3: Serial（运行时填 MAC） */
    "USB Network",          /* 4: NCM interface */
    NULL,                   /* 5: 占位（对齐 STRID_MSC） */
    NULL,                   /* 6: 占位（对齐 STRID_NET_INTERFACE） */
    NULL,                   /* 7: MAC string — 由 tinyusb_net_init() 填 ASCII MAC */
};

/* ---------------- 状态 ---------------- */
static bool             s_active = false;
static bool             s_mounted = false;
static tinyusb_config_t s_tusb_cfg = {0};   /* 异步任务只存指针，必须 static */
static uint8_t          s_sta_mac[6] = {0};
static TaskHandle_t     s_monitor_task = NULL;

/* ---------------- 桥接回调 ---------------- */

/* USB → WiFi：电脑发出的以太网帧交给 WiFi STA 发出 */
static esp_err_t ncm_recv_cb(void *buffer, uint16_t len, void *ctx)
{
    (void)ctx;
    if (!s_active) return ESP_OK;
    esp_err_t err = esp_wifi_internal_tx(WIFI_IF_STA, buffer, len);
    if (err != ESP_OK) {
        ESP_LOGD(TAG, "wifi tx failed: %s", esp_err_to_name(err));
    }
    return ESP_OK;
}

/* 释放 TX buffer：现在 USB 发的是 malloc 副本，直接 free */
static void ncm_free_tx_cb(void *buffer, void *ctx)
{
    (void)ctx;
    free(buffer);
}

/* WiFi → USB + 本机：WiFi 收到的包"双发"。
 * 关键：注册 internal rxcb 会覆盖 esp-netif 的默认接收函数，如果只转 USB，
 * 设备自己的 lwIP 收不到任何包（DNS 响应丢失 → getaddrinfo EAI_AGAIN）。
 * 做法：复制一份给 USB，原 buffer 交给 esp_netif_receive() 让本机协议栈处理。 */
static esp_netif_t *s_sta_netif = NULL;   /* WiFi STA netif（start 时获取） */

static esp_err_t wifi_rx_cb(void *buffer, uint16_t len, void *eb)
{
    /* 1. 复制一份转发给电脑（USB） */
    if (s_active && s_mounted) {
        uint8_t *copy = (uint8_t *)malloc(len);
        if (copy) {
            memcpy(copy, buffer, len);
            if (tinyusb_net_send_async(copy, len, copy) != ESP_OK) free(copy);
        }
    }
    /* 2. 原包交给本机 lwIP（esp_netif_receive 内部会释放 eb） */
    if (s_sta_netif) {
        return esp_netif_receive(s_sta_netif, buffer, len, eb);
    }
    /* 兜底：拿不到 netif 才退回原来的处理方式（正常不会发生） */
    esp_wifi_internal_free_rx_buffer(eb);
    return ESP_OK;
}

/* 只转本机的 rxcb：NCM 关闭后恢复设备网络用（不能设 NULL，否则永久断网） */
static esp_err_t wifi_rx_lwip_only_cb(void *buffer, uint16_t len, void *eb)
{
    if (s_sta_netif) {
        return esp_netif_receive(s_sta_netif, buffer, len, eb);
    }
    esp_wifi_internal_free_rx_buffer(eb);
    return ESP_OK;
}

/* 新版 TinyUSB 的 NCM class 不再调用 tud_network_init_cb()，on_init_callback
 * 永远不会触发；改为周期查询 tud_mounted() 检测真实枚举状态。 */
static void ncm_monitor_task(void *arg)
{
    (void)arg;
    bool was_mounted = false;
    while (s_active) {
        bool mounted = tud_mounted();
        if (mounted != was_mounted) {
            was_mounted = mounted;
            s_mounted = mounted;
            if (mounted) ESP_LOGI(TAG, "USB 网络已枚举成功，电脑应识别到网卡");
            else        ESP_LOGW(TAG, "USB 枚举断开，等待电脑重新连接");
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
    s_monitor_task = NULL;
    vTaskDelete(NULL);
}

static void ncm_event_cb(tinyusb_event_t *event, void *arg)
{
    (void)arg;
    if (event->id == TINYUSB_EVENT_ATTACHED) {
        ESP_LOGI(TAG, "USB 线已插入，等待电脑枚举");
    } else if (event->id == TINYUSB_EVENT_DETACHED) {
        ESP_LOGI(TAG, "USB 线已拔出");
    }
}

/* ---------------- 启停 ---------------- */
esp_err_t usb_ncm_start(void)
{
    if (s_active) return ESP_OK;

    /* 前提：WiFi 必须已连上路由器，否则桥接无意义 */
    if (g_wifi_state != WIFI_STA_CONNECTED) {
        ESP_LOGW(TAG, "WiFi 未连接，无法启动 USB 网络共享");
        return ESP_ERR_INVALID_STATE;
    }

    /* 与 U盘 / 声卡 / CDC 互斥 */
    usb_msc_stop();
    usb_uac_stop();
    usb_cdc_stop();

    /* 获取 WiFi STA netif：双发时要把原包交给它，设备自己才能上网 */
    s_sta_netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
    if (s_sta_netif == NULL) {
        ESP_LOGE(TAG, "拿不到 WiFi STA netif，无法启动桥接");
        return ESP_ERR_INVALID_STATE;
    }

    esp_read_mac(s_sta_mac, ESP_MAC_WIFI_STA);

    /* 1. 填序列号字符串（索引3）。MAC 字符串（索引7）由 tinyusb_net_init()
     *    内部用 ASCII 格式写入，不要自己构造 UTF-16LE 二进制，否则主机读到的
     *    MAC 字符串是空的/乱码，NCM 枚举会卡住。 */
    static char serial[13];      /* static：字符串指针在 driver 生命周期内必须有效 */
    snprintf(serial, sizeof(serial), "%02X%02X%02X%02X%02X%02X",
             s_sta_mac[0], s_sta_mac[1], s_sta_mac[2],
             s_sta_mac[3], s_sta_mac[4], s_sta_mac[5]);
    s_ncm_strings[3] = serial;

    /* 2. 安装 USB device driver，传纯 NCM 描述符 */
    s_tusb_cfg = TINYUSB_DEFAULT_CONFIG(ncm_event_cb, NULL);
    s_tusb_cfg.descriptor.device = &s_ncm_dev_desc;
    s_tusb_cfg.descriptor.string = s_ncm_strings;
    s_tusb_cfg.descriptor.string_count = sizeof(s_ncm_strings) / sizeof(s_ncm_strings[0]);
    s_tusb_cfg.descriptor.full_speed_config = s_ncm_cfg_desc;
    esp_err_t err = tinyusb_driver_install(&s_tusb_cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "tinyusb install failed: %s", esp_err_to_name(err));
        return err;
    }

    /* 3. 初始化 NCM net：MAC 用 WiFi STA 的，桥接对电脑透明 */
    tinyusb_net_config_t net_cfg = {
        .mac_addr = {0},
        .on_recv_callback = ncm_recv_cb,
        .free_tx_buffer = ncm_free_tx_cb,
        /* 新版 TinyUSB 不调用 on_init_callback，改用 ncm_monitor_task 查 tud_mounted() */
        .on_init_callback = NULL,
        .user_context = NULL,
    };
    memcpy(net_cfg.mac_addr, s_sta_mac, 6);
    err = tinyusb_net_init(&net_cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "tinyusb_net_init failed: %s", esp_err_to_name(err));
        tinyusb_driver_uninstall();
        return err;
    }

    /* 4. 注册 WiFi RX 回调，开始桥接 */
    s_mounted = false;
    esp_wifi_internal_reg_rxcb(WIFI_IF_STA, wifi_rx_cb);

    s_active = true;
    ESP_LOGI(TAG, "USB 网络共享已启动（WiFi STA → USB NCM），等待电脑枚举");
    /* 5. 启动枚举状态监控（新版 TinyUSB 不触发 on_init_callback） */
    xTaskCreate(ncm_monitor_task, "ncm_mon", 2048, NULL, 2, &s_monitor_task);
    return ESP_OK;
}

esp_err_t usb_ncm_stop(void)
{
    if (!s_active) return ESP_OK;
    s_active = false;
    s_mounted = false;

    if (s_monitor_task) {
        vTaskDelete(s_monitor_task);
        s_monitor_task = NULL;
    }
    /* 恢复为只转本机 lwIP：绝不能设 NULL，否则 WiFi 包无人接收，设备永久断网 */
    esp_wifi_internal_reg_rxcb(WIFI_IF_STA, wifi_rx_lwip_only_cb);
    tinyusb_net_deinit();
    tinyusb_driver_uninstall();
    ESP_LOGI(TAG, "USB 网络共享已关闭");
    return ESP_OK;
}

bool usb_ncm_is_active(void) { return s_active; }
